--
-- Name: employment_changes_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_changes_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'employment_changes: evidence rows are immutable; record a new revision instead'
    USING ERRCODE = '23514';
  RETURN NULL;
END $$;


--
-- Name: FUNCTION employment_changes_immutable_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_changes_immutable_guard() IS 'openbooks:employment_changes_immutable_guard:v1 - evidence immutable; closure lives on version tables';


--
-- Name: employment_changes_provenance_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employment_changes_provenance_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE actual_employment uuid;
BEGIN
  IF NEW.assignment_id IS NOT NULL THEN
    SELECT employment_id INTO actual_employment FROM public.employment_assignments
      WHERE id = NEW.assignment_id AND org_id = NEW.org_id;
    IF actual_employment IS NULL THEN
      RAISE EXCEPTION 'employment_changes: assignment must exist in the same organization'
        USING ERRCODE = '23514';
    END IF;
    IF actual_employment IS DISTINCT FROM NEW.employment_id THEN
      RAISE EXCEPTION 'employment_changes: assignment must belong to the same employment'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.employment_changes c
                   WHERE c.id = NEW.supersedes_id AND c.org_id = NEW.org_id
                     AND c.employment_id = NEW.employment_id) THEN
      RAISE EXCEPTION 'employment_changes: supersedes_id must name evidence for the same employment'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION employment_changes_provenance_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employment_changes_provenance_guard() IS 'openbooks:employment_changes_provenance_guard:v1 - assignment and supersedes proven to the same employment';


