    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Published checklist versions are immutable. Publish a new revision instead.'; END $$;


--
-- Name: hrm_closure_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_closure_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  identity_col text := TG_ARGV[0];
  idcol_val uuid;
  ev_txid bigint;
  ev_array jsonb;
  succ_at timestamptz;
  succ_n integer;
  elem jsonb;
  elem_n integer;
  expected_before jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.superseded_by IS NULL THEN
      RETURN NULL;
    END IF;
  ELSIF OLD.superseded_by IS NOT NULL OR NEW.superseded_by IS NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.closed_by_change_id IS NULL THEN
    RAISE EXCEPTION '%: closing a version requires closed_by_change_id (the aggregate evidence event)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF identity_col = 'employment_id' THEN
    idcol_val := NEW.employment_id;
  ELSIF identity_col = 'assignment_id' THEN
    idcol_val := NEW.assignment_id;
  ELSE
    idcol_val := NEW.relationship_id;
  END IF;
  -- Real adjacent successor: exists, strictly newer, starts exactly here.
  -- PL/pgSQL EXECUTE never sets FOUND (docs 41.5.5 basic-statements), so the
  -- presence check reads ROW_COUNT: recorded_at is NOT NULL, but a NULL
  -- succ_at test would still be wrong (it confuses "no row" with data).
  EXECUTE format(
    'SELECT recorded_at FROM public.%I WHERE org_id = $1 AND %I = $2 AND version_no = $3',
    TG_TABLE_NAME, identity_col)
    INTO succ_at
    USING NEW.org_id, idcol_val, NEW.superseded_by;
  GET DIAGNOSTICS succ_n = ROW_COUNT;
  IF succ_n = 0 THEN
    RAISE EXCEPTION '%: superseded_by must name a real version_no of the same identity (no dangling pointers)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by <= NEW.version_no THEN
    RAISE EXCEPTION '%: successor version_no must be strictly newer (rejects self and backwards)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF succ_at IS DISTINCT FROM NEW.recorded_until THEN
    RAISE EXCEPTION '%: successor recorded_at must equal the closed recorded_until (seamless handoff, no gap or overlap)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  -- Same-transaction aggregate event naming this exact closure. Plain
  -- SELECT ... INTO sets FOUND (unlike EXECUTE above), so IF NOT FOUND is
  -- correct here.
  SELECT c.change_txid, c.closed_versions INTO ev_txid, ev_array
    FROM public.employment_changes c
   WHERE c.id = NEW.closed_by_change_id AND c.org_id = NEW.org_id
     AND c.employment_id = NEW.employment_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION '%: closed_by_change_id must name an evidence event for the same employment', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF ev_txid IS DISTINCT FROM txid_current() THEN
    RAISE EXCEPTION '%: closure evidence must be written in the same transaction (change_txid must equal txid_current())', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  -- Exactly one element must name this closure: zero means the event does
  -- not evidence this close; two or more means the array double-counts one
  -- row and no single before-image can be authoritative. SELECT ... INTO
  -- would silently take the first of several, so count first.
  SELECT count(*) INTO elem_n FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', TG_TABLE_NAME::text, 'identity', idcol_val::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text);
  IF elem_n = 0 THEN
    RAISE EXCEPTION '%: evidence event must name this exact closure (table, identity, version_no, row_id) in closed_versions', TG_TABLE_NAME
      USING ERRCODE = '23514';
  ELSIF elem_n > 1 THEN
    RAISE EXCEPTION '%: evidence event names this closure more than once (duplicate closed_versions entries)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  SELECT e INTO elem FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', TG_TABLE_NAME::text, 'identity', idcol_val::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text)
   LIMIT 1;
  -- Exact prior image, full row, no column subtracted: on UPDATE the element
  -- must carry OLD as it stood before this close. The closing transition
  -- only ever fires from a live row, so OLD's closing columns are NULL on
  -- both sides, and the volatile audit columns are OLD's own prior touch —
  -- nothing needs excluding and the comment cannot overclaim. On INSERT of
  -- an already-closed row there is no OLD: the element must carry NEW as
  -- written (imported-image semantics, clearly separated from UPDATE).
  -- Key-only matching would admit forged history with the right identifiers.
  IF TG_OP = 'INSERT' THEN
    expected_before := to_jsonb(NEW);
  ELSE
    expected_before := to_jsonb(OLD);
  END IF;
  IF NOT (elem ? 'before') OR (elem->'before' IS DISTINCT FROM expected_before) THEN
    RAISE EXCEPTION '%: evidence event must carry the exact before-image of this closure in closed_versions[].before', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $_$;


--
-- Name: FUNCTION hrm_closure_evidence_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hrm_closure_evidence_guard() IS 'openbooks:hrm_closure_evidence_guard:v1 - deferred proof per closure: adjacent strictly-newer successor (ROW_COUNT presence) plus same-transaction aggregate event (txid-stamped) naming the exact row with its exact before-image';


--
-- Name: hrm_comp_criteria_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_comp_criteria_valid(criteria jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_typeof(criteria) = 'array'
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(criteria) AS c(elem)
        WHERE jsonb_typeof(c.elem) <> 'object'
           OR NOT (c.elem ? 'criterion')
           OR NOT (c.elem ? 'weight')
           OR NOT (c.elem ->> 'criterion' IN ('skills', 'effort', 'responsibility', 'working_conditions'))
     )
$$;


--
-- Name: hrm_comp_cycle_lines_budget_freeze_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_comp_cycle_lines_budget_freeze_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.cycle_id IS DISTINCT FROM OLD.cycle_id
     OR NEW.employment_id IS DISTINCT FROM OLD.employment_id
     OR NEW.current_rate IS DISTINCT FROM OLD.current_rate
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.basis IS DISTINCT FROM OLD.basis
     OR NEW.budget_pricing_date IS DISTINCT FROM OLD.budget_pricing_date
     OR NEW.budget_cycle_currency IS DISTINCT FROM OLD.budget_cycle_currency
     OR NEW.budget_envelope IS DISTINCT FROM OLD.budget_envelope
     OR NEW.budget_annual_hours IS DISTINCT FROM OLD.budget_annual_hours
     OR NEW.budget_fx_rate IS DISTINCT FROM OLD.budget_fx_rate
     OR NEW.budget_fx_asof IS DISTINCT FROM OLD.budget_fx_asof
     OR NEW.budget_fx_source IS DISTINCT FROM OLD.budget_fx_source
     OR NEW.budget_fx_inverse IS DISTINCT FROM OLD.budget_fx_inverse THEN
    RAISE EXCEPTION
      'hrm_comp_cycle_lines budget evidence is frozen at open: cycle_id, employment_id, current_rate, currency, basis and the budget_* inputs of line % cannot be changed — carry the adjustment into a new cycle',
      OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hrm_comp_cycles_budget_header_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_comp_cycles_budget_header_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- The lifecycle never rewinds to draft: no service path moves a live
  -- round back, so a status reset cannot regain draft-edit privileges.
  IF OLD.status <> 'draft' AND NEW.status = 'draft' THEN
    RAISE EXCEPTION
      'hrm_comp_cycles lifecycle moves forward only: cycle % left draft and cannot return — open a new round instead',
      OLD.id;
  END IF;
  -- Drafts with no lines correct freely; once the round opens — or any
  -- line exists to carry its copies — the header stays put in every
  -- later state (open, in_review, approved, pushed, closed, cancelled).
  IF (OLD.status <> 'draft'
      OR EXISTS (SELECT 1 FROM public.hrm_comp_cycle_lines l WHERE l.cycle_id = OLD.id))
     AND (NEW.effective_on IS DISTINCT FROM OLD.effective_on
       OR NEW.currency IS DISTINCT FROM OLD.currency
       OR NEW.budget_total IS DISTINCT FROM OLD.budget_total
       OR NEW.budget_basis IS DISTINCT FROM OLD.budget_basis) THEN
    RAISE EXCEPTION
      'hrm_comp_cycles budget header is frozen at open: effective_on, currency, budget_total and budget_basis of cycle % cannot be changed — open a new round instead',
      OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: hrm_compensation_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_compensation_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  changed text[];
BEGIN
  IF TG_TABLE_NAME = 'hrm_comp_events' THEN
    -- The event ledger is evidence: updates refused on every path, deletes
    -- only on the governed amend path — record a new event instead of
    -- editing one.
    IF TG_OP = 'UPDATE' THEN
      RAISE EXCEPTION 'openbooks:immutable_evidence: % rows are append-only — record a new event instead of editing one', TG_TABLE_NAME
        USING ERRCODE = '25001';
    END IF;
    IF TG_OP = 'DELETE'
       AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path', TG_TABLE_NAME
        USING ERRCODE = '25001';
    END IF;
    RETURN OLD;
  END IF;
  -- Versioned SHOULD-pay rows and decided cycle lines are history once
  -- superseded/decided: terminal rows are immutable except a pure audit
  -- touch (updated_at/updated_by), exactly like 0195 terminal rows.
  IF TG_OP = 'DELETE'
     AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path — retire by closing, never by deleting', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    -- One branch per table: PL/pgSQL does not short-circuit AND, so a
    -- shared predicate touching OLD.effective_to would fail on tables
    -- without that column. Each branch names only its own columns.
    IF TG_TABLE_NAME = 'hrm_pay_bands' THEN
      IF OLD.effective_to IS NOT NULL THEN
        changed := ARRAY(
          SELECT key FROM jsonb_each(to_jsonb(NEW)) AS n(key, value)
          WHERE (to_jsonb(OLD) -> n.key) IS DISTINCT FROM n.value);
        changed := ARRAY(SELECT c FROM unnest(changed) AS c WHERE c NOT IN ('updated_at', 'updated_by'));
        IF cardinality(changed) > 0 THEN
          RAISE EXCEPTION 'openbooks:immutable_evidence: a closed pay band is history — open a new version instead of editing %', array_to_string(changed, ', ')
            USING ERRCODE = '25001';
        END IF;
      END IF;
    ELSIF TG_TABLE_NAME = 'hrm_comp_cycle_lines' THEN
      IF OLD.status IN ('approved', 'rejected', 'pushed') THEN
        changed := ARRAY(
          SELECT key FROM jsonb_each(to_jsonb(NEW)) AS n(key, value)
          WHERE (to_jsonb(OLD) -> n.key) IS DISTINCT FROM n.value);
        changed := ARRAY(SELECT c FROM unnest(changed) AS c
          WHERE c NOT IN ('updated_at', 'updated_by', 'status', 'approver_party_id', 'decided_at', 'reason', 'pushed_rate_id', 'revision'));
        IF OLD.status = 'pushed' AND (to_jsonb(NEW) ->> 'status') IS DISTINCT FROM 'pushed' THEN
          RAISE EXCEPTION 'openbooks:immutable_evidence: a pushed line already moved payroll — reverse through a new cycle, never by reopening'
            USING ERRCODE = '25001';
        END IF;
        IF cardinality(changed) > 0 THEN
          RAISE EXCEPTION 'openbooks:immutable_evidence: a decided line is evidence — reopen it through the service instead of editing %', array_to_string(changed, ', ')
            USING ERRCODE = '25001';
        END IF;
      END IF;
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: hrm_compensation_plans_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_compensation_plans_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- A published equity figure is evidence, not a draft: updates refused on
  -- every path, deletes only on the governed amend path — compute a new
  -- snapshot instead of editing one.
  IF TG_TABLE_NAME = 'hrm_pay_gap_snapshots' AND TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows are frozen — compute a new snapshot instead of editing one', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  IF TG_OP = 'DELETE'
     AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: hrm_compliance_findings_no_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_compliance_findings_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION
    'HRM compliance finding % is append-only audit evidence — acknowledge or resolve it instead of deleting it.', OLD.id;
END;
$$;


--
-- Name: hrm_documents_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_documents_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  changed text[];
BEGIN
  -- Retention actions close exactly once: an open row (executed_at null)
  -- may set executed_at/executed_by (the execution) or blocked_reason
  -- (the legal-hold block). An executed row is history — like the 0226
  -- run log, which closes queued/running runs but never edits terminal
  -- ones. Events and responses allow no update at all.
  IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'hrm_retention_actions' THEN
    IF OLD.executed_at IS NOT NULL THEN
      RAISE EXCEPTION 'openbooks:immutable_evidence: an executed retention action is history — record a new action instead of editing %', OLD.id
        USING ERRCODE = '25001';
    END IF;
    changed := ARRAY(
      SELECT key FROM jsonb_each(to_jsonb(NEW)) AS n(key, value)
      WHERE (to_jsonb(OLD) -> n.key) IS DISTINCT FROM n.value);
    changed := ARRAY(SELECT c FROM unnest(changed) AS c WHERE c NOT IN ('executed_at', 'executed_by', 'blocked_reason'));
    IF cardinality(changed) > 0 THEN
      RAISE EXCEPTION 'openbooks:immutable_evidence: an open retention action closes or blocks — it never edits %', array_to_string(changed, ', ')
        USING ERRCODE = '25001';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows are append-only — record a new row instead of editing one', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  IF TG_OP = 'DELETE'
     AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: hrm_employment_change_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_employment_change_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  computed_digest text;
  run_org uuid;
  run_kind text;
  run_subject uuid;
  change_org uuid;
  change_employment uuid;
  change_revision integer;
BEGIN
  -- Canonical digest over the exact bytes of the jsonb normalized text
  -- form. Storage computes; callers never supply a trusted digest.
  computed_digest :=
    encode(digest(convert_to(NEW.payload::text, 'UTF8'), 'sha256'), 'hex');

  IF TG_OP = 'INSERT' THEN
    -- OM-13c clone replay: the sandbox/sample-company clone replays
    -- immutable terminal history verbatim under the clone authority (0316:
    -- openbooks.clone with openbooks.migration and openbooks.amend asserted
    -- together inside runClone's own RLS-bypass maintenance transaction).
    -- Admit that replayed INSERT — the digest is still recomputed in
    -- storage below — while every ordinary session keeps the born-draft
    -- refusals that follow. UPDATE and DELETE of this history stay blocked:
    -- this admission returns only on the INSERT path.
    IF public.openbooks_clone_authority() THEN
      NEW.payload_digest := computed_digest;
      RETURN NEW;
    END IF;
    -- Rows are born drafts. A forged submission (pending_approval with a
    -- run, a snapshot, or submission stamps on insert) is refused: submit
    -- through the draft -> pending_approval transition instead.
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION
        'HRM change request must be inserted as draft, then submitted — insert with status % is refused.', NEW.status;
    END IF;
    IF NEW.submitted_at IS NOT NULL OR NEW.submitted_by IS NOT NULL THEN
      RAISE EXCEPTION
        'HRM change request must be inserted unsubmitted — submit through the draft -> pending_approval transition instead.';
    END IF;
    IF NEW.flow_run_id IS NOT NULL THEN
      RAISE EXCEPTION
        'HRM change request must be inserted without a flow run — the run is stamped at submit instead.';
    END IF;
    IF NEW.decision_snapshot IS NOT NULL THEN
      RAISE EXCEPTION
        'HRM change request must be inserted without a decision snapshot — it is written atomically with approve/reject instead.';
    END IF;
    IF NEW.applied_at IS NOT NULL OR NEW.applied_by IS NOT NULL
       OR NEW.applied_employment_revision IS NOT NULL
       OR NEW.applied_employment_change_id IS NOT NULL THEN
      RAISE EXCEPTION
        'HRM change request must be inserted unapplied — application evidence is stamped on approved -> applied instead.';
    END IF;
    NEW.payload_digest := computed_digest;
    RETURN NEW;
  END IF;

  -- Identity and creator are frozen from insert, even in draft: a proposal
  -- about another employment is a new request, not an edit. The row id and
  -- creation timestamp are frozen with them — history must not be re-keyed
  -- or re-dated.
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.employment_id IS DISTINCT FROM OLD.employment_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION
      'HRM change request identity (id, org, employment, created_at, creator) is immutable — file a new request instead.';
  END IF;

  -- Payload/digest/schema-version/expected-revision live only in draft.
  -- Draft payload edits recompute the digest in storage; anything else
  -- attempting a silent re-point is refused.
  IF NEW.payload IS DISTINCT FROM OLD.payload
     OR NEW.payload_schema_version IS DISTINCT FROM OLD.payload_schema_version
     OR NEW.expected_employment_revision IS DISTINCT FROM OLD.expected_employment_revision THEN
    IF OLD.status <> 'draft' OR NEW.status <> 'draft' THEN
      RAISE EXCEPTION
        'HRM change request payload, schema version, and expected revision freeze on submit — file a new request for a revised proposal instead.';
    END IF;
    NEW.payload_digest := computed_digest;
  ELSIF NEW.payload_digest IS DISTINCT FROM OLD.payload_digest THEN
    RAISE EXCEPTION
      'HRM change request digest is storage-computed and immutable outside draft payload edits — it cannot be re-pointed.';
  END IF;

  -- Draft edits advance the request revision by exactly one; submitted rows
  -- never move it (resubmission is a new request, not a revision bump).
  IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
    IF NEW.payload IS NOT DISTINCT FROM OLD.payload
       AND NEW.payload_schema_version IS NOT DISTINCT FROM OLD.payload_schema_version
       AND NEW.expected_employment_revision IS NOT DISTINCT FROM OLD.expected_employment_revision
       AND NEW.reason IS NOT DISTINCT FROM OLD.reason THEN
      -- Touch-only update (e.g. updated_at): revision stays put.
      IF NEW.request_revision IS DISTINCT FROM OLD.request_revision THEN
        RAISE EXCEPTION
          'HRM change request revision moves only with a draft edit, by exactly one — leave request_revision alone on a touch update.';
      END IF;
    ELSIF NEW.request_revision <> OLD.request_revision + 1 THEN
      RAISE EXCEPTION
        'HRM change request draft edits advance request_revision by exactly one (was %, got %) — do not skip or reuse revisions.', OLD.request_revision, NEW.request_revision;
    END IF;
  ELSIF NEW.request_revision IS DISTINCT FROM OLD.request_revision THEN
    RAISE EXCEPTION
      'HRM change request revision freezes on submit — file a new request for a revised proposal instead.';
  END IF;

  -- Lifecycle transitions. Terminal states never leave; rejected and
  -- withdrawn never resurrect (a revised proposal is a new request, so an
  -- old approval can never be re-pointed at it).
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'draft' AND NEW.status NOT IN ('pending_approval', 'withdrawn') THEN
      RAISE EXCEPTION
        'HRM change request draft must submit (pending_approval) or withdraw — transition to % is refused.', NEW.status;
    ELSIF OLD.status = 'pending_approval'
            AND NEW.status NOT IN ('approved', 'rejected', 'withdrawn') THEN
      RAISE EXCEPTION
        'HRM change request awaiting approval resolves to approved, rejected, or withdrawn — transition to % is refused.', NEW.status;
    ELSIF OLD.status = 'approved' AND NEW.status <> 'applied' THEN
      RAISE EXCEPTION
        'HRM change request approved resolves only to applied — transition to % is refused. Withdraw or reject before approval instead.', NEW.status;
    ELSIF OLD.status IN ('rejected', 'withdrawn', 'applied') THEN
      RAISE EXCEPTION
        'HRM change request % is terminal — file a new request for a revised proposal instead.', OLD.status;
    END IF;
  END IF;

  -- Submission stamps are set once, on submit, and never re-pointed. A
  -- bare flip to pending_approval without them is refused here with a
  -- named remedy (the presence CHECKs backstop the same rule).
  IF OLD.status = 'draft' AND NEW.status = 'pending_approval' THEN
    IF NEW.submitted_at IS NULL OR NEW.submitted_by IS NULL
       OR NEW.flow_run_id IS NULL THEN
      RAISE EXCEPTION
        'HRM change request submit stamps submission actor/time and the native flow run atomically — set submitted_by, submitted_at, and flow_run_id in the same update instead.';
    END IF;
    IF NEW.reason IS NULL OR length(btrim(NEW.reason)) = 0 THEN
      RAISE EXCEPTION
        'HRM change request submit carries a non-blank reason — record why the change is proposed instead.';
    END IF;
  END IF;
  IF OLD.submitted_at IS NULL AND NEW.submitted_at IS NOT NULL THEN
    IF OLD.status <> 'draft' OR NEW.status <> 'pending_approval' THEN
      RAISE EXCEPTION
        'HRM change request submission stamps are set only on draft -> pending_approval — submit through that transition instead.';
    END IF;
  ELSIF NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
        OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by THEN
    RAISE EXCEPTION
      'HRM change request submission actor and time are immutable once set — they record what was submitted, not what is convenient.';
  END IF;

  -- Submission reason is submission evidence: frozen once submitted.
  IF OLD.submitted_at IS NOT NULL AND NEW.reason IS DISTINCT FROM OLD.reason THEN
    RAISE EXCEPTION
      'HRM change request reason freezes on submit — record later rationale in the audit trail, not on the request.';
  END IF;

  -- The native run anchor is stamped at submit, verified against the live
  -- native run (same org, governed subject kind/id), and never re-pointed.
  IF NEW.flow_run_id IS DISTINCT FROM OLD.flow_run_id THEN
    IF OLD.flow_run_id IS NOT NULL THEN
      RAISE EXCEPTION
        'HRM change request flow run is retained once stamped — it cannot be re-pointed to another run.';
    END IF;
    IF NEW.flow_run_id IS NULL THEN
      RAISE EXCEPTION
        'HRM change request flow run cannot be cleared once stamped — it is retained as approval evidence.';
    END IF;
  END IF;
  IF NEW.flow_run_id IS NOT NULL THEN
    SELECT org_id, subject_kind, subject_id
      INTO run_org, run_kind, run_subject
      FROM public.flow_runs WHERE id = NEW.flow_run_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'HRM change request flow run % does not exist — submit against a live native run instead.', NEW.flow_run_id;
    END IF;
    IF run_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION
        'HRM change request flow run % belongs to another organization — submit against a run in this organization instead.', NEW.flow_run_id;
    END IF;
    IF run_kind <> 'hrm_employment_change_request' OR run_subject IS DISTINCT FROM NEW.id THEN
      RAISE EXCEPTION
        'HRM change request flow run % is not opened for this request (kind %, subject %) — open the governed HRM approval run for this request instead.', NEW.flow_run_id, run_kind, run_subject;
    END IF;
  END IF;

  -- Decision snapshot is written once, atomically with approve/reject, and
  -- frozen forever (the binding CHECK pins its keys to the row).
  IF NEW.decision_snapshot IS DISTINCT FROM OLD.decision_snapshot THEN
    IF OLD.decision_snapshot IS NOT NULL THEN
      RAISE EXCEPTION
        'HRM change request decision snapshot is immutable once written — it records the decision that was made, not the one wanted.';
    END IF;
    IF NOT (OLD.status = 'pending_approval' AND NEW.status IN ('approved', 'rejected')) THEN
      RAISE EXCEPTION
        'HRM change request decision snapshot is written only on pending_approval -> approved/rejected — decide through that transition instead.';
    END IF;
  END IF;

  -- Application evidence lands atomically with approved -> applied, linked
  -- to a live canonical change in this org. applied_by stays evidence:
  -- this trigger authenticates nothing about the application user.
  IF NEW.applied_employment_change_id IS DISTINCT FROM OLD.applied_employment_change_id THEN
    IF NOT (OLD.status = 'approved' AND NEW.status = 'applied') THEN
      RAISE EXCEPTION
        'HRM change request application evidence is stamped only on approved -> applied — apply through that transition instead.';
    END IF;
  END IF;
  IF NEW.status = 'applied' AND OLD.status = 'approved' THEN
    SELECT org_id, employment_id, revision
      INTO change_org, change_employment, change_revision
      FROM public.employment_changes WHERE id = NEW.applied_employment_change_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'HRM change request applied change % does not exist — apply against the canonical change the approval produced instead.', NEW.applied_employment_change_id;
    END IF;
    IF change_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION
        'HRM change request applied change % belongs to another organization — apply against a change in this organization instead.', NEW.applied_employment_change_id;
    END IF;
    IF change_employment IS DISTINCT FROM NEW.employment_id THEN
      RAISE EXCEPTION
        'HRM change request applied change % is recorded against another employment — apply against the canonical change for this employment instead.', NEW.applied_employment_change_id;
    END IF;
    IF change_revision IS DISTINCT FROM NEW.applied_employment_revision THEN
      RAISE EXCEPTION
        'HRM change request applied change % carries revision %, not the applied revision % — stamp the exact canonical revision the approval produced instead.', NEW.applied_employment_change_id, change_revision, NEW.applied_employment_revision;
    END IF;
  END IF;
  IF (OLD.status = 'applied')
     AND (NEW.applied_at IS DISTINCT FROM OLD.applied_at
          OR NEW.applied_by IS DISTINCT FROM OLD.applied_by
          OR NEW.applied_employment_revision IS DISTINCT FROM OLD.applied_employment_revision
          OR NEW.applied_employment_change_id IS DISTINCT FROM OLD.applied_employment_change_id) THEN
    RAISE EXCEPTION
      'HRM change request application evidence is immutable once applied — a second application is a duplicate, not an update.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: hrm_employment_change_request_no_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_employment_change_request_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Governed amend path (fixture teardown, sandbox wipe, org purge). Without
  -- it a submitted request pins its organisation forever.
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF OLD.submitted_at IS NOT NULL THEN
    RAISE EXCEPTION
      'HRM change request % was submitted and is retained as history — terminal rows (approved, rejected, applied) cannot be withdrawn; file a new request for a revised proposal instead of deleting it.', OLD.id;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: hrm_evidence_closure_reverse_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_evidence_closure_reverse_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  elem jsonb;
  tbl text;
  idcol text;
  row_n integer;
BEGIN
  -- Governed amend path (fixture teardown, historical replay): the existing
  -- house mechanism, never a production bypass.
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NULL;
  END IF;
  FOR elem IN SELECT * FROM jsonb_array_elements(NEW.closed_versions) LOOP
    tbl := elem->>'table';
    IF tbl = 'worker_employment_versions' THEN
      idcol := 'employment_id';
    ELSIF tbl = 'employment_assignment_versions' THEN
      idcol := 'assignment_id';
    ELSIF tbl = 'reporting_relationships' THEN
      idcol := 'relationship_id';
    ELSE
      RAISE EXCEPTION 'employment_changes: closed_versions element names an unknown closure table %', tbl
        USING ERRCODE = '23514';
    END IF;
    IF jsonb_typeof(elem->'before') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'employment_changes: closed_versions element for % must carry a before-image object', tbl
        USING ERRCODE = '23514';
    END IF;
    -- count(*) always returns exactly one row, so INTO needs no FOUND dance.
    EXECUTE format(
      'SELECT count(*) FROM public.%I
        WHERE id = $1 AND org_id = $2 AND %I = $3 AND version_no = $4
          AND employment_id = $5
          AND superseded_by IS NOT NULL AND closed_by_change_id = $6',
      tbl, idcol)
      INTO row_n
      USING (elem->>'row_id')::uuid, NEW.org_id, (elem->>'identity')::uuid,
            (elem->>'version_no')::int, NEW.employment_id, NEW.id;
    IF row_n <> 1 THEN
      RAISE EXCEPTION 'employment_changes: closed_versions element must name a real closed row of this employment linked back to this event (table %, identity %)', tbl, elem->>'identity'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END $_$;


--
-- Name: FUNCTION hrm_evidence_closure_reverse_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hrm_evidence_closure_reverse_guard() IS 'openbooks:hrm_evidence_closure_reverse_guard:v1 - deferred reverse proof per event: every closed_versions element names exactly one really-closed row of this employment linked back to this event';


