--

COMMENT ON FUNCTION public.hrm_recruiting_history_guard() IS 'openbooks:hrm_recruiting_history_guard:v1 - terminal applications, interviews and offers immutable except a pure audit touch; deletes only on the governed amend path';


--
-- Name: hrm_reporting_no_cycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hrm_reporting_no_cycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  found_cycle boolean;
  max_depth integer;
  bump_n integer;
BEGIN
  IF NEW.kind <> 'line' OR NEW.superseded_by IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- Proven serialization FIRST (see hrm_graph_revisions): bump before any
  -- table read, so the walk below never runs on a stale snapshot.
  -- The seed INSERT is benign initialization only, never the proof:
  -- concurrent first-writes to a fresh org race to plant the rev = 0 row;
  -- the loser does nothing and BOTH proceed to the UPDATE below, which
  -- serializes them on the row lock. The seed carries no product data, so
  -- DO NOTHING can never silently disable the walk — the exact-row
  -- assertion after the UPDATE is what keeps a skipped bump loud.
  INSERT INTO public.hrm_graph_revisions AS g (org_id, rev)
    VALUES (NEW.org_id, 0)
    ON CONFLICT (org_id) DO NOTHING;
  UPDATE public.hrm_graph_revisions SET rev = rev + 1, updated_at = now()
    WHERE org_id = NEW.org_id;
  GET DIAGNOSTICS bump_n = ROW_COUNT;
  IF bump_n <> 1 THEN
    RAISE EXCEPTION 'reporting_relationships: graph-revision bump must hit exactly one row (an RLS-hidden row is a serialization failure, never a skip)'
      USING ERRCODE = '23514';
  END IF;
  WITH RECURSIVE walk(emp, wfrom, wto, depth, path) AS (
    SELECT NEW.manager_employment_id, NEW.effective_from, NEW.effective_to, 1,
           ARRAY[NEW.employment_id, NEW.manager_employment_id]
    UNION
    SELECT r.manager_employment_id,
           GREATEST(r.effective_from, w.wfrom),
           CASE WHEN r.effective_to IS NULL THEN w.wto
                WHEN w.wto IS NULL THEN r.effective_to
                WHEN r.effective_to < w.wto THEN r.effective_to
                ELSE w.wto END,
           w.depth + 1,
           w.path || r.manager_employment_id
      FROM public.reporting_relationships r
      JOIN walk w ON r.org_id = NEW.org_id
       AND r.employment_id = w.emp
       AND r.kind = 'line'
       AND r.superseded_by IS NULL
       AND r.id IS DISTINCT FROM NEW.id
       AND daterange(r.effective_from, COALESCE(r.effective_to, 'infinity'::date), '[)')
         && daterange(w.wfrom, COALESCE(w.wto, 'infinity'::date), '[)')
       AND w.depth < 65
       AND NOT (r.manager_employment_id = ANY (w.path)
                AND r.manager_employment_id <> NEW.employment_id)
  )
  SELECT COALESCE((SELECT true FROM walk WHERE emp = NEW.employment_id LIMIT 1), false),
         COALESCE((SELECT MAX(depth) FROM walk), 0)
    INTO found_cycle, max_depth;
  IF found_cycle THEN
    RAISE EXCEPTION 'reporting_relationships: line reporting creates a management cycle'
      USING ERRCODE = '23514';
  END IF;
  IF max_depth >= 65 THEN
    RAISE EXCEPTION 'reporting_relationships: chain reaches 65 edges; refused, not validated'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION hrm_reporting_no_cycle(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hrm_reporting_no_cycle() IS 'openbooks:hrm_reporting_no_cycle:v1 - storage backstop for the canonical manager-cycle service; all live line paths with window intersection, per-org graph-revision write before first read, 65-edge refusal';


