--
-- Name: journal_lines_lock_nonprofit_framework(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_lines_lock_nonprofit_framework() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(new.extra_dims, '{}'::jsonb) ? 'fund' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || new.org_id::text, 0)
    );
  end if;
  return new;
end $$;


--
-- Name: journal_primary_book_history_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_primary_book_history_fence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  primary_ids uuid[];
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN new;
  END IF;
  SELECT array_agg(id) INTO primary_ids FROM (
    SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
      ORDER BY id FOR SHARE
  ) authority;
  -- A concurrent empty-org promotion can demote the row seen by the first
  -- statement while its lock waits. Take a fresh READ COMMITTED snapshot to
  -- resolve the successor, instead of proceeding without an authority fence.
  IF coalesce(cardinality(primary_ids), 0) = 0 THEN
    SELECT array_agg(id) INTO primary_ids FROM (
      SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
        ORDER BY id FOR SHARE
    ) authority;
  END IF;
  IF coalesce(cardinality(primary_ids), 0) <> 1 THEN
    RAISE EXCEPTION 'accounting history creation requires exactly one primary accounting book'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: FUNCTION journal_primary_book_history_fence(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.journal_primary_book_history_fence() IS 'openbooks:journal_primary_book_history_fence:v1 - first journal creation retains the primary book row through commit, serializing SQL and secondary-book history with book reassignment';


--
-- Name: landed_cost_allocation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'landed-cost allocation evidence is append-only';
  END IF;
  IF OLD.journal_entry_id IS NULL
     AND NEW.journal_entry_id IS NOT NULL
     AND (to_jsonb(NEW) - 'journal_entry_id' - 'updated_at' - 'updated_by')
       = (to_jsonb(OLD) - 'journal_entry_id' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'landed-cost allocation evidence is immutable';
END
$$;


--
-- Name: landed_cost_voucher_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_voucher_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'posted landed-cost vouchers cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;
  IF OLD.status = 'posted'
     AND NEW.status = 'void'
     AND NEW.org_id = OLD.org_id
     AND NEW.document_number = OLD.document_number
     AND NEW.amount = OLD.amount
     AND NEW.basis = OLD.basis
     AND NEW.freight_account_id = OLD.freight_account_id
     AND NEW.source_document_line_id IS NOT DISTINCT FROM OLD.source_document_line_id
     AND NEW.subsidiary_id = OLD.subsidiary_id
     AND NEW.voucher_date = OLD.voucher_date
     AND NEW.journal_entry_id = OLD.journal_entry_id
     AND NEW.memo IS NOT DISTINCT FROM OLD.memo
     AND NEW.created_at = OLD.created_at
     AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
     AND NEW.reversal_journal_entry_id IS NOT NULL
     AND NEW.voided_at IS NOT NULL
     AND NEW.voided_by IS NOT NULL
     AND length(btrim(NEW.void_reason)) BETWEEN 5 AND 500 THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'posted and void landed-cost vouchers are immutable';
END
$$;


--
-- Name: landed_cost_voucher_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_voucher_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_status text;
  parent_org uuid;
BEGIN
  SELECT status, org_id
    INTO parent_status, parent_org
    FROM landed_cost_vouchers
   WHERE id = coalesce(NEW.voucher_id, OLD.voucher_id);
  IF TG_OP = 'DELETE' AND parent_status IS NULL THEN RETURN OLD; END IF;
  IF parent_status IS NULL
     OR parent_org IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'landed-cost target must reference a tenant-owned voucher';
  END IF;
  IF parent_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of a posted landed-cost voucher are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: layer_consumption_fill_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.layer_consumption_fill_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.issue_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'cost layer consumption requires the legal entity of its issue movement',
      DETAIL = 'The issue movement was not found, so ownership could not be derived.',
      HINT = 'Create the issue movement before recording its consumptions.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$$;


--
-- Name: lease_agreement_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_agreement_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.status<>'draft' THEN RAISE EXCEPTION 'commenced lease agreements are retained; use a termination or correcting change'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.org_id<>NEW.org_id OR OLD.subsidiary_id<>NEW.subsidiary_id OR OLD.id<>NEW.id THEN
    RAISE EXCEPTION 'lease organization and legal entity are immutable';
  END IF;
  IF OLD.status='draft' THEN RETURN NEW; END IF;
  IF (to_jsonb(NEW)-ARRAY['description','custom','updated_at','updated_by']) IS NOT DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['description','custom','updated_at','updated_by']) THEN RETURN NEW; END IF;
  IF NEW.revision<>OLD.revision+1 OR NEW.last_change_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM financial_changes c WHERE c.id=NEW.last_change_id AND c.org_id=NEW.org_id
      AND c.domain='lease' AND c.subject_id=NEW.id AND c.status='approved') THEN
    RAISE EXCEPTION 'changing a commenced lease requires an approved accounting change and a new revision';
  END IF;
  IF NEW.initial_liability IS DISTINCT FROM OLD.initial_liability OR NEW.initial_rou_asset IS DISTINCT FROM OLD.initial_rou_asset
     OR NEW.commencement_entry_id IS DISTINCT FROM OLD.commencement_entry_id OR NEW.commencement_on<>OLD.commencement_on
     OR NEW.book_id IS DISTINCT FROM OLD.book_id OR NEW.currency IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION 'lease commencement history is immutable';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: lease_charges_base_rent_repair(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_charges_base_rent_repair() RETURNS TABLE(windows_closed integer, shadows_deleted integer, lines_cancelled integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_conflict record;
  v_older_billed integer;
  v_newer_billed integer;
  v_windows_closed integer := 0;
  v_shadows_deleted integer := 0;
  v_lines_cancelled integer := 0;
BEGIN
  -- Resolve one chronologically-first conflict per pass so every decision
  -- sees the state the previous one produced (0051 ownership-repair pattern).
  LOOP
    SELECT first_charge.id AS older_id, second_charge.id AS newer_id,
           second_charge.effective_from AS newer_from,
           second_charge.effective_from > first_charge.effective_from AS distinct_start
      INTO v_conflict
      FROM public.lease_charges first_charge
      JOIN public.lease_charges second_charge
        ON second_charge.org_id = first_charge.org_id
       AND second_charge.lease_id = first_charge.lease_id
       AND second_charge.charge_type = 'base_rent'
       AND (second_charge.effective_from, second_charge.id) > (first_charge.effective_from, first_charge.id)
     WHERE first_charge.charge_type = 'base_rent'
       AND coalesce(first_charge.effective_to, 'infinity'::date) >= second_charge.effective_from
     ORDER BY first_charge.lease_id, second_charge.effective_from, second_charge.id, first_charge.id
     LIMIT 1;
    EXIT WHEN NOT FOUND;

    IF v_conflict.distinct_start THEN
      -- Distinct starts: the successor supersedes.  Close the older window the
      -- day before the successor begins — exactly what applying an escalation
      -- already does to the canon.
      UPDATE public.lease_charges
         SET effective_to = v_conflict.newer_from - 1, updated_at = now()
       WHERE id = v_conflict.older_id;
      v_windows_closed := v_windows_closed + 1;

      -- Retire the older row's unbilled future coverage that no longer has a
      -- contractual window, keeping every invoiced line as history.
      WITH cancelled AS (
        UPDATE public.lease_schedule_lines s
           SET status = 'cancelled', updated_at = now()
          FROM public.lease_charges c
         WHERE c.id = v_conflict.older_id
           AND s.org_id = c.org_id
           AND s.charge_id = c.id
           AND s.status = 'scheduled'
           AND s.period_starts_on >= v_conflict.newer_from
        RETURNING s.id
      )
      -- This is the corrective behavior: each conflict contributes to the
      -- running total instead of replacing the prior pass's count.
      SELECT v_lines_cancelled + count(*) INTO v_lines_cancelled FROM cancelled;

      UPDATE public.lease_schedule_lines s
         SET period_ends_on = v_conflict.newer_from - 1,
             amount = round((s.amount * ((v_conflict.newer_from - 1 - s.period_starts_on + 1)::numeric
                                         / (s.period_ends_on - s.period_starts_on + 1))), 4),
             updated_at = now()
       WHERE s.charge_id = v_conflict.older_id
         AND s.org_id = (SELECT org_id FROM public.lease_charges WHERE id = v_conflict.older_id)
         AND s.status = 'scheduled'
         AND s.period_starts_on < v_conflict.newer_from
         AND s.period_ends_on >= v_conflict.newer_from;
    ELSE
      -- Same-start duplicates: only one row may own the shared window. Billed
      -- history always wins; ties fall to the newest row (uuidv7 ids sort by
      -- creation time), as 0051 kept shadow duplicates.
      SELECT
        count(*) FILTER (WHERE s.status IN ('invoiced', 'credited') AND c.id = v_conflict.older_id),
        count(*) FILTER (WHERE s.status IN ('invoiced', 'credited') AND c.id = v_conflict.newer_id)
        INTO v_older_billed, v_newer_billed
        FROM (VALUES (v_conflict.older_id), (v_conflict.newer_id)) AS pair(id)
        JOIN public.lease_charges c ON c.id = pair.id
        LEFT JOIN public.lease_schedule_lines s ON s.charge_id = c.id AND s.org_id = c.org_id;

      DECLARE
        v_loser uuid := CASE WHEN v_older_billed > v_newer_billed THEN v_conflict.newer_id ELSE v_conflict.older_id END;
        v_loser_lines integer;
      BEGIN
        SELECT count(*) INTO v_loser_lines
          FROM public.lease_schedule_lines
         WHERE charge_id = v_loser
           AND org_id = (SELECT org_id FROM public.lease_charges WHERE id = v_loser);
        IF v_loser_lines > 0 THEN
          RAISE EXCEPTION 'lease_charges repair: base-rent rows % and % share effective_from % and both hold schedule-line history — resolve them manually before migrating',
            v_conflict.older_id, v_conflict.newer_id, v_conflict.newer_from;
        END IF;
        DELETE FROM public.lease_charges WHERE id = v_loser;
        v_shadows_deleted := v_shadows_deleted + 1;
      END;
    END IF;
  END LOOP;

  RAISE NOTICE 'lease_charges repair: % overlapping window(s) closed before successor, % orphanless duplicate(s) deleted, % future scheduled line(s) cancelled',
    v_windows_closed, v_shadows_deleted, v_lines_cancelled;
  windows_closed := v_windows_closed;
  shadows_deleted := v_shadows_deleted;
  lines_cancelled := v_lines_cancelled;
  RETURN NEXT;
END
$$;


--
-- Name: FUNCTION lease_charges_base_rent_repair(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lease_charges_base_rent_repair() IS 'openbooks:lease_charges_base_rent_repair:v2 - explicit, idempotent maintenance repair for pre-0060 overlaps; migration 0069 installs but never invokes it, and each conflict contributes to the cumulative cancelled-line total while billed evidence remains untouched';


--
-- Name: lease_schedule_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_schedule_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'lease schedules are retained; supersede future rows through an approved change'; END IF;
  IF (to_jsonb(NEW) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'lease schedule measurements are immutable; append a revision';
  END IF;
  IF NEW.superseded_by_change_id IS DISTINCT FROM OLD.superseded_by_change_id THEN
    IF OLD.accrual_posted_at IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM financial_changes c WHERE c.id=NEW.superseded_by_change_id AND c.org_id=OLD.org_id
        AND c.subject_id=OLD.lease_id AND c.domain='lease' AND c.status='approved') THEN
      RAISE EXCEPTION 'only unaccrued rows may be superseded by an approved change to this lease';
    END IF;
  END IF;
  IF (OLD.payment_posted_at IS NOT NULL AND (NEW.payment_posted_at IS DISTINCT FROM OLD.payment_posted_at OR NEW.payment_entry_id IS DISTINCT FROM OLD.payment_entry_id))
    OR (OLD.accrual_posted_at IS NOT NULL AND (NEW.accrual_posted_at IS DISTINCT FROM OLD.accrual_posted_at OR NEW.amortization_entry_id IS DISTINCT FROM OLD.amortization_entry_id))
    OR (OLD.superseded_by_change_id IS NOT NULL AND NEW IS DISTINCT FROM OLD) THEN
    RAISE EXCEPTION 'completed lease events cannot be changed';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: mfg_scrap_snapshot_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mfg_scrap_snapshot_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.work_order_id IS DISTINCT FROM OLD.work_order_id)
    OR (NEW.operation_id IS DISTINCT FROM OLD.operation_id)
    OR (NEW.component_item_id IS DISTINCT FROM OLD.component_item_id)
    OR (NEW.quantity IS DISTINCT FROM OLD.quantity)
    OR (NEW.reason_id IS DISTINCT FROM OLD.reason_id)
    OR (NEW.classification IS DISTINCT FROM OLD.classification)
  THEN
    RAISE EXCEPTION 'scrap event % for work order % carries frozen lineage that cannot be re-pointed; file a new event instead', NEW.id, NEW.work_order_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.treatment IS NOT NULL OR NEW.treatment IS NULL THEN
    IF (NEW.treatment IS DISTINCT FROM OLD.treatment)
      OR (NEW.frozen_value IS DISTINCT FROM OLD.frozen_value)
      OR (NEW.frozen_unit_cost IS DISTINCT FROM OLD.frozen_unit_cost)
      OR (NEW.lot_id IS DISTINCT FROM OLD.lot_id)
      OR (NEW.serial_id IS DISTINCT FROM OLD.serial_id)
      OR (NEW.plan_fingerprint IS DISTINCT FROM OLD.plan_fingerprint)
      OR (NEW.approval_required IS DISTINCT FROM OLD.approval_required)
    THEN
      RAISE EXCEPTION 'scrap event % for work order % carries a frozen valuation snapshot that cannot be rewritten; normalize a legacy event only through a controlled restatement proposal', NEW.id, NEW.work_order_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF OLD.posted_entry_id IS NOT NULL
    AND NEW.posted_entry_id IS DISTINCT FROM OLD.posted_entry_id
  THEN
    RAISE EXCEPTION 'scrap event % is already linked to posted entry %; posting linkage cannot be rewritten or cleared, correct through reversal or an adjusting entry', NEW.id, OLD.posted_entry_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: mfg_wo_snapshot_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mfg_wo_snapshot_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.standard_labor_wage_id IS DISTINCT FROM OLD.standard_labor_wage_id)
    OR (NEW.standard_labor_effective_from IS DISTINCT FROM OLD.standard_labor_effective_from)
    OR (NEW.standard_labor_rate IS DISTINCT FROM OLD.standard_labor_rate)
    OR (NEW.standard_labor_currency IS DISTINCT FROM OLD.standard_labor_currency)
    OR (NEW.standard_labor_basis IS DISTINCT FROM OLD.standard_labor_basis)
    OR (NEW.standard_labor_annual_hours IS DISTINCT FROM OLD.standard_labor_annual_hours)
    OR (NEW.standard_labor_final_rate IS DISTINCT FROM OLD.standard_labor_final_rate)
    OR (NEW.standard_labor_functional_currency IS DISTINCT FROM OLD.standard_labor_functional_currency)
    OR (NEW.standard_labor_burden IS DISTINCT FROM OLD.standard_labor_burden)
    OR (NEW.standard_labor_burden_hash IS DISTINCT FROM OLD.standard_labor_burden_hash)
    OR (NEW.standard_labor_fx_class IS DISTINCT FROM OLD.standard_labor_fx_class)
    OR (NEW.standard_labor_fx_rate IS DISTINCT FROM OLD.standard_labor_fx_rate)
    OR (NEW.standard_labor_fx_row_id IS DISTINCT FROM OLD.standard_labor_fx_row_id)
    OR (NEW.standard_labor_fx_date IS DISTINCT FROM OLD.standard_labor_fx_date)
    OR (NEW.standard_labor_fx_source IS DISTINCT FROM OLD.standard_labor_fx_source)
    OR (NEW.standard_labor_fx_direction IS DISTINCT FROM OLD.standard_labor_fx_direction)
    OR (NEW.overhead_snapshot IS DISTINCT FROM OLD.overhead_snapshot)
    OR (NEW.overhead_snapshot_hash IS DISTINCT FROM OLD.overhead_snapshot_hash)
  THEN
    RAISE EXCEPTION 'operation % for work order % carries release-frozen snapshots that cannot be rewritten; correct through reversal or an adjusting entry', NEW.id, NEW.work_order_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: net_investment_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.net_investment_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF TG_TABLE_NAME='subsidiary_ownership_interests' THEN
    IF EXISTS(SELECT 1 FROM public.net_investment_entries c WHERE c.org_id=OLD.org_id AND c.interest_id=OLD.id) AND
      (TG_OP='DELETE' OR (NEW.subsidiary_id,NEW.parent_subsidiary_id,NEW.method,NEW.ownership_percent,NEW.effective_from)
        IS DISTINCT FROM (OLD.subsidiary_id,OLD.parent_subsidiary_id,OLD.method,OLD.ownership_percent,OLD.effective_from)
       OR (NEW.effective_to IS DISTINCT FROM OLD.effective_to AND NOT EXISTS(SELECT 1 FROM public.financial_changes f
         WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.subject_id=OLD.id AND f.domain='consolidation'
           AND f.status='approved' AND f.operation IN('loss_of_control','reversal'))))
      THEN RAISE EXCEPTION 'used net-investment ownership identity is immutable; use the controlled loss-of-control workflow to close its reporting window'; END IF;
  ELSIF TG_TABLE_NAME='intercompany_pairs' THEN
    IF EXISTS(SELECT 1 FROM public.net_investment_entries c JOIN public.financial_changes f ON f.org_id=c.org_id AND f.id=c.change_id
      WHERE c.org_id=OLD.org_id AND f.payload->>'pairId'=OLD.id::text) AND
      (TG_OP='DELETE' OR (NEW.from_subsidiary_id,NEW.to_subsidiary_id,NEW.due_from_account_id,NEW.due_to_account_id)
        IS DISTINCT FROM (OLD.from_subsidiary_id,OLD.to_subsidiary_id,OLD.due_from_account_id,OLD.due_to_account_id))
      THEN RAISE EXCEPTION 'used net-investment loan pairing is immutable; configure a new pair for a changed financing arrangement'; END IF;
  ELSIF TG_TABLE_NAME='consolidated_fx_rates' THEN
    IF (TG_OP='DELETE' OR NEW.average_rate IS DISTINCT FROM OLD.average_rate) AND EXISTS(
      SELECT 1 FROM public.net_investment_entries c JOIN public.financial_changes f ON f.org_id=c.org_id AND f.id=c.change_id,
        jsonb_array_elements(f.before_state->'sources') source,
        jsonb_array_elements(f.before_state->'entities') holder
      WHERE c.org_id=OLD.org_id AND c.period_id=OLD.period_id AND c.reversed_by_change_id IS NULL
        AND holder->>'id'=source->>'subsidiary_id' AND holder->>'base_currency'=OLD.from_currency
        AND f.before_state->'elimination'->>'base_currency'=OLD.to_currency)
      THEN RAISE EXCEPTION 'the average rate supports an approved net-investment OCI assessment; reverse that assessment through Accounting changes before correcting its translation rate'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: net_investment_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.net_investment_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN
    IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
      IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
    END IF;
    IF TG_OP='UPDATE' AND OLD.reversed_by_change_id IS NULL AND NEW.reversed_by_change_id IS NOT NULL
      AND (to_jsonb(NEW)-'reversed_by_change_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'reversed_by_change_id')
      AND EXISTS(SELECT 1 FROM public.financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.reversed_by_change_id
        AND f.domain='consolidation' AND f.operation='net_investment_oci_reversal' AND f.status='approved'
        AND f.payload->>'sourceChangeId'=OLD.change_id::text) THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'net-investment evidence is immutable; use its independently approved correction in Accounting changes';
  END IF;
  IF TG_TABLE_NAME='net_investment_entries' THEN
    IF NOT EXISTS(SELECT 1 FROM public.financial_changes f JOIN public.subsidiary_ownership_interests i ON i.org_id=f.org_id AND i.id=f.subject_id
      JOIN public.accounting_books b ON b.org_id=f.org_id AND b.id=NEW.book_id
      JOIN public.accounting_periods p ON p.org_id=b.org_id AND p.id=NEW.period_id
      JOIN public.subsidiaries e ON e.org_id=f.org_id AND e.id=NEW.elimination_subsidiary_id AND e.is_elimination
      WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.domain='consolidation' AND f.operation='net_investment_oci' AND f.status='approved'
        AND f.subject_id=NEW.interest_id AND f.subsidiary_id=e.id AND f.payload->>'bookId'=b.id::text
        AND f.effective_on BETWEEN p.starts_on AND p.ends_on)
      OR (NEW.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.journal_entries e
        WHERE e.org_id=NEW.org_id AND e.id=NEW.journal_entry_id AND e.book_id=NEW.book_id AND e.period_id=NEW.period_id
          AND e.subsidiary_id=NEW.elimination_subsidiary_id AND e.status='posted' AND e.origin='net_investment_oci'))
      THEN RAISE EXCEPTION 'net-investment journal must bind to its approved ownership, book, period and elimination entity'; END IF;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.net_investment_entries c JOIN public.financial_changes f ON f.org_id=c.org_id AND f.id=c.change_id
      JOIN public.journal_lines l ON l.org_id=c.org_id AND l.id=NEW.source_line_id
      JOIN public.journal_entries e ON e.org_id=l.org_id AND e.id=l.entry_id
      WHERE c.org_id=NEW.org_id AND c.change_id=NEW.change_id AND f.status='approved' AND e.origin='fx_revaluation'
        AND e.book_id=c.book_id AND e.period_id=c.period_id AND e.status IN('posted','reversed') AND l.amount=NEW.amount
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(f.before_state->'sources') proof
          WHERE proof->>'id'=NEW.source_line_id::text AND (proof->>'translated')::numeric=NEW.translated_amount
            AND (proof->>'averageRate')::numeric=NEW.average_rate))
      THEN RAISE EXCEPTION 'net-investment source must match the independently approved native FX evidence'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: nonprofit_frameworks_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nonprofit_frameworks_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_line_count bigint;
  v_org_id uuid;
begin
  if tg_op = 'DELETE' and pg_catalog.pg_trigger_depth() > 1 then
    return old;
  end if;

  v_org_id := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'UPDATE' and new.org_id is distinct from old.org_id then
    raise exception 'a nonprofit framework cannot be moved to another organization'
      using errcode = '23514';
  end if;

  -- Fund line inserts use the same transaction lock, so a framework change
  -- cannot pass its history check while a fund posting is still in flight.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || v_org_id::text, 0)
  );

  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and new.framework is distinct from old.framework) then
    select count(*) into v_line_count
      from public.journal_lines jl
      join public.journal_entries je
        on je.org_id = jl.org_id and je.id = jl.entry_id
     where jl.org_id = v_org_id
       and jl.extra_dims ? 'fund'
       and je.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'nonprofit framework cannot change or be removed while % posted fund-tagged journal lines exist; continue with the current framework or use a separate organization',
        v_line_count
        using errcode = '23514',
              constraint = 'nonprofit_frameworks_history_guard';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;


--
-- Name: number_sequences_allocation_watermark(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.number_sequences_allocation_watermark() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.allocated_through := GREATEST(NEW.allocated_through, NEW.next_number);
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION number_sequences_allocation_watermark(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.number_sequences_allocation_watermark() IS 'openbooks:document_number_watermark:v1 - every counter advance raises the allocation watermark';


--
-- Name: number_sequences_monotonic_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.number_sequences_monotonic_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.allocated_through > 0 THEN
    IF NEW.next_number < OLD.allocated_through THEN
      RAISE EXCEPTION
        'document sequence % for kind % has already allocated through %; a used counter cannot move backward — advance it forward instead',
        OLD.prefix, OLD.document_kind, OLD.allocated_through;
    END IF;
    IF NEW.prefix IS DISTINCT FROM OLD.prefix
       OR NEW.padding IS DISTINCT FROM OLD.padding
       OR NEW.document_kind IS DISTINCT FROM OLD.document_kind THEN
      RAISE EXCEPTION
        'document sequence % for kind % has already issued numbers; its prefix, padding and kind are frozen once used',
        OLD.prefix, OLD.document_kind;
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION number_sequences_monotonic_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.number_sequences_monotonic_guard() IS 'openbooks:document_number_monotonic_guard:v1 - a used sequence cannot decrease into an occupied output range or change the format it issued; applies to setup edits, imports and direct writes alike';


--
-- Name: ob_rebase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ob_rebase(old uuid, seed uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    select md5(seed::text || ':' || old::text)::uuid
$$;


--
-- Name: openbooks_bank_rule_criteria_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_criteria_is_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  account_id text;
BEGIN
  IF jsonb_typeof(value) <> 'object'
     OR value->>'version' <> '2'
     OR octet_length(value::text) > 100000
     OR NOT openbooks_bank_rule_group_is_valid(value->'match') THEN
    RETURN false;
  END IF;
  IF value ? 'accountScope' THEN
    IF jsonb_typeof(value->'accountScope') <> 'array' THEN
      RETURN false;
    END IF;
    FOR account_id IN SELECT entry FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)
    LOOP
      IF account_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF (SELECT count(*) <> count(DISTINCT entry) FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_rule_group_is_valid(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_group_is_valid(value jsonb, depth integer DEFAULT 0) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  rule jsonb;
  field_name text;
  operator_name text;
  scalar_value text;
  numeric_value numeric;
  lower_bound numeric;
  upper_bound numeric;
BEGIN
  IF depth > 4
     OR jsonb_typeof(value) <> 'object'
     OR value->>'combinator' NOT IN ('and', 'or')
     OR jsonb_typeof(value->'rules') <> 'array'
     OR jsonb_array_length(value->'rules') NOT BETWEEN 1 AND 40 THEN
    RETURN false;
  END IF;

  FOR rule IN SELECT element FROM jsonb_array_elements(value->'rules') AS elements(element)
  LOOP
    IF jsonb_typeof(rule) <> 'object' THEN
      RETURN false;
    END IF;
    IF rule ? 'rules' THEN
      IF NOT openbooks_bank_rule_group_is_valid(rule, depth + 1) THEN
        RETURN false;
      END IF;
      CONTINUE;
    END IF;

    field_name := rule->>'field';
    operator_name := rule->>'op';
    scalar_value := rule->>'value';

    IF field_name IN ('description', 'payee', 'anyText', 'reference') THEN
      IF operator_name NOT IN ('contains', 'notContains', 'equals', 'startsWith', 'endsWith', 'isBlank')
         OR (operator_name <> 'isBlank' AND (jsonb_typeof(rule->'value') <> 'string' OR btrim(scalar_value) = '' OR length(scalar_value) > 200)) THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'flow' THEN
      IF operator_name <> 'is' OR scalar_value NOT IN ('in', 'out', 'any') THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'source' THEN
      IF operator_name <> 'equals' OR jsonb_typeof(rule->'value') <> 'string'
         OR btrim(scalar_value) = '' OR length(scalar_value) > 40 THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'amount' THEN
      IF operator_name NOT IN ('eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'between') THEN
        RETURN false;
      END IF;
      IF operator_name = 'between' THEN
        IF jsonb_typeof(rule->'value') <> 'array'
           OR jsonb_array_length(rule->'value') <> 2
           OR jsonb_typeof(rule->'value'->0) <> 'number'
           OR jsonb_typeof(rule->'value'->1) <> 'number' THEN
          RETURN false;
        END IF;
        lower_bound := (rule->'value'->>0)::numeric;
        upper_bound := (rule->'value'->>1)::numeric;
        IF lower_bound < 0 OR upper_bound < lower_bound THEN
          RETURN false;
        END IF;
      ELSE
        IF jsonb_typeof(rule->'value') <> 'number' THEN
          RETURN false;
        END IF;
        numeric_value := scalar_value::numeric;
        IF numeric_value < 0 THEN
          RETURN false;
        END IF;
      END IF;
    ELSIF field_name = 'date' THEN
      IF operator_name = 'withinDays' THEN
        IF jsonb_typeof(rule->'value') <> 'number' OR scalar_value::numeric <= 0 THEN
          RETURN false;
        END IF;
      ELSIF operator_name IN ('on', 'before', 'after') THEN
        IF jsonb_typeof(rule->'value') <> 'string'
           OR scalar_value !~ '^\d{4}-\d{2}-\d{2}$'
           OR to_char(scalar_value::date, 'YYYY-MM-DD') <> scalar_value THEN
          RETURN false;
        END IF;
      ELSE
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_rule_outcome_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_outcome_is_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  line jsonb;
  portion jsonb;
  optional_id text;
  remainder_count integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object' OR octet_length(value::text) > 100000 THEN
    RETURN false;
  END IF;
  IF value->>'action' = 'exclude' THEN
    RETURN value = '{"action":"exclude"}'::jsonb;
  END IF;
  IF value->>'action' <> 'categorize'
     OR value->>'version' <> '2'
     OR value->>'mode' NOT IN ('auto', 'suggest')
     OR jsonb_typeof(value->'lines') <> 'array'
     OR jsonb_array_length(value->'lines') NOT BETWEEN 1 AND 20 THEN
    RETURN false;
  END IF;

  IF value ? 'partyId' AND coalesce(value->>'partyId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  IF value ? 'memo' AND (jsonb_typeof(value->'memo') <> 'string' OR btrim(value->>'memo') = '' OR length(value->>'memo') > 300) THEN
    RETURN false;
  END IF;

  FOR line IN SELECT element FROM jsonb_array_elements(value->'lines') AS elements(element)
  LOOP
    IF jsonb_typeof(line) <> 'object'
       OR coalesce(line->>'accountId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR jsonb_typeof(line->'portion') <> 'object' THEN
      RETURN false;
    END IF;
    portion := line->'portion';
    IF portion->>'kind' = 'remainder' THEN
      remainder_count := remainder_count + 1;
    ELSIF portion->>'kind' = 'percent' THEN
      IF jsonb_typeof(portion->'value') <> 'number'
         OR (portion->>'value')::numeric <= 0
         OR (portion->>'value')::numeric > 100 THEN
        RETURN false;
      END IF;
    ELSIF portion->>'kind' = 'fixed' THEN
      IF jsonb_typeof(portion->'value') <> 'number' OR (portion->>'value')::numeric <= 0 THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;

    FOREACH optional_id IN ARRAY ARRAY['partyId', 'departmentId', 'projectId', 'locationId', 'classId', 'taxCodeId']
    LOOP
      IF line ? optional_id
         AND coalesce(line->>optional_id, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF line ? 'description'
       AND (jsonb_typeof(line->'description') <> 'string' OR btrim(line->>'description') = '' OR length(line->>'description') > 200) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN remainder_count <= 1;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_statement_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_statement_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF tg_op = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'imported bank statement lines are immutable';
  END IF;
  IF tg_op = 'INSERT' THEN
    RETURN new;
  END IF;
  IF to_jsonb(new)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by'
     <> to_jsonb(old)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by' THEN
    RAISE EXCEPTION 'imported bank statement content is immutable';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM reconciliation_matches m
      JOIN reconciliations r ON r.id = m.reconciliation_id
     WHERE m.statement_line_id = old.id
       AND m.org_id = old.org_id
       AND r.status = 'signed_off'
  ) OR EXISTS (
    SELECT 1
      FROM reconciliations r
     WHERE r.org_id = old.org_id
       AND r.account_id = old.account_id
       AND r.currency = old.currency
       AND r.status = 'signed_off'
       AND r.through_date >= old.posted_on
       AND old.match_status = 'excluded'
  ) THEN
    RAISE EXCEPTION 'signed-off bank statement evidence is immutable';
  END IF;
  IF new.match_status = 'matched'
     AND NOT EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'matched bank statement line requires reconciliation-match evidence';
  END IF;
  IF new.match_status <> 'matched'
     AND EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'bank statement line with match evidence must remain matched';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: openbooks_bump_revision_seq(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bump_revision_seq() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Every committed UPDATE is a new revision, even one that backdates the
  -- display timestamp: the counter only moves forward, so a stale
  -- revision-seq token can never compare equal against newer content.
  NEW.revision_seq := OLD.revision_seq + 1;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION openbooks_bump_revision_seq(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_bump_revision_seq() IS 'openbooks:revision_seq:v1 - strictly increasing optimistic-concurrency counter; bumped on every UPDATE of a revisioned row (documents, wip_prebill_lines, ap_capture_items, custom_records, crm_opportunities), independent of the editable updated_at display timestamp';


--
-- Name: openbooks_clone_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_clone_authority() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select coalesce(current_setting('openbooks.clone', true), 'off') = 'on'
     and coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
     and coalesce(current_setting('openbooks.amend', true), 'off') = 'on'
     and (public.app_bypass_rls_active()
          or exists (select 1
                       from pg_catalog.pg_roles
                      where rolname = current_user and rolbypassrls))
$$;


--
-- Name: FUNCTION openbooks_clone_authority(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_clone_authority() IS 'True only inside the deterministic clone transaction (0316, bypass-predicate acceptance added in 0401): openbooks.clone, openbooks.migration and openbooks.amend asserted together with an unscoped maintenance context (public.app_bypass_rls_active() or a BYPASSRLS login). Guards honour it for INSERT of posted history only; it never permits UPDATE, DELETE, or tenant-transaction writes.';


--
-- Name: openbooks_connector_replay_authorized(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_connector_replay_authorized(p_org uuid, p_authorization uuid, p_period uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
      from connector_replay_authorizations auth
      join accounting_periods from_period
        on from_period.id = auth.period_from_id
       and from_period.org_id = auth.org_id
      join accounting_periods to_period
        on to_period.id = auth.period_to_id
       and to_period.org_id = auth.org_id
      join accounting_periods target
        on target.id = p_period
       and target.org_id = p_org
     where auth.id = p_authorization
       and auth.org_id = p_org
       and auth.authorized_at <= now()
       and auth.expires_at > now()
       and target.starts_on >= least(from_period.starts_on, to_period.starts_on)
       and target.ends_on <= greatest(from_period.ends_on, to_period.ends_on)
  )
$$;


--
-- Name: FUNCTION openbooks_connector_replay_authorized(p_org uuid, p_authorization uuid, p_period uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_connector_replay_authorized(p_org uuid, p_authorization uuid, p_period uuid) IS 'Live-grant check for closed-period connector replay: the named connector_replay_authorizations row belongs to the posting organization, its window is open, and its period range covers the entry period. Fail-closed: anything else is false.';


--
-- Name: openbooks_default_budget_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_default_budget_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.subsidiary_id IS NULL THEN
    SELECT s.id
      INTO NEW.subsidiary_id
      FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id
       AND s.parent_id IS NULL
       AND s.is_active
       AND NOT s.is_elimination
     ORDER BY s.created_at, s.id
     LIMIT 1;
    IF NEW.subsidiary_id IS NULL THEN
      RAISE EXCEPTION 'budget line requires an active root subsidiary for organization %', NEW.org_id
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION openbooks_default_budget_subsidiary(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_default_budget_subsidiary() IS 'openbooks:budget_subsidiary:v1 - resolves legacy omitted budget entities to the tenant root before the not-null and tenant-coherent FK checks';


--
-- Name: openbooks_gl_activity_apply(uuid, uuid, date, uuid, numeric, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_apply(p_org uuid, p_account uuid, p_month date, p_subsidiary uuid, p_debit numeric, p_credit numeric, p_count bigint) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, month, subsidiary_id, debit_total, credit_total, line_count)
  values (p_org, p_account, p_month, p_subsidiary, p_debit, p_credit, p_count)
  on conflict (org_id, account_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_apply(uuid, uuid, uuid, date, uuid, numeric, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_apply(p_org uuid, p_account uuid, p_book uuid, p_month date, p_subsidiary uuid, p_debit numeric, p_credit numeric, p_count bigint) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, book_id, month, subsidiary_id, debit_total, credit_total, line_count)
  values (p_org, p_account, p_book, p_month, p_subsidiary, p_debit, p_credit, p_count)
  on conflict (org_id, account_id, book_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_old_in boolean;
  v_new_in boolean;
  v_old_month date;
  v_new_month date;
  v_old_book uuid;
  v_new_book uuid;
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'INSERT' then
    if new.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(new.id, new.org_id, date_trunc('month', new.posting_date)::date, 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    if old.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(old.id, old.org_id, date_trunc('month', old.posting_date)::date, -1);
    end if;
    return null;
  end if;
  v_old_in := old.status in ('posted', 'reversed');
  v_new_in := new.status in ('posted', 'reversed');
  v_old_month := date_trunc('month', old.posting_date)::date;
  v_new_month := date_trunc('month', new.posting_date)::date;
  v_old_book := old.book_id;
  v_new_book := new.book_id;
  if v_old_in and not v_new_in then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1);
  elsif v_new_in and not v_old_in then
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  elsif v_old_in and v_new_in and (v_old_month <> v_new_month or v_old_book is distinct from v_new_book) then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1, v_old_book);
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  end if;
  return null;
end $$;


--
-- Name: openbooks_gl_activity_entry_delta(uuid, uuid, date, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_entry_delta(p_entry uuid, p_org uuid, p_month date, p_sign integer, p_book uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, book_id, month, subsidiary_id, debit_total, credit_total, line_count)
  select p_org, l.account_id, coalesce(p_book, e.book_id), p_month, l.subsidiary_id,
         p_sign * coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0),
         p_sign * coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0),
         p_sign * count(*)
    from journal_lines l
    join journal_entries e on e.id = l.entry_id and e.org_id = l.org_id
   where l.entry_id = p_entry and l.org_id = p_org and e.org_id = p_org
   group by l.account_id, coalesce(p_book, e.book_id), l.subsidiary_id
   order by l.account_id, coalesce(p_book, e.book_id), l.subsidiary_id
  on conflict (org_id, account_id, book_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
  v_date date;
  v_org uuid;
  v_book uuid;
  v_month date;
  v_entry uuid;
  v_line_org uuid;
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'UPDATE'
     and (new.entry_id, new.org_id) is distinct from (old.entry_id, old.org_id) then
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
        -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
    end if;
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = new.entry_id and org_id = new.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
        greatest(new.amount, 0), greatest(-new.amount, 0), 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    v_entry := old.entry_id;
    v_line_org := old.org_id;
  else
    v_entry := new.entry_id;
    v_line_org := new.org_id;
  end if;
  select status, posting_date, org_id, book_id
    into v_status, v_date, v_org, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if v_status is null or v_status not in ('posted', 'reversed') then
    return null;
  end if;
  v_month := date_trunc('month', v_date)::date;
  if tg_op in ('UPDATE', 'DELETE') then
    perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
      -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
      greatest(new.amount, 0), greatest(-new.amount, 0), 1);
  end if;
  return null;
end $$;


--
-- Name: openbooks_gl_activity_rebuild(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_rebuild(p_org uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_count bigint;
begin
  delete from gl_month_activity where org_id = p_org;
  insert into gl_month_activity (org_id, account_id, book_id, month, subsidiary_id, debit_total, credit_total, line_count)
  select e.org_id, l.account_id, e.book_id, date_trunc('month', e.posting_date)::date, l.subsidiary_id,
         coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0),
         coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0),
         count(*)
    from journal_lines l
    join journal_entries e on e.id = l.entry_id and e.org_id = l.org_id
   where e.org_id = p_org and l.org_id = p_org and e.status in ('posted', 'reversed')
   group by e.org_id, l.account_id, e.book_id, date_trunc('month', e.posting_date)::date, l.subsidiary_id;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: openbooks_gl_activity_verify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_verify(p_org uuid) RETURNS TABLE(account_id uuid, book_id uuid, month date, subsidiary_id uuid, summary_debit numeric, ledger_debit numeric, summary_credit numeric, ledger_credit numeric)
    LANGUAGE sql
    AS $$
  with ledger as (
    select l.account_id, e.book_id, date_trunc('month', e.posting_date)::date as month, l.subsidiary_id,
           coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0) as debit_total,
           coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0) as credit_total
      from journal_lines l
      join journal_entries e on e.id = l.entry_id and e.org_id = l.org_id
     where e.org_id = p_org and l.org_id = p_org and e.status in ('posted', 'reversed')
     group by 1, 2, 3, 4
  ), summary as (
    select g.account_id, g.book_id, g.month, g.subsidiary_id, g.debit_total, g.credit_total
      from gl_month_activity g where g.org_id = p_org
       and (g.debit_total <> 0 or g.credit_total <> 0 or g.line_count <> 0)
  )
  select coalesce(l.account_id, s.account_id), coalesce(l.book_id, s.book_id),
         coalesce(l.month, s.month), coalesce(l.subsidiary_id, s.subsidiary_id),
         coalesce(s.debit_total, 0), coalesce(l.debit_total, 0),
         coalesce(s.credit_total, 0), coalesce(l.credit_total, 0)
    from ledger l
    full outer join summary s
      on s.account_id = l.account_id and s.book_id = l.book_id
     and s.month = l.month and s.subsidiary_id = l.subsidiary_id
   where coalesce(s.debit_total, 0) <> coalesce(l.debit_total, 0)
      or coalesce(s.credit_total, 0) <> coalesce(l.credit_total, 0);
$$;


--
-- Name: openbooks_guard_ap_capture_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'AP capture evidence is append-only';
END;
