--
-- Name: openbooks_guard_ap_capture_source_blob(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM file_versions fv
    JOIN ap_capture_items ci ON ci.file_id = fv.file_id
    WHERE fv.id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'AP capture source blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = OLD.id) THEN
    RAISE EXCEPTION 'AP capture source files are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_file_id uuid;
BEGIN
  target_file_id := CASE WHEN TG_OP = 'INSERT' THEN NEW.file_id ELSE OLD.file_id END;
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = target_file_id) THEN
    RAISE EXCEPTION 'AP capture source versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_budget_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_budget_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  row_data budget_lines%rowtype;
  scenario_org uuid;
  scenario_year integer;
  scenario_status text;
begin
  row_data := case when tg_op = 'DELETE' then old else new end;
  select org_id, fiscal_year, status
    into scenario_org, scenario_year, scenario_status
    from budget_scenarios where id = row_data.scenario_id;
  -- During an ON DELETE CASCADE, PostgreSQL removes the parent scenario before
  -- firing the child row's delete trigger. The line was already protected by
  -- the scenario's draft-only delete guard, so allow that cascade to finish.
  if tg_op = 'DELETE' and scenario_org is null then return old; end if;
  if scenario_org is null or scenario_org <> row_data.org_id then
    raise exception 'budget line scenario must belong to the tenant';
  end if;
  if scenario_status <> 'draft' then
    raise exception 'budget lines are immutable outside draft status';
  end if;
  if tg_op = 'DELETE' then return old; end if;

  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id and a.is_active and not a.is_summary
  ) then
    raise exception 'budget account must be an active posting account in the tenant';
  end if;
  -- Budgets plan the profit and loss only: the six P&L types of the single
  -- PNL_TYPES definition (engine records/account-types), the same set the
  -- worksheet, the import, the variances and the prior-actuals copy filter
  -- on. Refuse a balance-sheet account by name rather than writing a line
  -- the worksheet hides but the totals count.
  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id
       and a.type in ('income', 'income_other', 'cogs', 'expense', 'expense_other', 'expense_deferred')
  ) then
    raise exception 'budget account must be a profit-and-loss posting account in the tenant (income, income_other, cogs, expense, expense_other, expense_deferred)';
  end if;
  if not exists (
    select 1 from accounting_periods p
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment
  ) then
    raise exception 'budget period must belong to the scenario fiscal year and tenant';
  end if;
  -- A budget is pinned to one calendar: the org default. The worksheet, the
  -- totals, the import resolver and the copy mapping all read that calendar,
  -- so a line on any other calendar would be hidden yet counted.
  if not exists (
    select 1 from accounting_periods p
      join fiscal_calendars fc on fc.id = p.fiscal_calendar_id and fc.org_id = p.org_id
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment and fc.is_default
  ) then
    raise exception 'budget period must belong to the scenario fiscal year on the default fiscal calendar of the tenant';
  end if;
  if new.department_id is not null and not exists (
    select 1 from departments d where d.id = new.department_id and d.org_id = new.org_id
  ) then raise exception 'budget department must belong to the tenant'; end if;
  if new.project_id is not null and not exists (
    select 1 from projects p where p.id = new.project_id and p.org_id = new.org_id
  ) then raise exception 'budget project must belong to the tenant'; end if;
  if new.location_id is not null and not exists (
    select 1 from locations l where l.id = new.location_id and l.org_id = new.org_id
  ) then raise exception 'budget location must belong to the tenant'; end if;
  if new.class_id is not null and not exists (
    select 1 from classes c where c.id = new.class_id and c.org_id = new.org_id
  ) then raise exception 'budget class must belong to the tenant'; end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_budget_scenario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_budget_scenario() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'only draft budget scenarios may be deleted';
    end if;
    return old;
  end if;

  if not exists (
    select 1 from accounting_books b
     where b.id = new.book_id and b.org_id = new.org_id and b.is_active
  ) then
    raise exception 'budget scenario book must be active and belong to the tenant';
  end if;

  if tg_op = 'UPDATE' then
    if new.revision <> old.revision + 1 then
      raise exception 'budget scenario revision must increment by exactly one';
    end if;
    if old.status <> 'draft' and (
      new.name is distinct from old.name or
      new.description is distinct from old.description or
      new.book_id is distinct from old.book_id or
      new.fiscal_year is distinct from old.fiscal_year or
      new.kind is distinct from old.kind
    ) then
      raise exception 'only draft budget metadata may be edited';
    end if;
    -- The book and fiscal year pin the plan to one ledger and one period
    -- set: changing either under existing lines would silently reinterpret
    -- the whole plan. Refuse here as well as in the route so writers
    -- bypassing the API meet the same refusal.
    if (new.book_id is distinct from old.book_id or new.fiscal_year is distinct from old.fiscal_year)
       and exists (select 1 from budget_lines bl where bl.scenario_id = new.id and bl.org_id = new.org_id)
    then
      raise exception 'budget book and fiscal year are fixed once the budget has lines';
    end if;
    if new.status is distinct from old.status and not (
      (old.status = 'draft' and new.status in ('pending_approval', 'archived')) or
      (old.status = 'pending_approval' and new.status in ('draft', 'approved', 'archived')) or
      (old.status = 'approved' and new.status = 'archived')
    ) then
      raise exception 'invalid budget status transition: % -> %', old.status, new.status;
    end if;
  end if;

  if new.status in ('pending_approval', 'approved') and not exists (
    select 1 from budget_lines bl
     where bl.scenario_id = new.id and bl.org_id = new.org_id and bl.amount <> 0
  ) then
    raise exception 'a submitted or approved budget must contain at least one non-zero line';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then raise exception 'budget submitter must belong to the tenant'; end if;
  if new.approved_by is not null and not exists (
    select 1 from users u where u.id = new.approved_by and u.org_id = new.org_id
  ) then raise exception 'budget approver must belong to the tenant'; end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_depreciation_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_depreciation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  posted boolean;
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'depreciation input evidence is append-preserved';
  end if;

  select exists (
    select 1 from depreciation_schedule_lines
     where input_id = old.id and posted_amount is not null
  ) into posted;
  if posted then
    raise exception 'posted depreciation input evidence is immutable';
  end if;

  if old.voided_at is not null
     or new.voided_at is null
     or new.voided_by is null
     or new.org_id is distinct from old.org_id
     or new.schedule_id is distinct from old.schedule_id
     or new.period_id is distinct from old.period_id
     or new.kind is distinct from old.kind
     or new.manual_amount is distinct from old.manual_amount
     or new.production_units is distinct from old.production_units
     or new.memo is distinct from old.memo
     or new.evidence_file_id is distinct from old.evidence_file_id
     or new.supersedes_input_id is distinct from old.supersedes_input_id
     or new.created_at is distinct from old.created_at
     or new.created_by is distinct from old.created_by then
    raise exception 'depreciation input evidence may only be voided before posting';
  end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_finished_ap_capture_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_finished_ap_capture_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.status <> 'running' THEN
    RAISE EXCEPTION 'Finished AP capture runs are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: openbooks_guard_pay_run_bank_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_pay_run_bank_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payroll bank files are immutable evidence and cannot be deleted';
  END IF;
  IF NEW.id <> OLD.id
     OR NEW.org_id <> OLD.org_id
     OR NEW.pay_run_document_id <> OLD.pay_run_document_id
     OR NEW.payment_bank_profile_id <> OLD.payment_bank_profile_id
     OR NEW.format <> OLD.format
     OR NEW.sequence_number <> OLD.sequence_number
     OR NEW.file_number <> OLD.file_number
     OR NEW.sequence_value <> OLD.sequence_value
     OR NEW.file_creation_number IS DISTINCT FROM OLD.file_creation_number
     OR NEW.file_id_modifier IS DISTINCT FROM OLD.file_id_modifier
     OR NEW.filename <> OLD.filename
     OR NEW.content_hash <> OLD.content_hash
     OR NEW.size_bytes <> OLD.size_bytes
     OR NEW.file_id <> OLD.file_id
     OR NEW.file_version_id <> OLD.file_version_id
     OR NEW.entry_count <> OLD.entry_count
     OR NEW.control_total <> OLD.control_total
     OR NEW.currency <> OLD.currency
     OR NEW.excluded_cheque::text <> OLD.excluded_cheque::text
     OR NEW.excluded_total <> OLD.excluded_total
     OR NEW.generated_at <> OLD.generated_at THEN
    RAISE EXCEPTION 'payroll bank file % is immutable: regenerate to produce a new artifact', OLD.file_number;
  END IF;
  IF NEW.release_count < OLD.release_count THEN
    RAISE EXCEPTION 'payroll bank file release history cannot be rewound';
  END IF;
  IF OLD.status = 'superseded' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION 'a superseded payroll bank file cannot be reinstated';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_blob(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_version_id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'payroll bank file blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_id = OLD.id) THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'payroll bank files cannot be deleted from the cabinet';
    END IF;
    -- Renaming, moving, retiring or re-pointing the current version would all
    -- change what a later download returns.
    IF NEW.name <> OLD.name OR NEW.folder_id <> OLD.folder_id
       OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.current_version_id IS DISTINCT FROM OLD.current_version_id
       OR NEW.is_inactive <> OLD.is_inactive THEN
      RAISE EXCEPTION 'payroll bank files are immutable';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_version_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'payroll bank file versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_je_cascade_posting_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_je_cascade_posting_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  update journal_lines
     set posting_date = new.posting_date
   where entry_id = new.id
     and org_id = new.org_id
     and posting_date is distinct from new.posting_date;
  return null;
end $$;


--
-- Name: openbooks_jl_stamp_posting_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_jl_stamp_posting_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_date date;
begin
  select posting_date into v_date
    from journal_entries
   where id = new.entry_id and org_id = new.org_id;
  new.posting_date := v_date;
  return new;
end $$;


--
-- Name: openbooks_party_payment_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_party_payment_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'INSERT' then
    if new.unapplied_at is null then
      perform openbooks_party_payment_stats_delta(new.from_line_id, new.to_line_id, 1);
    end if;
  elsif tg_op = 'DELETE' then
    if old.unapplied_at is null then
      perform openbooks_party_payment_stats_delta(old.from_line_id, old.to_line_id, -1);
    end if;
  else
    if old.unapplied_at is null and new.unapplied_at is not null then
      perform openbooks_party_payment_stats_delta(old.from_line_id, old.to_line_id, -1);
    elsif old.unapplied_at is not null and new.unapplied_at is null then
      perform openbooks_party_payment_stats_delta(new.from_line_id, new.to_line_id, 1);
    end if;
  end if;
  return null;
end $$;


--
-- Name: openbooks_party_payment_stats_delta(uuid, uuid, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_party_payment_stats_delta(p_from_line uuid, p_to_line uuid, p_sign integer, p_settled date DEFAULT NULL::date, p_paid date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_org uuid; v_party uuid; v_type text; v_settled date; v_paid date; v_days numeric;
begin
  select bl.org_id, bl.party_id, a.type, bl.posting_date, pl.posting_date
    into v_org, v_party, v_type, v_settled, v_paid
    from journal_lines bl
    join accounts a on a.id = bl.account_id and a.org_id = bl.org_id
    join journal_lines pl on pl.id = p_from_line
   where bl.id = p_to_line;
  -- A bulk copy can insert an application before its lines; the rebuild
  -- function is the repair path for that (clones copy lines first).
  if v_party is null or v_settled is null or v_paid is null then return; end if;
  if v_type not in ('asset_receivable', 'liability_payable') then return; end if;
  -- A date move passes explicit before/after images; ordinary legs keep
  -- reading the live rows exactly as before.
  v_settled := coalesce(p_settled, v_settled);
  v_paid := coalesce(p_paid, v_paid);
  v_days := (v_paid - v_settled)::numeric;
  insert into party_payment_stats as s (org_id, party_id, account_type, settled_on, n, sum_days, sum_days_sq)
  values (v_org, v_party, v_type, v_paid,
          p_sign, p_sign * v_days, p_sign * v_days * v_days)
  on conflict (org_id, account_type, settled_on, party_id) do update
    set n = s.n + excluded.n,
        sum_days = s.sum_days + excluded.sum_days,
        sum_days_sq = s.sum_days_sq + excluded.sum_days_sq;
end $$;


--
-- Name: openbooks_party_payment_stats_rebuild(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_party_payment_stats_rebuild(p_org uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_count bigint;
begin
  delete from party_payment_stats where org_id = p_org;
  insert into party_payment_stats (org_id, party_id, account_type, settled_on, n, sum_days, sum_days_sq)
  select bl.org_id, bl.party_id, a.type, pl.posting_date,
         count(*),
         sum((pl.posting_date - bl.posting_date)::numeric),
         sum(((pl.posting_date - bl.posting_date)::numeric) * ((pl.posting_date - bl.posting_date)::numeric))
    from applications x
    join journal_lines bl on bl.id = x.to_line_id and bl.org_id = p_org
    join journal_lines pl on pl.id = x.from_line_id and pl.org_id = p_org
    join accounts a on a.id = bl.account_id and a.org_id = p_org
   where x.org_id = p_org and x.unapplied_at is null and bl.party_id is not null
     and a.type in ('asset_receivable', 'liability_payable')
     and bl.posting_date is not null and pl.posting_date is not null
   group by 1, 2, 3, 4;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: openbooks_party_payment_stats_verify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_party_payment_stats_verify(p_org uuid) RETURNS TABLE(party_id uuid, account_type text, settled_on date, stored_n bigint, actual_n bigint, stored_sum numeric, actual_sum numeric)
    LANGUAGE sql
    AS $$
  with actual as (
    select bl.party_id as pid, a.type as atype, pl.posting_date as m,
           count(*) as n, sum((pl.posting_date - bl.posting_date)::numeric) as sd
      from applications x
      join journal_lines bl on bl.id = x.to_line_id and bl.org_id = p_org
      join journal_lines pl on pl.id = x.from_line_id and pl.org_id = p_org
      join accounts a on a.id = bl.account_id and a.org_id = p_org
     where x.org_id = p_org and x.unapplied_at is null and bl.party_id is not null
       and a.type in ('asset_receivable', 'liability_payable')
       and bl.posting_date is not null and pl.posting_date is not null
     group by 1, 2, 3
  ), stored as (
    select s.party_id as pid, s.account_type as atype, s.settled_on as m, s.n, s.sum_days as sd
      from party_payment_stats s where s.org_id = p_org and s.n <> 0
  )
  select coalesce(a.pid, s.pid), coalesce(a.atype, s.atype), coalesce(a.m, s.m),
         coalesce(s.n, 0), coalesce(a.n, 0), coalesce(s.sd, 0), coalesce(a.sd, 0)
    from actual a full outer join stored s on s.pid = a.pid and s.atype = a.atype and s.m = a.m
   where coalesce(s.n, 0) <> coalesce(a.n, 0) or coalesce(s.sd, 0) <> coalesce(a.sd, 0);
$$;


--
-- Name: openbooks_query_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_query_org_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  resolved_org_id uuid;
begin
  execute 'select org_id from pg_temp.openbooks_query_context limit 1'
    into resolved_org_id;
  return resolved_org_id;
exception
  when undefined_table then return null;
end;
$$;


--
-- Name: openbooks_reconciliation_match_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_reconciliation_match_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_reconciliation_id uuid := coalesce(new.reconciliation_id, old.reconciliation_id);
  target_org_id uuid := coalesce(new.org_id, old.org_id);
  parent_status text;
BEGIN
  IF tg_op = 'DELETE' AND openbooks_sandbox_wipe_allowed(old.org_id) THEN
    RETURN old;
  END IF;
  SELECT status
    INTO parent_status
    FROM reconciliations
   WHERE id = target_reconciliation_id
     AND org_id = target_org_id;
  IF parent_status IS NULL THEN
    RAISE EXCEPTION 'reconciliation match parent must belong to the tenant';
  END IF;
  IF parent_status = 'signed_off' THEN
    RAISE EXCEPTION 'signed-off reconciliation matches are immutable';
  END IF;
  IF tg_op = 'UPDATE'
     AND (
       new.org_id IS DISTINCT FROM old.org_id
       OR new.reconciliation_id IS DISTINCT FROM old.reconciliation_id
       OR new.statement_line_id IS DISTINCT FROM old.statement_line_id
       OR new.journal_line_id IS DISTINCT FROM old.journal_line_id
       OR new.created_at IS DISTINCT FROM old.created_at
       OR new.created_by IS DISTINCT FROM old.created_by
     ) THEN
    RAISE EXCEPTION 'reconciliation match identity is immutable';
  END IF;
  IF tg_op <> 'DELETE' THEN
    IF NOT EXISTS (
      SELECT 1
        FROM reconciliations r
        JOIN bank_statement_lines l
          ON l.id = new.statement_line_id
         AND l.org_id = r.org_id
         AND l.account_id = r.account_id
         AND l.currency = r.currency
         AND l.posted_on <= r.through_date
        JOIN journal_lines jl
          ON jl.id = new.journal_line_id
         AND jl.org_id = r.org_id
         AND jl.account_id = r.account_id
         AND jl.currency = r.currency
        JOIN journal_entries je
          ON je.id = jl.entry_id
         AND je.status IN ('posted', 'reversed')
         AND je.posting_date <= r.through_date
       WHERE r.id = new.reconciliation_id
         AND r.org_id = new.org_id
         AND r.status <> 'signed_off'
         AND jl.reconciled_at IS NULL
    ) THEN
      RAISE EXCEPTION 'reconciliation match violates tenant, account, currency, cutoff, or journal availability';
    END IF;
  END IF;
  RETURN coalesce(new, old);
END;
$$;


--
-- Name: openbooks_refresh_query_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_refresh_query_catalog() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  relation_name text;
  has_org_id boolean;
  global_relations constant text[] := array['currencies'];
begin
  -- Public base tables are never query-console surfaces. Revoke both current
  -- and future access before rebuilding the reviewed view catalog.
  revoke all privileges on all tables in schema public from openbooks_read;
  alter default privileges in schema public revoke select on tables from openbooks_read;

  drop schema if exists openbooks_query cascade;
  create schema openbooks_query;
  revoke all on schema openbooks_query from public;
  grant usage on schema openbooks_query to openbooks_read;

  -- The registry table is the single source of truth for the governed
  -- relation set: a module migration registers with INSERT, never by
  -- redefining this function.
  for relation_name in
    select relation
      from public.openbooks_query_catalog_relations
     order by relation
  loop
    if to_regclass(format('public.%I', relation_name)) is null then
      raise exception 'governed query relation is missing: %', relation_name;
    end if;
    -- SELECT * is expanded and frozen when the view is created, so a column
    -- added later is not queryable until this function runs again.
    select exists (
      select 1 from information_schema.columns
       where table_schema = 'public' and table_name = relation_name and column_name = 'org_id'
    ) into has_org_id;
    if has_org_id then
      execute format(
        'create view openbooks_query.%1$I with (security_barrier=true) as '
        'select * from public.%1$I '
        'where org_id = public.openbooks_query_org_id()',
        relation_name
      );
    elsif relation_name = any(global_relations) then
      execute format(
        'create view openbooks_query.%1$I with (security_barrier=true) as select * from public.%1$I',
        relation_name
      );
    else
      raise exception
        'governed query relation % has no org_id and is not an explicitly reviewed global relation',
        relation_name;
    end if;
    execute format('grant select on openbooks_query.%I to openbooks_read', relation_name);
  end loop;

  -- Clawback tracking is reportable, but the provider webhook payload is
  -- not: event_payload carries the raw provider event, which can include
  -- instrument details. Status and references stay queryable.
  create view openbooks_query.payment_pending_clawbacks with (security_barrier=true) as
    select id, org_id, provider, intent_ref, event_status,
           created_at, last_seen_at, consumed_at, consumed_attempt_id
      from public.payment_pending_clawbacks
     where org_id = public.openbooks_query_org_id();
  -- Party dimensions are reportable, but full tax identifiers, sealed bank
  -- details and arbitrary source-system custom payloads are not.
  create view openbooks_query.parties with (security_barrier=true) as
    select id, org_id, kind, display_name, legal_name, short_code, email, phone,
           website, subsidiary_id, is_active, invoicing_preference,
           invoicing_profile, created_at, created_by, updated_at, updated_by
      from public.parties
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.customer_roles with (security_barrier=true) as
    select id, org_id, party_id, ar_account_id, payment_terms_id, credit_limit,
           currency, sales_rep_id, tax_code_id, is_on_hold, hold_reason, held_at,
           held_by, is_active, created_at, created_by, updated_at, updated_by
      from public.customer_roles
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.vendor_roles with (security_barrier=true) as
    select id, org_id, party_id, ap_account_id, payment_terms_id,
           default_expense_account_id, payment_method, eft_notification_email,
           currency, tax_code_id, is_t4a, compliance_class_id,
           information_return_form, information_return_box, tax_classification,
           tin_last4, tin_type, backup_withholding, is_on_hold, hold_reason,
           held_at, held_by, is_active, created_at, created_by, updated_at, updated_by
      from public.vendor_roles
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.party_bank_accounts with (security_barrier=true) as
    select id, org_id, party_id, bank_name, country, currency, account_last_four,
           approved_at, approved_by, approval_status, submitted_by, submitted_at,
           retired_at, retired_by, retirement_reason, is_active,
           created_at, created_by, updated_at, updated_by
      from public.party_bank_accounts
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.subsidiaries with (security_barrier=true) as
    select id, org_id, parent_id, name, legal_name, base_currency, country,
           is_elimination, is_active, created_at, created_by, updated_at, updated_by
      from public.subsidiaries
     where org_id = public.openbooks_query_org_id();
  -- Payroll profiles are reportable, but the sealed national identifier is not:
  -- sin_encrypted is envelope-encrypted SIN/SSN ciphertext and never leaves the
  -- payroll engine. sin_last3 is the identify-without-reveal substitute.
  create view openbooks_query.employee_payroll_profiles with (security_barrier=true) as
    select id, org_id, employee_party_id, pay_schedule_id, province,
           pay_basis, federal_claim_code, federal_claim_amount,
           provincial_claim_code, provincial_claim_amount,
           additional_tax_per_period, prescribed_zone_deduction,
           authorized_annual_deductions, authorized_federal_credits,
           authorized_provincial_credits, cpp_exempt, ei_exempt,
           tax_exempt, vacation_percent, vacation_method, is_active,
           created_at, created_by, updated_at, updated_by,
           union_agreement_id, union_classification_id, country,
           filing_status, multiple_jobs, dependent_credits,
           other_income_annual, deductions_annual, w4_pre_2020,
           w4_allowances, fica_exempt, futa_exempt, sin_last3,
           filing_account_id, stub_delivery, payment_method,
           labour_jurisdiction
      from public.employee_payroll_profiles
     where org_id = public.openbooks_query_org_id();
  -- Employment records are reportable; date of birth is not. It exists for ROE
  -- demographics and the stub-password policy, and the schema comment on
  -- employee_roles.birth_date already states it stays out of these views.
  create view openbooks_query.employee_roles with (security_barrier=true) as
    select id, org_id, party_id, employee_number, department_id,
           supervisor_id, trade_id, worker_comp_group_id, hired_on,
           terminated_on, has_benefits, vacation_days_per_year,
           billable_utilization_target, expense_account_id,
           external_payroll_id, is_active, custom, created_at, created_by,
           updated_at, updated_by, job_title
      from public.employee_roles
     where org_id = public.openbooks_query_org_id();
  -- CRM activity rows remain reportable, but private notes never cross the
  -- governed-query boundary. The flag is retained so reports can count or
  -- filter private rows without seeing their body.
  create view openbooks_query.crm_activities with (security_barrier=true) as
    select id, org_id, kind, status, subject,
           case when is_private then null else body end as body,
           priority, owner_user_id, assigned_user_id, starts_at, ends_at,
           due_at, completed_at, reminder_at, duration_minutes, recurrence,
           is_private, custom, created_at, created_by, updated_at, updated_by
      from public.crm_activities
     where org_id = public.openbooks_query_org_id();
  -- Time rows remain available for hours, rates, billing, and payroll
  -- reporting, but private memo text is redacted in the governed catalog.
  create view openbooks_query.time_entries with (security_barrier=true) as
    select id, org_id, employee_party_id, worked_on, hours, time_type_id,
           item_id, project_id, project_task_id, department_id,
           case when memo_is_private then null else memo end as memo,
           memo_is_private, is_billable, cost_rate, bill_rate, status,
           approved_by, approved_at, cost_journal_entry_id, invoiced_by_line_id,
           payroll_batch_ref, created_at, created_by, updated_at, updated_by,
           custom, overhead_journal_entry_id, field_ticket_id,
           labor_cost_rate_id, wage_rate, wage_currency, wage_fx_rate,
           cost_rate_currency, cost_rate_subsidiary_id, bill_rate_source_rate,
           bill_rate_source_currency, bill_rate_fx_rate, bill_rate_currency,
           bill_rate_book_id, bill_rate_version_id, bill_rate_line_id,
           billing_status, costing_basis, started_at, rejection_reason,
           amends_entry_id
      from public.time_entries
     where org_id = public.openbooks_query_org_id();
  -- Membership rows inherit tenancy through their owning tax group. They
  -- deliberately cannot use the generic catalog path because the base table
  -- has no org_id of its own.
  create view openbooks_query.tax_group_members with (security_barrier=true) as
    select member.id, member.tax_group_id, member.tax_code_id, member.sequence
      from public.tax_group_members member
      join public.tax_groups tax_group on tax_group.id = member.tax_group_id
     where tax_group.org_id = public.openbooks_query_org_id();

  -- Every relation in the governed schema is a reviewed, org-filtered view,
  -- so the read role gets SELECT on all of them in one statement. A per-name
  -- grant list omitted payment_pending_clawbacks (created between the two
  -- loops) and silently left it unreadable.
  grant select on all tables in schema openbooks_query to openbooks_read;
end;
$_$;


--
-- Name: openbooks_repair_document_sequences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_repair_document_sequences() RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
  rec record;
  repair_prefix text;
  merged_next integer;
  issued_max bigint;
BEGIN
  -- Kinds that already have a single org-wide row only need their watermark
  -- raised: treat the stored counter as consumed so the repair never lowers
  -- what any tenant has already reached. Only never-watermarked rows (the
  -- pre-0032 state) are touched, so a rerun never reinterprets a counter the
  -- repair itself normalized.
  UPDATE public.number_sequences seq
     SET allocated_through = seq.next_number
   WHERE seq.allocated_through = 0
     AND seq.subsidiary_id IS NULL
     AND NOT EXISTS (
       SELECT 1
         FROM public.number_sequences other
        WHERE other.org_id = seq.org_id
          AND other.document_kind = seq.document_kind
          AND other.subsidiary_id IS NOT NULL);

  -- Kinds that still carry per-subsidiary rows collapse into ONE org-wide
  -- row. Output continuity: the org-wide prefix wins when present (otherwise
  -- the lexicographically greatest per-subsidiary prefix), gapless survives
  -- if any row requested it, and the counter moves past BOTH every configured
  -- counter AND every document number ever issued under the surviving prefix
  -- — so the merged row can never reproduce an existing document number.
  -- The merge is an explicit update-then-insert (this runs before the new
  -- unique constraint exists, so conflict targets are not yet available);
  -- it is migration/maintenance-time code with no concurrent writers.
  FOR rec IN
    SELECT org_id,
           document_kind,
           bool_or(gapless) AS gapless,
           max(prefix) FILTER (WHERE subsidiary_id IS NULL) AS org_prefix,
           max(next_number) FILTER (WHERE subsidiary_id IS NULL) AS org_next,
           max(prefix) AS any_prefix
      FROM public.number_sequences
     GROUP BY org_id, document_kind
     HAVING count(*) FILTER (WHERE subsidiary_id IS NOT NULL) > 0
  LOOP
    repair_prefix := COALESCE(rec.org_prefix, rec.any_prefix);
    -- The highest numeric suffix already issued under the surviving prefix.
    -- A prefix containing LIKE metacharacters can only over-match into a
    -- strictly larger floor — gaps, never collisions. The stored counter is
    -- last-issued semantics, so the merge floors it at this value and the
    -- next allocation hands out exactly the number after the last one issued.
    SELECT max(substring(d.document_number FROM length(repair_prefix) + 1)::bigint)
      INTO issued_max
      FROM public.documents d
     WHERE d.org_id = rec.org_id
       AND d.kind = rec.document_kind
       AND d.document_number LIKE repair_prefix || '%'
       AND substring(d.document_number FROM length(repair_prefix) + 1) ~ '^[0-9]+$';
    merged_next := GREATEST(COALESCE(rec.org_next, 1), COALESCE(issued_max, 0));

    UPDATE public.number_sequences seq
       SET prefix = repair_prefix,
           next_number = GREATEST(seq.next_number, merged_next),
           allocated_through = GREATEST(seq.allocated_through, merged_next),
           gapless = rec.gapless
     WHERE seq.org_id = rec.org_id
       AND seq.document_kind = rec.document_kind
       AND seq.subsidiary_id IS NULL;
    IF NOT FOUND THEN
      INSERT INTO public.number_sequences
        (org_id, document_kind, subsidiary_id, prefix, next_number, allocated_through)
      VALUES
        (rec.org_id, rec.document_kind, NULL, repair_prefix, merged_next, merged_next);
    END IF;
  END LOOP;

  -- The merged org-wide rows now own every counter; the per-subsidiary rows
  -- are configuration, not history, and nothing else references them.
  DELETE FROM public.number_sequences WHERE subsidiary_id IS NOT NULL;
END
$_$;


--
-- Name: FUNCTION openbooks_repair_document_sequences(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_repair_document_sequences() IS 'openbooks:document_sequence_global_repair:v1 - deterministic merge of legacy per-subsidiary number_sequences rows into the org-wide row; rerunnable';


--
-- Name: openbooks_reversal_mirrors(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_reversal_mirrors(p_org_id uuid, p_original_id uuid, p_reversal_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
           select 1
             from public.journal_lines v
            where v.org_id = p_org_id and v.entry_id = p_reversal_id
         )
     and not exists (
           select 1
             from public.journal_lines o
            where o.org_id = p_org_id and o.entry_id = p_original_id
              and not exists (
                    select 1
                      from public.journal_lines v
                     where v.org_id = p_org_id and v.entry_id = p_reversal_id
                       and v.line_number = o.line_number
                       and v.account_id is not distinct from o.account_id
                       and v.subsidiary_id is not distinct from o.subsidiary_id
                       and v.amount is not distinct from -o.amount
                       and v.currency is not distinct from o.currency
                       and v.txn_amount is not distinct from -o.txn_amount
                       and v.fx_rate is not distinct from o.fx_rate
                       and v.party_id is not distinct from o.party_id
                       and v.department_id is not distinct from o.department_id
                       and v.project_id is not distinct from o.project_id
                       and v.location_id is not distinct from o.location_id
                       and v.class_id is not distinct from o.class_id
                       and v.equipment_unit_id is not distinct from o.equipment_unit_id
                       and v.payment_card_id is not distinct from o.payment_card_id
                       and v.tax_code_id is not distinct from o.tax_code_id
                       and v.extra_dims is not distinct from o.extra_dims
                       and v.quantity is not distinct from -o.quantity
                  )
         )
     and not exists (
           select 1
             from public.journal_lines v
            where v.org_id = p_org_id and v.entry_id = p_reversal_id
              and not exists (
                    select 1
                      from public.journal_lines o
                     where o.org_id = p_org_id and o.entry_id = p_original_id
                       and v.line_number = o.line_number
                       and v.account_id is not distinct from o.account_id
                       and v.subsidiary_id is not distinct from o.subsidiary_id
                       and v.amount is not distinct from -o.amount
                       and v.currency is not distinct from o.currency
                       and v.txn_amount is not distinct from -o.txn_amount
                       and v.fx_rate is not distinct from o.fx_rate
                       and v.party_id is not distinct from o.party_id
                       and v.department_id is not distinct from o.department_id
                       and v.project_id is not distinct from o.project_id
                       and v.location_id is not distinct from o.location_id
                       and v.class_id is not distinct from o.class_id
                       and v.equipment_unit_id is not distinct from o.equipment_unit_id
                       and v.payment_card_id is not distinct from o.payment_card_id
                       and v.tax_code_id is not distinct from o.tax_code_id
                       and v.extra_dims is not distinct from o.extra_dims
                       and v.quantity is not distinct from -o.quantity
                  )
         )
$$;


--
-- Name: FUNCTION openbooks_reversal_mirrors(p_org_id uuid, p_original_id uuid, p_reversal_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_reversal_mirrors(p_org_id uuid, p_original_id uuid, p_reversal_id uuid) IS 'openbooks:reversal-mirror:v1 - true when the reversal entry lines mirror-negate the original entry lines (0166); memo/due-date/custom metadata excluded';


--
-- Name: openbooks_sandbox_wipe_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_sandbox_wipe_allowed(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on'
     and exists (
       select 1 from orgs where id = p_org_id and env_kind = 'sandbox'
     )
$$;


--
-- Name: FUNCTION openbooks_sandbox_wipe_allowed(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_sandbox_wipe_allowed(p_org_id uuid) IS 'Returns true only when the transaction-local wipe GUC is on and the target organization is a sandbox; DELETE-only trigger exemptions must call this helper.';


--
-- Name: openbooks_scheduler_outbox_replay_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_scheduler_outbox_replay_allowed(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(
    p_org_id IS NOT NULL
    AND coalesce(current_setting('openbooks.scheduler_outbox_replay_org', true), '') <> ''
    AND current_setting('openbooks.scheduler_outbox_replay_org', true) = p_org_id::text,
    false
  )
$$;


--
-- Name: FUNCTION openbooks_scheduler_outbox_replay_allowed(p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.openbooks_scheduler_outbox_replay_allowed(p_org_id uuid) IS 'True only inside a transaction whose replay routine pinned this exact organization.';


--
-- Name: openbooks_valid_form_sections(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_valid_form_sections(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN jsonb_typeof(value) IS DISTINCT FROM 'array' THEN false
    ELSE NOT EXISTS (
      SELECT 1
        FROM jsonb_array_elements(value) section
       WHERE jsonb_typeof(section) IS DISTINCT FROM 'object'
          OR jsonb_typeof(section->'fields') IS DISTINCT FROM 'array'
    )
  END
$$;


--
-- Name: openbooks_valid_report_attachments(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_valid_report_attachments(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN jsonb_typeof(value) IS DISTINCT FROM 'array' THEN false
    ELSE NOT EXISTS (
      SELECT 1
        FROM jsonb_array_elements(value) attachment
       WHERE jsonb_typeof(attachment) IS DISTINCT FROM 'object'
          OR jsonb_typeof(attachment->'slug') IS DISTINCT FROM 'string'
          OR length(btrim(attachment->>'slug')) = 0
    )
  END
$$;


--
-- Name: openbooks_validate_depreciation_line_input(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_validate_depreciation_line_input() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  input_row depreciation_inputs%rowtype;
  schedule_method text;
begin
  if new.source in ('formula', 'imported') then return new; end if;
  select * into input_row from depreciation_inputs where id = new.input_id;
  if not found
     or input_row.voided_at is not null
     or input_row.org_id <> new.org_id
     or input_row.schedule_id <> new.schedule_id
     or input_row.period_id <> new.period_id then
    raise exception 'depreciation line input evidence does not match its schedule and period';
  end if;
  select method into schedule_method from depreciation_schedules where id = new.schedule_id;
  if (new.source = 'manual' and (input_row.kind <> 'manual' or schedule_method <> 'manual'))
     or (new.source = 'production_usage' and (input_row.kind <> 'production_usage' or schedule_method <> 'units_of_production')) then
    raise exception 'depreciation line source does not match its method evidence';
  end if;
  return new;
end;
$$;


--
-- Name: order_line_cancellations_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_line_cancellations_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'order_line_cancellations is append-only';
END $$;


--
-- Name: ownership_evidence_policy_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ownership_evidence_policy_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM 1
    FROM public.subsidiary_ownership_interests policy
   WHERE policy.id = NEW.interest_id
     AND policy.org_id = NEW.org_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ownership evidence must reference a policy of the same organization'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION ownership_evidence_policy_fence(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ownership_evidence_policy_fence() IS 'openbooks:ownership_evidence_policy_fence:v1 - holds a FOR SHARE lock on the ownership policy from the first evidence insert so material policy edits serialize with first-use consolidation';


--
-- Name: ownership_interest_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ownership_interest_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE actual_parent uuid; bad_account boolean; approved_close boolean:=false;
BEGIN
 SELECT parent_id INTO actual_parent FROM subsidiaries WHERE id=NEW.subsidiary_id AND org_id=NEW.org_id AND is_active AND NOT is_elimination;
 IF actual_parent IS DISTINCT FROM NEW.parent_subsidiary_id OR NOT EXISTS(SELECT 1 FROM subsidiaries WHERE id=NEW.parent_subsidiary_id AND org_id=NEW.org_id AND is_active AND NOT is_elimination) THEN RAISE EXCEPTION 'ownership interest must follow the active tenant consolidation hierarchy'; END IF;
 SELECT EXISTS(SELECT 1 FROM unnest(array_remove(ARRAY[NEW.investment_account_id,NEW.equity_income_account_id,NEW.distribution_account_id,NEW.distribution_income_account_id,NEW.nci_equity_account_id,NEW.nci_income_account_id,NEW.goodwill_account_id,NEW.fair_value_adjustment_account_id],NULL)) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM accounts a WHERE a.id=wanted.id AND a.org_id=NEW.org_id AND a.is_active AND NOT a.is_summary)) INTO bad_account;
 IF bad_account THEN RAISE EXCEPTION 'ownership accounts must be active postable accounts in the tenant'; END IF;
 IF NEW.method='full' AND NEW.ownership_percent<100 AND (NEW.nci_equity_account_id IS NULL OR NEW.nci_income_account_id IS NULL) THEN RAISE EXCEPTION 'full consolidation below 100 percent requires NCI equity and income accounts'; END IF;
 IF NEW.method='full' AND (NEW.goodwill_account_id IS NULL OR NEW.fair_value_adjustment_account_id IS NULL) THEN RAISE EXCEPTION 'full consolidation requires goodwill and fair-value adjustment accounts'; END IF;
 IF NEW.distribution_account_id IS NOT NULL AND NEW.distribution_income_account_id IS NULL THEN RAISE EXCEPTION 'distribution income account is required when a distribution account is configured'; END IF;
 -- A new full policy alone does not book a new acquisition or reopen the
 -- disposed reporting window. Do not silently reconsolidate from stale basis.
 IF NEW.method='full' AND NEW.is_active AND EXISTS(SELECT 1 FROM consolidation_control_losses loss WHERE loss.org_id=NEW.org_id AND loss.subsidiary_id=NEW.subsidiary_id AND loss.reversed_by_change_id IS NULL AND NEW.effective_from>loss.effective_on) THEN RAISE EXCEPTION 'a full reacquisition requires new acquisition accounting; a policy-only change cannot reopen the disposed group. For an erroneous disposal use its approved correction in Accounting changes'; END IF;
 IF TG_OP='UPDATE' THEN
  approved_close:=NEW.effective_to IS NOT NULL AND NEW.effective_to>=OLD.effective_from AND (OLD.effective_to IS NULL OR NEW.effective_to<=OLD.effective_to) AND NEW.last_change_id IS DISTINCT FROM OLD.last_change_id AND EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.domain='consolidation' AND f.operation='loss_of_control' AND f.subject_id=OLD.id AND f.effective_on=NEW.effective_to AND f.status='approved') AND (to_jsonb(NEW)-ARRAY['effective_to','last_change_id','updated_at','updated_by']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['effective_to','last_change_id','updated_at','updated_by']);
  approved_close:=approved_close OR (NEW.last_change_id IS DISTINCT FROM OLD.last_change_id AND EXISTS(SELECT 1 FROM financial_changes f JOIN consolidation_control_losses loss ON loss.org_id=f.org_id AND loss.change_id::text=f.payload->>'sourceChangeId' WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.domain='consolidation' AND f.operation='reversal' AND f.status='approved' AND loss.interest_id=OLD.id AND loss.reversed_by_change_id=f.id AND NEW.effective_to IS NOT DISTINCT FROM (loss.measurement->>'originalEffectiveTo')::date) AND (to_jsonb(NEW)-ARRAY['effective_to','last_change_id','updated_at','updated_by']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['effective_to','last_change_id','updated_at','updated_by']));
  approved_close:=approved_close OR (OLD.is_active AND NOT NEW.is_active AND EXISTS(SELECT 1 FROM financial_changes f JOIN consolidation_control_losses loss ON loss.org_id=f.org_id AND loss.change_id::text=f.payload->>'sourceChangeId' WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.domain='consolidation' AND f.operation='reversal' AND f.status='approved' AND loss.retained_interest_id=OLD.id AND loss.reversed_by_change_id=f.id) AND (to_jsonb(NEW)-ARRAY['is_active','last_change_id','updated_at','updated_by']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['is_active','last_change_id','updated_at','updated_by']));
  IF EXISTS(SELECT 1 FROM ownership_consolidation_entries WHERE interest_id=OLD.id) AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by']) AND NOT approved_close THEN RAISE EXCEPTION 'used ownership policy is immutable; propose an approved loss-of-control change or retain the existing historical terms'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION ownership_interest_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ownership_interest_guard() IS 'openbooks:ownership_interest_guard:v2 - hierarchy, account, method, and used-policy immutability checks for ownership interests; effective-date exclusivity moved to the subsidiary_ownership_interests_no_active_overlap exclusion constraint';


--
-- Name: party_subsidiary_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_subsidiary_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from parties p where p.id = new.party_id and p.org_id = new.org_id) then
    raise exception 'party belongs to another organization' using errcode = '23514';
  end if;
  if not exists (
    select 1 from subsidiaries s
     where s.id = new.subsidiary_id and s.org_id = new.org_id and not s.is_elimination
  ) then
    raise exception 'party subsidiary is invalid' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: pay_component_earning_classifications_prevent_orphan_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_component_earning_classifications_prevent_orphan_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pay_components
     WHERE org_id = OLD.org_id AND id = OLD.pay_component_id
  ) THEN
    RAISE EXCEPTION 'pay component classifications cannot be deleted independently';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: pay_component_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_component_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Permit the owning tenant's cascade deletion, never an ordinary component
  -- deletion that would SET NULL on historical stub lines.
  IF TG_OP = 'DELETE' AND NOT EXISTS (
    SELECT 1 FROM public.orgs WHERE id = OLD.org_id
  ) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW IS DISTINCT FROM OLD THEN
      -- All component inputs participate in calculation freshness, including
      -- prospective flags whose monetary results are already snapshotted.
      NEW.updated_at := clock_timestamp();
    END IF;
    IF ROW(NEW.id, NEW.org_id, NEW.kind, NEW.system_key, NEW.country,
           NEW.taxable, NEW.tax_treatment)
       IS NOT DISTINCT FROM
       ROW(OLD.id, OLD.org_id, OLD.kind, OLD.system_key, OLD.country,
           OLD.taxable, OLD.tax_treatment) THEN
      RETURN NEW;
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pay_stub_lines l
    JOIN public.pay_stubs s ON s.org_id = l.org_id AND s.id = l.stub_id
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
     WHERE l.org_id = OLD.org_id AND l.component_id = OLD.id
       AND r.run_status IN ('committed', 'voided')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'pay_component_historical_policy',
      MESSAGE = 'Pay component tax classification is fixed after committed payroll. Preserve this component and use a new policy for future payroll; historical corrections require a controlled adjustment.';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  -- Raw SQL writers must also invalidate an existing calculation. A caller's
  -- old transaction timestamp must not hide a later policy edit.
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END
$$;


--
-- Name: pay_component_non_cash_account_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_component_non_cash_account_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.payment_kind IS DISTINCT FROM OLD.payment_kind AND EXISTS (
    SELECT 1 FROM public.hrm_benefit_programs p WHERE p.org_id = OLD.org_id AND p.pay_component_id = OLD.id
      AND (p.status = 'active' OR EXISTS (
        SELECT 1 FROM public.hrm_benefit_awards a WHERE a.org_id = p.org_id AND a.program_id = p.id
          AND a.status IN ('approved', 'queued', 'delivered')
      ))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'An active benefit program or approved benefit obligation uses this cash representation; preserve its component and create a new program and component for a different delivery policy.';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.payment_kind IS DISTINCT FROM OLD.payment_kind AND EXISTS (
    SELECT 1 FROM public.pay_stub_lines l JOIN public.pay_stubs s ON s.org_id = l.org_id AND s.id = l.stub_id
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
    WHERE l.org_id = OLD.org_id AND l.component_id = OLD.id AND r.run_status IN ('committed', 'voided')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A pay component cash representation is fixed after committed payroll; preserve this component and create a new component for future earnings.';
  END IF;
  IF NEW.payment_kind = 'non_cash' AND NOT EXISTS (
    SELECT 1 FROM public.accounts a WHERE a.org_id = NEW.org_id AND a.id = NEW.non_cash_account_id
      AND a.is_active AND NOT a.is_summary
      AND a.type IN ('asset_current_other', 'asset_other', 'liability_current_other', 'liability_long_term')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A non-cash earning requires an active posting prepaid asset or provider clearing liability; an expense account would count the benefit twice.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: pay_components_create_earning_classification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_components_create_earning_classification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  INSERT INTO public.pay_component_earning_classifications (org_id, pay_component_id)
  VALUES (NEW.org_id, NEW.id);
  RETURN NEW;
END;
$$;


--
-- Name: pay_derived_rules_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_derived_rules_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.org_id, NEW.code, NEW.name, NEW.component_id, NEW.trigger,
      NEW.time_type_id, NEW.project_id, NEW.department_id,
      NEW.equipment_unit_id, NEW.item_id, NEW.trade_id, NEW.job_title,
      NEW.billable_only, NEW.included_job_titles, NEW.excluded_job_titles,
      NEW.quantity_mode, NEW.rate_mode, NEW.rate_value, NEW.costing_mode,
      NEW.effective_from, NEW.sequence
    ) IS DISTINCT FROM ROW(
      OLD.org_id, OLD.code, OLD.name, OLD.component_id, OLD.trigger,
      OLD.time_type_id, OLD.project_id, OLD.department_id,
      OLD.equipment_unit_id, OLD.item_id, OLD.trade_id, OLD.job_title,
      OLD.billable_only, OLD.included_job_titles, OLD.excluded_job_titles,
      OLD.quantity_mode, OLD.rate_mode, OLD.rate_value, OLD.costing_mode,
      OLD.effective_from, OLD.sequence
    ) THEN
      RAISE EXCEPTION
        'derived payroll rules are immutable; close it and create a new effective-dated rule'
        USING ERRCODE = '55000';
    END IF;

    -- A policy window may be shortened (the route closes it immediately before
    -- inserting a successor), but never extended after the fact. Activation is
    -- intentionally mutable so a newly-created disabled rule can be enabled.
    IF OLD.effective_to IS NOT NULL
       AND (NEW.effective_to IS NULL OR NEW.effective_to > OLD.effective_to) THEN
      RAISE EXCEPTION
        'derived payroll rule windows may only be shortened; create a new effective-dated rule'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION pay_derived_rules_immutable_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pay_derived_rules_immutable_guard() IS 'openbooks:pay_derived_rules_immutable_guard:v1 - derived-pay policy snapshots are immutable; only window closure, activation, and audit timestamps may change in place';


--
-- Name: pay_runs_sync_voided_document(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_runs_sync_voided_document() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.kind = 'pay_run' AND NEW.status = 'voided' THEN
    UPDATE public.pay_runs
       SET run_status = 'voided',
           updated_at = now(),
           updated_by = COALESCE(NEW.voided_by, NEW.updated_by)
     WHERE document_id = NEW.id
       AND org_id = NEW.org_id
       AND run_status <> 'voided';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION pay_runs_sync_voided_document(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pay_runs_sync_voided_document() IS 'openbooks: mirror a pay_run document void into pay_runs.run_status so the live-period key releases while the historical run remains immutable';


--
-- Name: pay_stub_country_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_stub_country_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Rolling-deploy compatibility for old writers. New calculation code
    -- supplies the resolved pack country and its explicit source.
    IF NEW.country IS NULL THEN
      NEW.country := public.payroll_legacy_region_country(NEW.province);
      NEW.country_source := CASE WHEN NEW.country IS NULL THEN 'unknown' ELSE 'legacy_region' END;
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.country, NEW.country_source) IS DISTINCT FROM ROW(OLD.country, OLD.country_source) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_historical_country',
      MESSAGE = 'Payroll country is captured at calculation. Recalculate editable payroll or use a controlled correction; do not overwrite historical attribution.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: pay_stub_filing_account_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_stub_filing_account_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.filing_account_source = 'unknown' THEN
      -- Old application writers still capture attribution at INSERT, before
      -- any subsequent profile/default edit. This is not a legacy backfill.
      SELECT coalesce(prof.filing_account_id,
        (SELECT fa.id FROM public.payroll_filing_accounts fa
          WHERE fa.org_id = NEW.org_id AND fa.country = NEW.country
            AND fa.is_active AND fa.is_default))
        INTO NEW.filing_account_id
        FROM public.employee_payroll_profiles prof
       WHERE prof.org_id = NEW.org_id AND prof.employee_party_id = NEW.employee_party_id;
      NEW.filing_account_source := 'insertion';
    END IF;
    IF NEW.filing_account_source NOT IN ('calculation', 'insertion') THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_historical_filing_account',
        MESSAGE = 'New payroll must capture its filing account at calculation or insertion.';
    END IF;
  ELSE
    IF ROW(NEW.org_id, NEW.filing_account_id, NEW.filing_account_source, NEW.filing_account_evidence)
       IS NOT DISTINCT FROM
       ROW(OLD.org_id, OLD.filing_account_id, OLD.filing_account_source, OLD.filing_account_evidence) THEN
      RETURN NEW;
    END IF;
    IF OLD.filing_account_source <> 'unknown' OR NEW.filing_account_source <> 'reconciled'
       OR NEW.updated_by IS NULL
       OR (to_jsonb(NEW) - ARRAY['filing_account_id','filing_account_source','filing_account_evidence','updated_at','updated_by'])
          IS DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['filing_account_id','filing_account_source','filing_account_evidence','updated_at','updated_by']) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_historical_filing_account',
        MESSAGE = 'Payroll filing attribution is immutable. Only unknown legacy attribution can be reconciled with original evidence, a reason, and an actor.';
    END IF;
    NEW.updated_at := clock_timestamp();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
    VALUES (NEW.org_id, 'pay_stubs', NEW.id, 'update',
      jsonb_build_object('operation', 'reconcile_filing_account', 'before', to_jsonb(OLD),
                        'after', to_jsonb(NEW), 'evidence', NEW.filing_account_evidence), NEW.updated_by);
  END IF;

  IF NEW.filing_account_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.payroll_filing_accounts fa
     WHERE fa.org_id = NEW.org_id AND fa.id = NEW.filing_account_id
       AND fa.country = NEW.country
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_filing_account_country',
      MESSAGE = 'Payroll filing account must belong to the stub organization and country.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: pay_stub_line_expense_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_stub_line_expense_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.expense_account_source <> 'unknown'
     AND ROW(NEW.expense_account_id, NEW.expense_account_source)
         IS DISTINCT FROM ROW(OLD.expense_account_id, OLD.expense_account_source) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_line_expense_immutable',
      MESSAGE = 'The expense account a committed payroll line was costed to is immutable.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: pay_stub_line_liability_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_stub_line_liability_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE committed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.liability_account_source = 'reconciled' THEN
      RAISE EXCEPTION 'Liability reconciliation must resolve an existing unknown payroll line.' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.org_id,NEW.liability_account_id,NEW.liability_account_source,NEW.liability_account_evidence)
     IS NOT DISTINCT FROM ROW(OLD.org_id,OLD.liability_account_id,OLD.liability_account_source,OLD.liability_account_evidence) THEN
    RETURN NEW;
  END IF;
  IF OLD.liability_account_source <> 'unknown' THEN
    RAISE EXCEPTION 'The liability account a committed payroll line accrued to is immutable.' USING ERRCODE='23514';
  END IF;
  SELECT r.run_status='committed' INTO committed FROM public.pay_stubs s
    JOIN public.pay_runs r ON r.org_id=s.org_id AND r.document_id=s.pay_run_document_id
   WHERE s.org_id=OLD.org_id AND s.id=OLD.stub_id;
  IF NEW.liability_account_source = 'commit' AND committed IS FALSE AND NEW.org_id=OLD.org_id THEN
    RETURN NEW; -- normal commit captures its account before marking the run committed
  END IF;
  IF NEW.liability_account_source <> 'reconciled' OR committed IS NOT TRUE OR NEW.updated_by IS NULL
     OR OLD.kind NOT IN ('deduction','employer_contribution')
     OR (to_jsonb(NEW) - ARRAY['liability_account_id','liability_account_source','liability_account_evidence','updated_at','updated_by'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['liability_account_id','liability_account_source','liability_account_evidence','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'Only unknown committed liabilities may be reconciled, with original evidence and without changing payroll amounts.' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.liability_account_id
    AND NOT a.is_summary AND a.type LIKE 'liability%') THEN
    RAISE EXCEPTION 'Historical payroll liability must reference a posting liability account in the same organization.' USING ERRCODE='23514';
  END IF;
  NEW.updated_at := clock_timestamp();
  INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
  VALUES(NEW.org_id,'pay_stub_lines',NEW.id,'update',jsonb_build_object(
    'operation','reconcile_liability_account','before',to_jsonb(OLD),'after',to_jsonb(NEW),
    'evidence',NEW.liability_account_evidence),NEW.updated_by);
  RETURN NEW;
END
$$;


--
-- Name: pay_stub_line_payment_kind_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_stub_line_payment_kind_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE component_payment_kind text; component_non_cash_account uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.kind = 'earning' AND NEW.component_id IS NOT NULL THEN
      SELECT payment_kind, non_cash_account_id INTO component_payment_kind, component_non_cash_account
        FROM public.pay_components WHERE org_id = NEW.org_id AND id = NEW.component_id;
      IF component_payment_kind IS NOT NULL AND (
        NEW.payment_kind IS DISTINCT FROM component_payment_kind OR
        (component_payment_kind = 'non_cash' AND NEW.non_cash_account_id IS DISTINCT FROM component_non_cash_account)
      ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'The calculated earning cash representation must match its configured component. Update the payroll application and recalculate; a non-cash benefit must never also be paid as cash.';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.payment_kind, NEW.non_cash_account_id) IS DISTINCT FROM ROW(OLD.payment_kind, OLD.non_cash_account_id)
     AND EXISTS (SELECT 1 FROM public.pay_stubs s JOIN public.pay_runs r
       ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
       WHERE s.org_id = OLD.org_id AND s.id = OLD.stub_id AND r.run_status IN ('committed', 'voided')) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'The cash representation and clearing account of a committed payroll line are immutable; use a correcting payroll run.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: pay_stub_line_remittance_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_stub_line_remittance_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_trusted_replay boolean;
BEGIN
  -- This is the same paired, transaction-local authority the document-line,
  -- posted-document and journal guards admit: a source-asserted party merge
  -- re-points frozen destinations to the survivor (absorbed and survivor are
  -- the same economic party, so history follows). Migration-only or
  -- amend-only callers remain blocked; no ordinary writer can turn either
  -- setting into an edit bypass by itself.
  v_trusted_replay :=
    coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on';
  IF v_trusted_replay THEN
    RETURN NEW;
  END IF;
  IF OLD.remittance_party_id IS NOT NULL
     AND NEW.remittance_party_id IS DISTINCT FROM OLD.remittance_party_id THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_line_remittance_immutable',
      MESSAGE = 'The remittance destination a committed payroll line accrued to is immutable.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: payment_acceptance_account_reference_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_acceptance_account_reference_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  account_row record;
  rule_row record;
BEGIN
  IF TG_TABLE_NAME = 'psp_provider_configs' THEN
    IF NEW.default_bank_account_id IS NOT NULL THEN
      SELECT org_id, type, is_active, is_summary
        INTO account_row
        FROM public.accounts
       WHERE id = NEW.default_bank_account_id;
      IF NOT FOUND OR account_row.org_id IS DISTINCT FROM NEW.org_id
         OR account_row.type IS DISTINCT FROM 'asset_bank'
         OR NOT account_row.is_active OR account_row.is_summary THEN
        RAISE EXCEPTION 'provider default bank account must be an active, postable asset_bank account owned by the provider organization'
          USING ERRCODE = '23514';
      END IF;
    END IF;
    IF NEW.surcharge_rule_id IS NOT NULL THEN
      SELECT org_id, is_active, provider
        INTO rule_row
        FROM public.payment_surcharge_rules
       WHERE id = NEW.surcharge_rule_id;
      IF NOT FOUND OR rule_row.org_id IS DISTINCT FROM NEW.org_id
         OR NOT rule_row.is_active
         OR (rule_row.provider IS NOT NULL AND rule_row.provider IS DISTINCT FROM NEW.provider) THEN
        RAISE EXCEPTION 'provider surcharge rule must be active, provider-compatible, and owned by the provider organization'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'payment_surcharge_rules' THEN
    SELECT org_id, type, is_active, is_summary
      INTO account_row
      FROM public.accounts
     WHERE id = NEW.fee_income_account_id;
    IF NOT FOUND OR account_row.org_id IS DISTINCT FROM NEW.org_id
       OR account_row.type NOT IN ('income', 'income_other')
       OR NOT account_row.is_active OR account_row.is_summary THEN
      RAISE EXCEPTION 'surcharge fee account must be an active, postable income account owned by the rule organization'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'payment_links' THEN
    SELECT org_id, type, is_active, is_summary
      INTO account_row
      FROM public.accounts
     WHERE id = NEW.bank_account_id;
    IF NOT FOUND OR account_row.org_id IS DISTINCT FROM NEW.org_id
       OR account_row.type IS DISTINCT FROM 'asset_bank'
       OR NOT account_row.is_active OR account_row.is_summary THEN
      RAISE EXCEPTION 'payment link bank account must be an active, postable asset_bank account owned by the link organization'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION payment_acceptance_account_reference_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payment_acceptance_account_reference_guard() IS 'openbooks:payment_acceptance_account_references:v1 - tenant, active, postable, and account-class guards for hosted payment acceptance references';


--
-- Name: payment_event_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_event_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'payment events are append-only';
end $$;


--
-- Name: payment_file_artifact_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_file_artifact_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.payment_run_id is distinct from old.payment_run_id
     or new.payment_bank_profile_id is distinct from old.payment_bank_profile_id
     or new.payment_format_id is distinct from old.payment_format_id
     or new.parent_payment_file_id is distinct from old.parent_payment_file_id
     or new.sequence_number is distinct from old.sequence_number
     or new.filename is distinct from old.filename
     or new.content_type is distinct from old.content_type
     or new.content_hash is distinct from old.content_hash
     or new.file_id is distinct from old.file_id
     or new.file_version_id is distinct from old.file_version_id
     or new.payment_count is distinct from old.payment_count
     or new.total_amount is distinct from old.total_amount
     or new.currency is distinct from old.currency
     or new.generated_at is distinct from old.generated_at
     or new.generated_by is distinct from old.generated_by then
    raise exception 'generated payment file artifacts are immutable; reprocess into a new file';
  end if;
  return new;
end $$;


--
-- Name: payment_run_item_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_run_item_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_status text;
begin
  select status into v_status from payment_runs where id = coalesce(new.payment_run_id, old.payment_run_id);
  if tg_op = 'DELETE' and v_status not in ('draft', 'pending_approval')
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'payment run items are immutable once the run is approved';
  end if;
  if tg_op = 'UPDATE' and v_status not in ('draft', 'pending_approval') and (
     new.payment_run_id is distinct from old.payment_run_id
     or new.payment_instruction_id is distinct from old.payment_instruction_id
     or new.source_document_id is distinct from old.source_document_id
     or new.source_open_line_id is distinct from old.source_open_line_id
     or new.kind is distinct from old.kind
     or new.gross_amount is distinct from old.gross_amount
     or new.discount_amount is distinct from old.discount_amount
     or new.credit_amount is distinct from old.credit_amount
     or new.payment_amount is distinct from old.payment_amount
     or new.currency is distinct from old.currency
     or new.fx_rate is distinct from old.fx_rate) then
    raise exception 'payment run item composition is immutable once the run is approved';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: payment_run_item_instruction_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_run_item_instruction_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if new.status in ('sent', 'settled') then
    update public.payment_run_items
       set status = 'paid', exclusion_reason = null,
           updated_at = now(), updated_by = new.updated_by
     where org_id = new.org_id
       and payment_run_id = new.payment_run_id
       and payment_instruction_id = new.id
       and status = 'selected';
  elsif new.status in ('returned', 'rejected') then
    update public.payment_run_items
       set status = 'returned', exclusion_reason = null,
           updated_at = now(), updated_by = new.updated_by
     where org_id = new.org_id
       and payment_run_id = new.payment_run_id
       and payment_instruction_id = new.id
       and status in ('selected', 'paid');
  elsif new.status = 'reversed' then
    update public.payment_run_items
       set status = 'reversed', exclusion_reason = null,
           updated_at = now(), updated_by = new.updated_by
     where org_id = new.org_id
       and payment_run_id = new.payment_run_id
       and payment_instruction_id = new.id
       and status in ('selected', 'paid', 'returned');
  elsif new.status = 'cancelled' then
    update public.payment_run_items
       set status = 'excluded',
           exclusion_reason = coalesce(
             nullif(btrim(exclusion_reason), ''),
             'payment instruction cancelled'
           ),
           updated_at = now(), updated_by = new.updated_by
     where org_id = new.org_id
       and payment_run_id = new.payment_run_id
       and payment_instruction_id = new.id
       and status = 'selected';
  end if;

  return new;
end $$;


--
-- Name: payment_run_item_run_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_run_item_run_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if new.status in ('cancelled', 'rejected', 'rolled_back') then
    update public.payment_run_items
       set status = 'excluded',
           exclusion_reason = coalesce(
             nullif(btrim(exclusion_reason), ''),
             'payment run ' || replace(new.status, '_', ' ')
           ),
           updated_at = now(), updated_by = new.updated_by
     where org_id = new.org_id
       and payment_run_id = new.id
       and status = 'selected';
  end if;

  return new;
end $$;


--
-- Name: payroll_employment_coherence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_employment_coherence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE worker uuid;
BEGIN
  IF NEW.employment_id IS NULL THEN
    RETURN NEW;
  END IF;
  -- No person on the row (entitlement_plan_limits non-person scopes): there
  -- is nobody to compare the employment against, so this guard abstains and
  -- the scope CHECK owns the refusal with its precise message.
  IF NEW.employee_party_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT we.worker_party_id INTO worker
    FROM public.worker_employments we
   WHERE we.org_id = NEW.org_id AND we.id = NEW.employment_id;
  -- No row (yet): the composite FK refuses unknown/other-org ids at commit.
  -- This trigger owns only the cross-person refusal, which the FK cannot see.
  IF worker IS NULL THEN
    RETURN NEW;
  END IF;
  IF worker IS DISTINCT FROM NEW.employee_party_id THEN
    RAISE EXCEPTION
      '% employment_id % names an employment of worker %, not employee % — stamp the row with an employment of the row''s own worker',
      TG_TABLE_NAME, NEW.employment_id, worker, NEW.employee_party_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION payroll_employment_coherence_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payroll_employment_coherence_guard() IS 'Payroll employment coherence (0186): refuses any payroll row whose employment_id names an employment of a different worker. Cross-org/unknown ids are the composite tenant FK''s job at commit; this trigger owns only the cross-person refusal and names both ids.';


--
-- Name: payroll_legacy_region_country(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_legacy_region_country(region text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN region = ANY(ARRAY['AB', 'BC', 'MB', 'NB', 'NL', 'NS', 'NT', 'NU', 'ON', 'PE', 'QC', 'SK', 'YT', 'ZZ']::text[]) THEN 'CA'
    WHEN region = ANY(ARRAY['AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'DC', 'FL', 'GA', 'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC', 'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY']::text[]) THEN 'US'
    ELSE NULL
  END
$$;


--
-- Name: payroll_profile_vacation_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_profile_vacation_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NEW.vacation_percent IS NOT NULL OR NEW.vacation_method IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Configure vacation through employee Vacation terms; new payroll profiles contain tax and payroll delivery facts only.';
  END IF;
  RETURN NEW;
 END IF;
 IF (NEW.vacation_percent,NEW.vacation_method) IS DISTINCT FROM (OLD.vacation_percent,OLD.vacation_method) THEN
  RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Vacation policy belongs to effective-dated employee Vacation terms. Edit those terms; payroll profile vacation fields preserve historical evidence.';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: payroll_provider_fulfillment_void_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_provider_fulfillment_void_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'voided' AND OLD.status <> 'voided' AND EXISTS (
    SELECT 1 FROM public.hrm_benefit_awards a JOIN public.hrm_benefit_programs p ON p.org_id = a.org_id AND p.id = a.program_id
    WHERE a.org_id = OLD.org_id AND a.pay_run_document_id = OLD.id AND a.status = 'delivered'
      AND p.delivery_method = 'external' AND a.external_ref IS NOT NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'This payroll run represents a fulfilled non-cash benefit; voiding payroll does not cancel provider fulfillment. Record an adjusting benefit award and correcting payroll run instead.';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: payroll_service_configuration_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_service_configuration_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE row_value jsonb;
BEGIN
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP = 'DELETE' THEN row_value := to_jsonb(OLD); ELSE row_value := to_jsonb(NEW); END IF;
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
 VALUES ((row_value->>'org_id')::uuid,TG_TABLE_NAME,(row_value->>'id')::uuid,lower(TG_OP),
 jsonb_build_object('before',CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,'after',CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END),
 coalesce((row_value->>'updated_by')::uuid,(row_value->>'created_by')::uuid));
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: payroll_service_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_service_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE last_period_end date; target_org uuid; configurations jsonb;
BEGIN
 target_org := CASE WHEN TG_OP = 'INSERT' THEN NEW.org_id ELSE OLD.org_id END;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:payroll-service:' || target_org::text,0));
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 configurations := CASE WHEN TG_OP = 'INSERT' THEN jsonb_build_array(to_jsonb(NEW))
  WHEN TG_OP = 'DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END;
 SELECT max(r.period_end) INTO last_period_end FROM public.pay_runs r JOIN public.pay_stubs s
  ON s.org_id = r.org_id AND s.pay_run_document_id = r.document_id
 LEFT JOIN public.worker_employments e ON e.org_id=s.org_id AND e.id=s.employment_id
 WHERE r.org_id = target_org AND r.run_status IN ('committed','voided') AND EXISTS (
  SELECT 1 FROM jsonb_array_elements(configurations) cfg
  WHERE (cfg->>'employment_id' IS NULL OR s.employment_id=(cfg->>'employment_id')::uuid)
    AND (cfg->>'employer_subsidiary_id' IS NULL OR e.employer_subsidiary_id IS NULL OR e.employer_subsidiary_id=(cfg->>'employer_subsidiary_id')::uuid)
    AND r.period_end >= (cfg->>'effective_from')::date
    AND (cfg->>'effective_to' IS NULL OR r.period_end <= (cfg->>'effective_to')::date)
 );
 IF last_period_end IS NOT NULL THEN
  IF TG_OP IN ('INSERT','DELETE') THEN
   RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'This service configuration affects committed payroll evidence. Preserve its terms and add a replacement effective after the last committed period end.';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['effective_to','updated_at','updated_by']) IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['effective_to','updated_at','updated_by']) OR NEW.effective_to IS NULL OR NEW.effective_to < last_period_end THEN
   RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'This service configuration has committed payroll evidence. Preserve its terms, close its window on or after the last committed period end, and add an effective-dated replacement.';
  END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


--
-- Name: payroll_work_location_allocation_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_work_location_allocation_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row public.payroll_work_location_allocations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_row := OLD;
  ELSE
    v_row := NEW;
  END IF;
  INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
  VALUES (
    v_row.org_id,
    'payroll_work_location_allocations',
    v_row.id,
    lower(TG_OP),
    jsonb_build_object(
      'before', CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
      'after', CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END,
      'reason', v_row.change_reason
    ),
    coalesce(v_row.updated_by, v_row.created_by)
  );
  RETURN NULL;
END
$$;


--
-- Name: payroll_work_location_allocation_lock_committed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_work_location_allocation_lock_committed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_org uuid := coalesce(NEW.org_id, OLD.org_id);
  v_employment uuid := coalesce(NEW.employment_id, OLD.employment_id);
  v_start date := coalesce(NEW.period_start, OLD.period_start);
  v_end date := coalesce(NEW.period_end, OLD.period_end);
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pay_stubs s
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
    JOIN public.documents d ON d.org_id = r.org_id AND d.id = r.document_id
    WHERE s.org_id = v_org AND s.employment_id = v_employment
      AND r.period_start = v_start AND r.period_end = v_end
      AND r.run_status = 'committed' AND d.status <> 'voided'
  ) THEN
    RAISE EXCEPTION 'Payroll work allocation is locked because a payroll run for this employment period is committed'
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: period_module_blocks_write(uuid, uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.period_module_blocks_write(p_org uuid, p_period uuid, p_book uuid, p_subsidiary uuid, p_module text, p_allow_imported boolean) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select case
    when p_allow_imported
      and connector_historical_replay_authorized(p_org)
      then false
    else coalesce(
      (select case
         when p_allow_imported and reason = 'close.importedPeriodLockReason' then false
         when state = 'closed' then true
         when state = 'soft_closed' then true
         when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
         else false
       end
         from period_locks
        where org_id = p_org and period_id = p_period and book_id = p_book
          and subsidiary_id = p_subsidiary and module = p_module),
      (select case
         when p_allow_imported and reason = 'close.importedPeriodLockReason' then false
         when state = 'closed' then true
         when state = 'soft_closed' then true
         when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
         else false
       end
         from period_locks
        where org_id = p_org and period_id = p_period and book_id = p_book
          and subsidiary_id is null and module = p_module),
      false
    )
  end
$$;


--
-- Name: FUNCTION period_module_blocks_write(p_org uuid, p_period uuid, p_book uuid, p_subsidiary uuid, p_module text, p_allow_imported boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.period_module_blocks_write(p_org uuid, p_period uuid, p_book uuid, p_subsidiary uuid, p_module text, p_allow_imported boolean) IS 'Blocks soft-closed and closed-period writes except source-owned imported locks or a database-authenticated connector replay; never changes the lock itself.';


--
-- Name: period_module_is_closed(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.period_module_is_closed(p_org uuid, p_period uuid, p_book uuid, p_subsidiary uuid, p_module text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select case
       when state = 'closed' then true
       when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
       else false
     end
       from period_locks
      where org_id = p_org and period_id = p_period and book_id = p_book
        and subsidiary_id = p_subsidiary and module = p_module),
    (select case
       when state = 'closed' then true
       when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
       else false
     end
       from period_locks
      where org_id = p_org and period_id = p_period and book_id = p_book
        and subsidiary_id is null and module = p_module),
    false
  )
$$;


--
-- Name: period_posting_fence(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.period_posting_fence(p_org uuid, p_period uuid, p_book uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Shared side of the close/posting fence. Transaction-scoped by design:
  -- held until this transaction commits or rolls back, pinning the
  -- [period-state check -> commit] window of every journal mutation against
  -- concurrent lock-state transitions taken through the exclusive side.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('period-lock:' || p_org::text || ':' || p_period::text || ':' || p_book::text, 0)
  );
END;
$$;


--
-- Name: FUNCTION period_posting_fence(p_org uuid, p_period uuid, p_book uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.period_posting_fence(p_org uuid, p_period uuid, p_book uuid) IS 'openbooks:close_posting_fence:v1 - shared side of the period-close serialization fence; conflicts with the exclusive periodScopeAdvisoryLock held by close/reopen writers so a journal write either lands before their final refresh or is rejected after they commit';


--
-- Name: position_changes_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_changes_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'position_changes: evidence rows are immutable; record a new revision instead'
    USING ERRCODE = '23514';
  RETURN NULL;
END $$;


--
-- Name: FUNCTION position_changes_immutable_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_changes_immutable_guard() IS 'openbooks:position_changes_immutable_guard:v1 - evidence immutable; closure lives on position_versions';


--
-- Name: position_changes_provenance_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_changes_provenance_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.positions p
                  WHERE p.id = NEW.position_id AND p.org_id = NEW.org_id) THEN
    RAISE EXCEPTION 'position_changes: position must exist in the same organization'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION position_changes_provenance_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_changes_provenance_guard() IS 'openbooks:position_changes_provenance_guard:v1 - evidence bound to a real position of the same organization';


--
-- Name: position_changes_stamp_txid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_changes_stamp_txid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.change_txid := txid_current();
  RETURN NEW;
END $$;


--
-- Name: FUNCTION position_changes_stamp_txid(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_changes_stamp_txid() IS 'openbooks:position_changes_stamp_txid:v1 - every position evidence event carries its writing top-level transaction id, immutable forever';


--
-- Name: position_closure_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_closure_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  ev_txid bigint;
  ev_array jsonb;
  succ_at timestamptz;
  succ_n integer;
  elem jsonb;
  elem_n integer;
  expected_before jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.superseded_by IS NULL THEN
      RETURN NULL;
    END IF;
  ELSIF OLD.superseded_by IS NOT NULL OR NEW.superseded_by IS NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.closed_by_change_id IS NULL THEN
    RAISE EXCEPTION 'position_versions: closing a version requires closed_by_change_id (the aggregate evidence event)'
      USING ERRCODE = '23514';
  END IF;
  -- Real adjacent successor: exists, strictly newer, starts exactly here.
  -- PL/pgSQL EXECUTE never sets FOUND, so the presence check reads
  -- ROW_COUNT (the 0184 guard's documented rule, repeated here because the
  -- wrong check compiles and silently proves nothing).
  EXECUTE
    'SELECT recorded_at FROM public.position_versions WHERE org_id = $1 AND position_id = $2 AND version_no = $3'
    INTO succ_at
    USING NEW.org_id, NEW.position_id, NEW.superseded_by;
  GET DIAGNOSTICS succ_n = ROW_COUNT;
  IF succ_n = 0 THEN
    RAISE EXCEPTION 'position_versions: superseded_by must name a real version_no of the same position (no dangling pointers)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by <= NEW.version_no THEN
    RAISE EXCEPTION 'position_versions: successor version_no must be strictly newer (rejects self and backwards)'
      USING ERRCODE = '23514';
  END IF;
  IF succ_at IS DISTINCT FROM NEW.recorded_until THEN
    RAISE EXCEPTION 'position_versions: successor recorded_at must equal the closed recorded_until (seamless handoff, no gap or overlap)'
      USING ERRCODE = '23514';
  END IF;
  -- Same-transaction aggregate event naming this exact closure. Plain
  -- SELECT ... INTO sets FOUND (unlike EXECUTE above), so IF NOT FOUND is
  -- correct here.
  SELECT c.change_txid, c.closed_versions INTO ev_txid, ev_array
    FROM public.position_changes c
   WHERE c.id = NEW.closed_by_change_id AND c.org_id = NEW.org_id
     AND c.position_id = NEW.position_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'position_versions: closed_by_change_id must name an evidence event for the same position'
      USING ERRCODE = '23514';
  END IF;
  IF ev_txid IS DISTINCT FROM txid_current() THEN
    RAISE EXCEPTION 'position_versions: closure evidence must be written in the same transaction (change_txid must equal txid_current())'
      USING ERRCODE = '23514';
  END IF;
  -- Exactly one element must name this closure: zero means the event does
  -- not evidence this close; two or more means the array double-counts one
  -- row and no single before-image can be authoritative.
  SELECT count(*) INTO elem_n FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', 'position_versions', 'identity', NEW.position_id::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text);
  IF elem_n = 0 THEN
    RAISE EXCEPTION 'position_versions: evidence event must name this exact closure (table, identity, version_no, row_id) in closed_versions'
      USING ERRCODE = '23514';
  ELSIF elem_n > 1 THEN
    RAISE EXCEPTION 'position_versions: evidence event names this closure more than once (duplicate closed_versions entries)'
      USING ERRCODE = '23514';
  END IF;
  SELECT e INTO elem FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', 'position_versions', 'identity', NEW.position_id::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text)
   LIMIT 1;
  -- Exact prior image, full row, no column subtracted: on UPDATE the element
  -- must carry OLD as it stood before this close; on INSERT of an
  -- already-closed row it must carry NEW as written.
  IF TG_OP = 'INSERT' THEN
    expected_before := to_jsonb(NEW);
  ELSE
    expected_before := to_jsonb(OLD);
  END IF;
  IF NOT (elem ? 'before') OR (elem->'before' IS DISTINCT FROM expected_before) THEN
    RAISE EXCEPTION 'position_versions: evidence event must carry the exact before-image of this closure in closed_versions[].before'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $_$;


--
-- Name: FUNCTION position_closure_evidence_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_closure_evidence_guard() IS 'openbooks:position_closure_evidence_guard:v1 - deferred proof per closure: adjacent strictly-newer successor (ROW_COUNT presence) plus same-transaction aggregate position_changes event (txid-stamped) naming the exact row with its exact before-image';


--
-- Name: position_evidence_closure_reverse_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_evidence_closure_reverse_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  elem jsonb;
  tbl text;
  row_n integer;
BEGIN
  -- Governed amend path (fixture teardown, historical replay): the existing
  -- house mechanism, never a production bypass.
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NULL;
  END IF;
  FOR elem IN SELECT * FROM jsonb_array_elements(NEW.closed_versions) LOOP
    tbl := elem->>'table';
    IF tbl IS DISTINCT FROM 'position_versions' THEN
      RAISE EXCEPTION 'position_changes: closed_versions element names an unknown closure table %', tbl
        USING ERRCODE = '23514';
    END IF;
    IF jsonb_typeof(elem->'before') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'position_changes: closed_versions element for % must carry a before-image object', tbl
        USING ERRCODE = '23514';
    END IF;
    -- count(*) always returns exactly one row, so INTO needs no FOUND dance.
    SELECT count(*) INTO row_n FROM public.position_versions
     WHERE id = (elem->>'row_id')::uuid AND org_id = NEW.org_id
       AND position_id = (elem->>'identity')::uuid
       AND version_no = (elem->>'version_no')::int
       AND position_id = NEW.position_id
       AND superseded_by IS NOT NULL AND closed_by_change_id = NEW.id;
    IF row_n <> 1 THEN
      RAISE EXCEPTION 'position_changes: closed_versions element must name a real closed row of this position linked back to this event (identity %)', elem->>'identity'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END $$;


--
-- Name: FUNCTION position_evidence_closure_reverse_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_evidence_closure_reverse_guard() IS 'openbooks:position_evidence_closure_reverse_guard:v1 - deferred reverse proof per event: every closed_versions element names exactly one really-closed row of this position linked back to this event';


--
-- Name: position_versions_closure_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_versions_closure_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Governed amend path (fixture teardown, historical replay, native merge):
  -- the existing house mechanism, not a new bypass. Production paths never
  -- set openbooks.amend; scratch teardown does, or cascade deletes of a
  -- dropped scratch org could never complete.
  IF TG_OP = 'DELETE'
     AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'position_versions: rows are never deleted; close with a superseding version'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.superseded_by IS NOT NULL THEN
    RAISE EXCEPTION 'position_versions: closed versions are immutable'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by IS NULL AND NEW.recorded_until IS NULL
     AND NEW.closed_by_change_id IS NULL
     AND to_jsonb(NEW) - ARRAY['updated_at','updated_by']
       = to_jsonb(OLD) - ARRAY['updated_at','updated_by'] THEN
    RETURN NEW;
  END IF;
  IF NEW.superseded_by IS NULL OR NEW.recorded_until IS NULL THEN
    RAISE EXCEPTION 'position_versions: live rows are append-only; the only allowed UPDATE is the closing transition (recorded_until + superseded_by) or a pure audit touch'
      USING ERRCODE = '23514';
  END IF;
  -- Explicit allowlist: ONLY recorded_until, superseded_by,
  -- closed_by_change_id, and the audit touch (updated_at/updated_by) may
  -- differ. The successor reference and its evidence are validated deferred
  -- at commit (position_closure_evidence_guard).
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.position_id IS DISTINCT FROM OLD.position_id
     OR NEW.version_no IS DISTINCT FROM OLD.version_no
     OR NEW.title IS DISTINCT FROM OLD.title
     OR NEW.department_id IS DISTINCT FROM OLD.department_id
     OR NEW.location_id IS DISTINCT FROM OLD.location_id
     OR NEW.employer_subsidiary_id IS DISTINCT FROM OLD.employer_subsidiary_id
     OR NEW.job_grade IS DISTINCT FROM OLD.job_grade
     OR NEW.planned_fte IS DISTINCT FROM OLD.planned_fte
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
     OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
     OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'position_versions: closure sets recorded_until + superseded_by + closed_by_change_id (plus audit touch) only'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION position_versions_closure_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.position_versions_closure_guard() IS 'openbooks:position_versions_closure_guard:v1 - closed rows immutable; live rows accept only the closing transition or a pure audit touch; successor + evidence proven deferred by position_closure_evidence_guard';


--
-- Name: positions_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.positions_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.position_code IS DISTINCT FROM OLD.position_code THEN
    RAISE EXCEPTION 'positions: org_id and position_code are immutable (close the position and open a new one, never move it)'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION positions_identity_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.positions_identity_guard() IS 'openbooks:positions_identity_guard:v1 - stable establishment identity; parent keys immutable so version and funding provenance proofs cannot be invalidated';


--
-- Name: posted_document_financial_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posted_document_financial_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
    raise exception 'document % is % — its financial identity (totals, dates, currency, party, kind, number) is immutable outside the governed amend path', old.id, old.status;
  end if;
  return new;
end $$;


--
-- Name: posted_document_status_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posted_document_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Only the hardened per-org check admits a sandbox wipe; a raw session
  -- GUC is settable by any session and would reopen posted -> draft.
  if public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return new;
  end if;
  -- The controlled void writes its evidence (voided_at, voided_by,
  -- void_reason) in the same statement that flips the status; the row CHECK
  -- documents_void_reason_required enforces the same triple at commit.
  if new.status = 'voided'
     and new.voided_at is not null
     and new.voided_by is not null
     and new.void_reason is not null then
    return new;
  end if;
  if coalesce(current_setting('openbooks.amend', true), 'off') = 'on' then
    return new;
  end if;
  raise exception 'document % is posted and immutable — void it through the controlled void path instead of changing its status to %', old.id, new.status;
end $$;


--
-- Name: prepaid_breakage_change_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepaid_breakage_change_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.domain='revenue' AND NEW.operation='expected_breakage_estimate' AND NOT EXISTS(
    SELECT 1 FROM public.usage_prepaid_grants g
      JOIN public.document_lines line ON line.org_id=g.org_id AND line.id=g.source_document_line_id
      JOIN public.documents document ON document.org_id=line.org_id AND document.id=line.document_id
      JOIN public.performance_obligations obligation ON obligation.org_id=line.org_id AND obligation.document_line_id=line.id
      JOIN public.revenue_contracts contract ON contract.org_id=obligation.org_id AND contract.id=obligation.contract_id
    WHERE g.org_id=NEW.org_id AND g.id=(NEW.payload->>'grantId')::uuid AND contract.id=NEW.subject_id
      AND coalesce(contract.subsidiary_id,line.subsidiary_id,document.subsidiary_id)=NEW.subsidiary_id
      AND NEW.payload->'requiredSubsidiaryIds'=jsonb_build_array(NEW.subsidiary_id::text)
      AND jsonb_typeof(NEW.before_state->'estimates')='array'
  ) THEN RAISE EXCEPTION 'breakage estimate must bind to its prepaid grant, revenue contract and legal entity'; END IF;
  RETURN NEW;
END $$;


--
-- Name: price_level_activation_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.price_level_activation_maintenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Clone replay copies the source activation periods immediately after the
    -- price levels; creating a new period here would duplicate that evidence.
    IF public.openbooks_clone_authority() THEN
      RETURN NEW;
    END IF;
    -- A level born inactive was never offered: no period until activated.
    -- Otherwise the standing offer opens at -infinity (see 0327).
    IF NEW.is_active THEN
      INSERT INTO public.price_level_activation_history (org_id, price_level_id, active_from, opened_at)
      VALUES (NEW.org_id, NEW.id, '-infinity'::date, now());
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.is_active AND NOT NEW.is_active THEN
    UPDATE public.price_level_activation_history
       SET active_to = current_date, closed_at = now(), updated_at = now()
     WHERE org_id = NEW.org_id AND price_level_id = NEW.id AND active_to IS NULL;
  ELSIF NOT OLD.is_active AND NEW.is_active THEN
    INSERT INTO public.price_level_activation_history (org_id, price_level_id, active_from, opened_at)
    SELECT NEW.org_id, NEW.id, current_date, now()
     WHERE NOT EXISTS (
       SELECT 1 FROM public.price_level_activation_history h
        WHERE h.org_id = NEW.org_id AND h.price_level_id = NEW.id AND h.active_to IS NULL
     );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: primary_book_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.primary_book_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  source_org uuid;
  target_org uuid;
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    IF tg_op = 'DELETE' THEN RETURN old; END IF;
    RETURN new;
  END IF;
  IF tg_op = 'DELETE' THEN
    IF NOT old.is_primary OR public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    source_org := old.org_id;
  ELSIF tg_op = 'INSERT' THEN
    IF NOT new.is_primary THEN RETURN new; END IF;
    target_org := new.org_id;
  ELSE
    -- A name, code, activation, or posting-policy edit does not change which
    -- book is authoritative. Keep those existing lifecycle controls intact.
    IF new.is_primary = old.is_primary AND new.org_id = old.org_id AND new.id = old.id THEN
      RETURN new;
    END IF;
    IF old.is_primary THEN source_org := old.org_id; END IF;
    IF new.is_primary THEN target_org := new.org_id; END IF;
  END IF;
  -- A pre-existing REPEATABLE READ snapshot could miss a first journal that
  -- committed before we acquired the book lock (SHARE did not change its row).
  -- These rare configuration writes require fresh statement snapshots.
  IF current_setting('transaction_isolation') NOT IN ('read committed', 'read uncommitted') THEN
    RAISE EXCEPTION 'Primary book identity changes require READ COMMITTED isolation; retry the configuration in a new READ COMMITTED transaction'
      USING ERRCODE = '25000';
  END IF;
  -- SQL callers may already hold the target book row when this trigger runs.
  -- Never wait in the inverse target -> authority order: contention fails
  -- closed and the caller can retry the whole transaction. The setup service
  -- acquires authority first, so its ordinary wait/recheck path is unchanged.
  PERFORM id FROM public.accounting_books
    WHERE org_id IN (source_org, target_org) AND is_primary
    ORDER BY id FOR UPDATE NOWAIT;
  IF EXISTS (SELECT 1 FROM public.journal_entries WHERE org_id IN (source_org, target_org))
     OR EXISTS (SELECT 1 FROM public.reconciliations WHERE org_id IN (source_org, target_org)) THEN
    RAISE EXCEPTION 'Cannot reassign the primary book while journal entries or bank reconciliation sessions/history exist; a controlled book conversion is required'
      USING ERRCODE = '23514';
  END IF;
  IF tg_op = 'DELETE' THEN RETURN old; END IF;
  RETURN new;
END;
$$;


--
-- Name: FUNCTION primary_book_history_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.primary_book_history_guard() IS 'openbooks:primary_book_history_guard:v1 - primary book identity is frozen by accounting or reconciliation history; migration and controlled sandbox-delete exemptions';


--
-- Name: project_financial_adjustment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_financial_adjustment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF tg_op = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(old.org_id)
  THEN
    RETURN old;
  END IF;
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION
      'project financial adjustments are append-only; post a reversing adjustment';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM projects p
     WHERE p.id = new.project_id
       AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial adjustment must belong to the project organization';
  END IF;
  IF new.reverses_adjustment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_financial_adjustments original
     WHERE original.id = new.reverses_adjustment_id
       AND original.org_id = new.org_id
       AND original.project_id = new.project_id
       AND original.measure = new.measure
       AND original.amount = -new.amount
  ) THEN
    RAISE EXCEPTION
      'a reversing project financial adjustment must exactly offset the same project and measure';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: project_financial_profile_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_financial_profile_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  publish_mode boolean :=
    coalesce(current_setting('openbooks.publish_project_profile', true), 'off') = 'on';
  correction_mode boolean :=
    coalesce(current_setting('openbooks.correct_project_profile', true), 'off') = 'on';
  correction_reason text :=
    coalesce(current_setting('openbooks.project_profile_correction_reason', true), '');
BEGIN
  IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
    RETURN old;
  END IF;
  IF tg_op <> 'DELETE' AND NOT EXISTS (
    SELECT 1
      FROM project_types pt
     WHERE pt.id = new.project_type_id
       AND pt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial profile version must belong to the project type organization';
  END IF;

  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'published project financial profile versions are immutable';
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF correction_mode THEN
      IF length(btrim(correction_reason)) < 8
         OR (to_jsonb(new) - 'financial_profile' - 'updated_at' - 'updated_by')
            IS DISTINCT FROM
            (to_jsonb(old) - 'financial_profile' - 'updated_at' - 'updated_by')
      THEN
        RAISE EXCEPTION
          'controlled project financial profile correction may change only policy JSON and requires a reason';
      END IF;
    ELSIF NOT publish_mode
       OR (to_jsonb(new) - 'effective_to' - 'updated_at' - 'updated_by')
          IS DISTINCT FROM
          (to_jsonb(old) - 'effective_to' - 'updated_at' - 'updated_by')
    THEN
      RAISE EXCEPTION 'published project financial profile versions are immutable';
    END IF;
  END IF;

  -- Effective-range exclusivity is owned by the
  -- project_financial_profile_versions_no_overlap exclusion constraint
  -- (0051). Publish-mode window closing and correction-mode immutability
  -- above are unchanged.
  RETURN new;
END;
$$;


--
-- Name: FUNCTION project_financial_profile_version_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.project_financial_profile_version_guard() IS 'openbooks:project_financial_profile_version_guard:v3 - authorized sandbox teardown; publish/correct-mode immutability for project financial profile versions; effective-range exclusivity moved to the project_financial_profile_versions_no_overlap exclusion constraint';


