--
-- Name: property_financial_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.property_financial_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF openbooks_sandbox_wipe_allowed(CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END) THEN
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'property financial evidence is append-only';
END $$;


--
-- Name: protect_application_idempotency_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_application_idempotency_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.expires_at <= now()
       OR public.app_bypass_rls_active() THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'unexpired application idempotency evidence cannot be deleted';
  END IF;

  IF OLD.completed_at IS NULL
     AND NEW.completed_at IS NOT NULL
     AND NEW.response IS NOT NULL
     AND NEW.org_id = OLD.org_id
     AND NEW.actor_id = OLD.actor_id
     AND NEW.source = OLD.source
     AND NEW.operation = OLD.operation
     AND NEW.idempotency_key = OLD.idempotency_key
     AND NEW.request_hash = OLD.request_hash
     AND NEW.created_at = OLD.created_at
     AND NEW.expires_at = OLD.expires_at THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'application idempotency evidence is immutable after creation';
END;
$$;


--
-- Name: protect_country_tax_pack_installation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_country_tax_pack_installation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'country tax pack installation evidence is immutable';
  END IF;
  IF OLD.status = 'active'
     AND NEW.status = 'superseded'
     AND NEW.org_id = OLD.org_id
     AND NEW.pack_code = OLD.pack_code
     AND NEW.country = OLD.country
     AND NEW.version = OLD.version
     AND NEW.content_hash = OLD.content_hash
     AND NEW.manifest = OLD.manifest
     AND NEW.installed_at = OLD.installed_at
     AND NEW.installed_by IS NOT DISTINCT FROM OLD.installed_by
     AND NEW.superseded_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'country tax pack installation may only transition from active to superseded';
END;
$$;


--
-- Name: protect_org_base_price_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_org_base_price_level() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF OLD.is_base THEN
      RAISE EXCEPTION 'The organization base price level must remain active; edit its name or add another price level instead';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.customer_price_level_assignments assignment
       WHERE assignment.org_id = OLD.org_id AND assignment.price_level_id = OLD.id AND assignment.is_active
      UNION ALL
      SELECT 1 FROM public.item_price_schedules schedule
       WHERE schedule.org_id = OLD.org_id AND schedule.price_level_id = OLD.id AND schedule.is_active
    ) THEN
      RAISE EXCEPTION 'Price level % is still in use; deactivate its customer assignments and item pricing schedules first', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_base AND (NOT NEW.is_base OR NOT NEW.is_active OR NEW.org_id <> OLD.org_id) THEN
    RAISE EXCEPTION 'The organization base price level must remain active; edit its name or add another price level instead';
  END IF;
  IF OLD.is_active AND NOT NEW.is_active AND EXISTS (
    SELECT 1 FROM public.customer_price_level_assignments assignment
     WHERE assignment.org_id = OLD.org_id AND assignment.price_level_id = OLD.id AND assignment.is_active
    UNION ALL
    SELECT 1 FROM public.item_price_schedules schedule
     WHERE schedule.org_id = OLD.org_id AND schedule.price_level_id = OLD.id AND schedule.is_active
  ) THEN
    RAISE EXCEPTION 'Price level % is still in use; deactivate its customer assignments and item pricing schedules first', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_pricing_customer_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_pricing_customer_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF OLD.is_active AND EXISTS (
      SELECT 1 FROM public.customer_price_level_assignments assignment
       WHERE assignment.org_id = OLD.org_id AND assignment.customer_id = OLD.party_id AND assignment.is_active
      UNION ALL
      SELECT 1 FROM public.item_price_schedules schedule
       WHERE schedule.org_id = OLD.org_id AND schedule.customer_id = OLD.party_id AND schedule.is_active
    ) THEN
      RAISE EXCEPTION 'Customer % has active pricing; deactivate its price-level assignments and item pricing schedules first', OLD.party_id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_active AND NOT NEW.is_active AND EXISTS (
    SELECT 1 FROM public.customer_price_level_assignments assignment
     WHERE assignment.org_id = OLD.org_id AND assignment.customer_id = OLD.party_id AND assignment.is_active
    UNION ALL
    SELECT 1 FROM public.item_price_schedules schedule
     WHERE schedule.org_id = OLD.org_id AND schedule.customer_id = OLD.party_id AND schedule.is_active
  ) THEN
    RAISE EXCEPTION 'Customer % has active pricing; deactivate its price-level assignments and item pricing schedules first', OLD.party_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_report_run_authorization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_report_run_authorization() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.authorization_snapshot IS NOT DISTINCT FROM OLD.authorization_snapshot THEN
    RETURN NEW;
  END IF;
  -- A missing snapshot behaves like an empty object for the one allowed
  -- transition below, but it may gain nothing beyond that single key.
  IF OLD.authorization_snapshot IS NULL THEN
    IF jsonb_typeof(NEW.authorization_snapshot) = 'object'
       AND NEW.authorization_snapshot
           = jsonb_build_object('requiredPermissions', NEW.authorization_snapshot->'requiredPermissions')
       AND jsonb_typeof(NEW.authorization_snapshot->'requiredPermissions') = 'array' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  IF jsonb_typeof(OLD.authorization_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- An already-recorded requiredPermissions is evidence: it never moves.
  IF OLD.authorization_snapshot ? 'requiredPermissions' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- Otherwise NEW must be OLD plus exactly the recorded key (jsonb
  -- equality: every other key identical, the new key an array).
  IF jsonb_typeof(NEW.authorization_snapshot->'requiredPermissions') = 'array'
     AND (OLD.authorization_snapshot
          || jsonb_build_object('requiredPermissions', NEW.authorization_snapshot->'requiredPermissions')
         ) = NEW.authorization_snapshot THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
END;
$$;


--
-- Name: protect_tax_provision_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tax_provision_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION
        'finalized income-tax provision runs are append-only (run %, status %)',
        OLD.id, OLD.status;
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('discarded', 'superseded') THEN
    RAISE EXCEPTION
      'finalized income-tax provision runs are immutable (run %, status %)',
      OLD.id, OLD.status;
  END IF;

  IF OLD.status = 'posted' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'posted income-tax provision runs may only transition to superseded (run %)',
      OLD.id;
  END IF;

  IF OLD.status = 'posted' AND (
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.fiscal_year IS DISTINCT FROM OLD.fiscal_year
    OR NEW.period_from IS DISTINCT FROM OLD.period_from
    OR NEW.period_to IS DISTINCT FROM OLD.period_to
    OR NEW.version IS DISTINCT FROM OLD.version
    OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id
    OR NEW.posted_at IS DISTINCT FROM OLD.posted_at
    OR NEW.posted_by IS DISTINCT FROM OLD.posted_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
  ) THEN
    RAISE EXCEPTION
      'posted income-tax provision evidence is immutable (run %)',
      OLD.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_temporary_difference_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_temporary_difference_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_org_id uuid;
  target_run_id uuid;
  target_status text;
BEGIN
  target_org_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.org_id ELSE NEW.org_id END;
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(target_org_id) THEN
    RETURN OLD;
  END IF;

  target_run_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.run_id ELSE NEW.run_id END;
  SELECT status
    INTO target_status
    FROM tax_provision_runs
   WHERE id = target_run_id
     AND org_id = target_org_id;

  IF target_status IS NULL THEN
    RAISE EXCEPTION 'temporary difference must reference a tenant-owned provision run';
  END IF;
  IF target_status <> 'draft' THEN
    RAISE EXCEPTION
      'temporary differences are immutable after provision finalization (run %, status %)',
      target_run_id, target_status;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: provision_change_binding_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_change_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.domain='provision' AND NOT EXISTS (
    SELECT 1 FROM public.provision_obligations p WHERE p.org_id=NEW.org_id
      AND p.id=NEW.subject_id AND p.subsidiary_id=NEW.subsidiary_id
      AND NEW.operation='provision_assessment'
      AND NEW.payload->'requiredSubsidiaryIds'=jsonb_build_array(p.subsidiary_id::text)
  ) THEN
    RAISE EXCEPTION 'provision assessment must bind to its organization and legal entity';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: provision_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'provision accounting identity is immutable; release the old obligation through an approved assessment and create the corrected obligation';
END
$$;


--
-- Name: provision_project_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_project_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.org_id=NEW.org_id
    AND p.id=NEW.project_id AND p.subsidiary_id=NEW.subsidiary_id) THEN
    RAISE EXCEPTION 'construction loss provision must bind to the project legal entity';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: putaway_rules_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.putaway_rules_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  target_code text;
  warehouse_code text;
BEGIN
  IF public.stock_location_warehouse(NEW.org_id, NEW.target_location_id) IS DISTINCT FROM NEW.warehouse_id THEN
    SELECT code INTO target_code FROM public.stock_locations WHERE id = NEW.target_location_id AND org_id = NEW.org_id;
    SELECT code INTO warehouse_code FROM public.stock_locations WHERE id = NEW.warehouse_id AND org_id = NEW.org_id;
    RAISE EXCEPTION 'putaway target % is not inside warehouse %; choose a bin or zone under that warehouse',
      coalesce(target_code, NEW.target_location_id::text), coalesce(warehouse_code, NEW.warehouse_id::text)
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: rate_adjustment_target_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_adjustment_target_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  SELECT version.status, adjustment.org_id
    INTO v_status, v_org_id
    FROM labor_rate_adjustments adjustment
    JOIN item_rate_versions version
      ON version.id = adjustment.version_id
     AND version.org_id = adjustment.org_id
   WHERE adjustment.id = coalesce(NEW.adjustment_id, OLD.adjustment_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'adjustment target must reference a tenant-owned rate version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: rate_book_currency_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_book_currency_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    IF EXISTS (
      SELECT 1 FROM item_rate_versions version
       WHERE version.rate_book_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'a rate book with version history cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'rate book organization is immutable';
  END IF;
  IF NEW.currency IS DISTINCT FROM OLD.currency
     AND EXISTS (
       SELECT 1 FROM item_rate_versions version
        WHERE version.rate_book_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'rate book currency cannot change after version history exists';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: rate_version_book_lock_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_book_lock_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM 1
    FROM public.item_rate_books book
   WHERE book.id = NEW.rate_book_id
     AND book.org_id = NEW.org_id
     FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'rate version must reference a tenant-owned rate book'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION rate_version_book_lock_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rate_version_book_lock_guard() IS 'openbooks:rate_version_book_lock_guard:v1 - holds a FOR SHARE lock on the tenant-owned rate book from before a version insert until commit, so a concurrent currency change cannot pass the history check while first-version creation is in flight';


--
-- Name: rate_version_child_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_child_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  SELECT status, org_id
    INTO v_status, v_org_id
    FROM item_rate_versions
   WHERE id = coalesce(NEW.version_id, OLD.version_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'rate-version child must reference a tenant-owned version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'children of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: rate_version_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'activated and retired rate versions cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;

  IF OLD.status = 'active' AND NEW.status = 'active'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom
     AND NEW.effective_to IS NOT NULL
     AND NEW.effective_to >= OLD.effective_from
     AND (OLD.effective_to IS NULL OR NEW.effective_to <= OLD.effective_to) THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'active' AND NEW.status = 'retired'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.effective_to IS NOT DISTINCT FROM OLD.effective_to
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'activated and retired rate versions are immutable';
END
$$;


--
-- Name: recognition_revision_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recognition_revision_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
 END IF;
 IF OLD.superseded_by_change_id IS NOT NULL THEN RAISE EXCEPTION 'superseded revenue plans are immutable evidence'; END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.journal_entry_id IS NOT NULL THEN RAISE EXCEPTION 'posted revenue history cannot be deleted'; END IF;
  RETURN OLD;
 END IF;
 IF OLD.journal_entry_id IS NOT NULL AND
    (to_jsonb(NEW)-ARRAY['reversal_journal_entry_id','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['reversal_journal_entry_id','updated_at','updated_by']) THEN
   RAISE EXCEPTION 'posted revenue measurements are immutable; append an adjustment';
 END IF;
 IF OLD.reversal_journal_entry_id IS NOT NULL AND NEW.reversal_journal_entry_id IS DISTINCT FROM OLD.reversal_journal_entry_id THEN
   RAISE EXCEPTION 'revenue reversal lineage is immutable';
 END IF;
 IF NEW.superseded_by_change_id IS DISTINCT FROM OLD.superseded_by_change_id AND
   (OLD.journal_entry_id IS NOT NULL OR NOT EXISTS (
     SELECT 1 FROM financial_changes f JOIN recognition_schedules s ON s.id=OLD.schedule_id AND s.org_id=OLD.org_id
     JOIN performance_obligations o ON o.id=s.obligation_id AND o.org_id=s.org_id
     WHERE f.id=NEW.superseded_by_change_id AND f.org_id=OLD.org_id AND f.domain='revenue' AND f.subject_id=o.contract_id AND f.status='approved')) THEN
   RAISE EXCEPTION 'only unposted plans may be superseded by an approved modification of this contract';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: recompute_document_open_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_document_open_balance(p_doc uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Different open lines can receive applications concurrently. Acquire the
  -- shared document lock BEFORE starting the calculation statement so its
  -- READ COMMITTED snapshot includes the previous lock holder's settlement.
  PERFORM d.id FROM public.documents d WHERE d.id = p_doc FOR UPDATE;
  UPDATE public.documents d
     SET open_balance = public.document_open_balance_amount(
       d.org_id, d.posted_entry_id, d.currency, d.status::text)
   WHERE d.id = p_doc;
END;
$$;


--
-- Name: recompute_document_open_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_document_open_balances(p_org uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_ids uuid[];
  v_healed integer;
BEGIN
  -- Fence exactly the existing projections selected for this repair. New
  -- documents committed after this statement remain owned by their triggers;
  -- including an unlocked newcomer in the next statement would reintroduce
  -- the stale-snapshot race. Lock order is deterministic across bulk repairs.
  SELECT array_agg(locked.id) INTO v_ids
    FROM (
      SELECT d.id FROM public.documents d
       WHERE d.org_id = p_org
         AND (d.posted_entry_id IS NOT NULL OR d.open_balance IS NOT NULL)
       ORDER BY d.id FOR UPDATE
    ) locked;
  WITH balances AS MATERIALIZED (
    SELECT d.id, public.document_open_balance_amount(
             d.org_id, d.posted_entry_id, d.currency, d.status::text) AS balance
      FROM public.documents d
     WHERE d.org_id = p_org AND d.id = ANY(v_ids)
  )
  UPDATE public.documents d SET open_balance = b.balance
    FROM balances b
   WHERE d.id = b.id AND d.org_id = p_org
     AND d.open_balance IS DISTINCT FROM b.balance;
  GET DIAGNOSTICS v_healed = ROW_COUNT;
  RETURN v_healed;
END;
$$;


--
-- Name: recurring_occurrence_document_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recurring_occurrence_document_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'recurring occurrence lineage is immutable';
END $$;


--
-- Name: refresh_document_totals_from_lines(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_document_totals_from_lines(p_document_id uuid, p_org_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_kind text;
    v_line_count integer;
    v_amount_sum numeric;
    v_tax_sum numeric;
    v_debit_sum numeric;
    v_want_subtotal numeric;
    v_want_total numeric;
BEGIN
    SELECT kind INTO v_kind
      FROM public.documents
     WHERE id = p_document_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT count(*)::int,
           coalesce(sum(l.amount), 0),
           coalesce(sum(l.tax_amount), 0),
           coalesce(sum(l.amount) FILTER (WHERE l.amount > 0), 0)
      INTO v_line_count, v_amount_sum, v_tax_sum, v_debit_sum
      FROM public.document_lines l
     WHERE l.document_id = p_document_id AND l.org_id = p_org_id;
    IF v_kind IN ('journal', 'pay_run') THEN
        v_want_total := v_debit_sum;
        v_want_subtotal := v_debit_sum - v_tax_sum;
    ELSE
        v_want_subtotal := v_amount_sum;
        v_want_total := v_amount_sum + v_tax_sum;
    END IF;
    UPDATE public.documents d
       SET subtotal = v_want_subtotal,
           tax_total = v_tax_sum,
           total = v_want_total,
           updated_at = greatest(clock_timestamp(), d.updated_at + interval '1 microsecond')
     WHERE d.id = p_document_id
       AND d.org_id = p_org_id
       AND (d.subtotal, d.tax_total, d.total) IS DISTINCT FROM
           (v_want_subtotal, v_tax_sum, v_want_total);
END;
$$;


--
-- Name: FUNCTION refresh_document_totals_from_lines(p_document_id uuid, p_org_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_document_totals_from_lines(p_document_id uuid, p_org_id uuid) IS 'openbooks:document_total_line_refresh:v1 - refreshes denormalized document totals after a financial line mutation';


--
-- Name: reporting_relationships_closure_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reporting_relationships_closure_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Governed amend path (fixture teardown, historical replay, native merge):
  -- the existing house mechanism, not a new bypass. Production paths never
  -- set openbooks.amend; scratch teardown does, or cascade deletes of a
  -- dropped scratch org could never complete.
  IF TG_OP = 'DELETE'
     AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reporting_relationships: rows are never deleted; close with a superseding version'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.superseded_by IS NOT NULL THEN
    RAISE EXCEPTION 'reporting_relationships: closed rows are immutable'
      USING ERRCODE = '23514';
  END IF;
  -- Pure audit touch on a live row (updated_at/updated_by only): housekeeping
  -- attribution, never content (same shape as worker_employment_versions).
  IF NEW.superseded_by IS NULL AND NEW.recorded_until IS NULL
     AND NEW.closed_by_change_id IS NULL
     AND to_jsonb(NEW) - ARRAY['updated_at','updated_by']
       = to_jsonb(OLD) - ARRAY['updated_at','updated_by'] THEN
    RETURN NEW;
  END IF;
  IF NEW.superseded_by IS NULL OR NEW.recorded_until IS NULL THEN
    RAISE EXCEPTION 'reporting_relationships: live rows are append-only; the only allowed UPDATE is the closing transition (recorded_until + superseded_by) or a pure audit touch'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.employment_id IS DISTINCT FROM OLD.employment_id
     OR NEW.manager_employment_id IS DISTINCT FROM OLD.manager_employment_id
     OR NEW.kind IS DISTINCT FROM OLD.kind
     OR NEW.relationship_id IS DISTINCT FROM OLD.relationship_id
     OR NEW.version_no IS DISTINCT FROM OLD.version_no
     OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
     OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
     OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'reporting_relationships: closure sets recorded_until + superseded_by + closed_by_change_id (plus audit touch) only'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION reporting_relationships_closure_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reporting_relationships_closure_guard() IS 'openbooks:reporting_relationships_closure_guard:v1 - closed rows immutable; live rows accept only the closing transition or a pure audit touch; successor + evidence proven deferred by hrm_closure_evidence_guard';


--
-- Name: revenue_approved_terms_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_approved_terms_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE subject uuid; changed boolean; amendment uuid;
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF NEW.org_id<>OLD.org_id OR NEW.id<>OLD.id THEN RAISE EXCEPTION 'revenue identity and organization are immutable'; END IF;
 IF TG_TABLE_NAME='revenue_contracts' THEN
  IF OLD.subsidiary_id IS NOT NULL AND NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id THEN RAISE EXCEPTION 'revenue legal entity cannot be changed'; END IF;
  subject:=OLD.id; amendment:=NEW.last_change_id;
  changed:=(NEW.total_transaction_price,NEW.currency,NEW.customer_id,NEW.starts_on,NEW.ends_on) IS DISTINCT FROM
           (OLD.total_transaction_price,OLD.currency,OLD.customer_id,OLD.starts_on,OLD.ends_on);
 ELSE
  IF NEW.contract_id<>OLD.contract_id THEN RAISE EXCEPTION 'a performance obligation cannot move contracts'; END IF;
  subject:=OLD.contract_id; amendment:=NEW.last_change_id;
  changed:=(NEW.allocated_price,NEW.standalone_selling_price,NEW.recognition_rule_id,NEW.recognition_starts_on,NEW.recognition_ends_on,NEW.deferred_account_id,NEW.recognized_account_id) IS DISTINCT FROM
           (OLD.allocated_price,OLD.standalone_selling_price,OLD.recognition_rule_id,OLD.recognition_starts_on,OLD.recognition_ends_on,OLD.deferred_account_id,OLD.recognized_account_id);
 END IF;
 IF (OLD.last_change_id IS NOT NULL AND changed) OR NEW.last_change_id IS DISTINCT FROM OLD.last_change_id THEN
  IF amendment IS NULL OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=amendment AND f.org_id=OLD.org_id AND f.domain='revenue' AND f.subject_id=subject AND f.status='approved') THEN
   RAISE EXCEPTION 'approved revenue terms require a new independently approved contract modification';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: revenue_schedule_basis_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_schedule_basis_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE subject uuid; parent uuid;
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF NEW.change_basis IS NOT NULL AND (TG_OP='INSERT' OR NEW.change_basis IS DISTINCT FROM OLD.change_basis) THEN
  SELECT c.id,c.parent_contract_id INTO subject,parent FROM performance_obligations o JOIN revenue_contracts c ON c.id=o.contract_id AND c.org_id=o.org_id WHERE o.id=NEW.obligation_id AND o.org_id=NEW.org_id;
  IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=(NEW.change_basis->>'changeId')::uuid AND f.org_id=NEW.org_id AND f.domain='revenue' AND f.subject_id IN(subject,parent) AND f.status='approved') THEN
   RAISE EXCEPTION 'amended recognition basis requires the approved contract modification';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND OLD.change_basis IS NOT NULL AND NEW.change_basis IS NULL THEN RAISE EXCEPTION 'an approved recognition basis cannot be erased'; END IF;
 IF NEW.change_basis IS NOT NULL AND NEW.total_amount IS DISTINCT FROM (NEW.change_basis->>'totalAmount')::numeric THEN RAISE EXCEPTION 'recognition total must match its approved basis'; END IF;
 RETURN NEW;
END $$;


--
-- Name: rma_document_kind_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rma_document_kind_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  record_org uuid;
  record_kind text;
BEGIN
  SELECT org_id, kind INTO record_org, record_kind
    FROM public.documents WHERE id = NEW.document_id;
  IF record_org IS DISTINCT FROM NEW.org_id OR record_kind IS DISTINCT FROM 'rma' THEN
    RAISE EXCEPTION 'RMA details require a return authorization document in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT org_id, kind INTO record_org, record_kind
    FROM public.documents WHERE id = NEW.source_document_id;
  IF record_org IS DISTINCT FROM NEW.org_id OR record_kind NOT IN ('customer_invoice', 'sales_fulfillment') THEN
    RAISE EXCEPTION 'RMA source must be a customer invoice or sales fulfillment in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.customer_credit_id IS NOT NULL THEN
    SELECT org_id, kind INTO record_org, record_kind
      FROM public.documents WHERE id = NEW.customer_credit_id;
    IF record_org IS DISTINCT FROM NEW.org_id OR record_kind IS DISTINCT FROM 'customer_credit' THEN
      RAISE EXCEPTION 'RMA customer credit must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: rma_line_kind_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rma_line_kind_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  rma_org uuid;
  document_kind text;
  line_document uuid;
  source_org uuid;
  location_org uuid;
  credit_org uuid;
  credit_kind text;
  scrap_org uuid;
BEGIN
  SELECT org_id INTO rma_org FROM public.rma_documents
   WHERE document_id = NEW.document_id AND org_id = NEW.org_id;
  SELECT d.kind, l.document_id INTO document_kind, line_document
    FROM public.document_lines l JOIN public.documents d ON d.id = l.document_id AND d.org_id = l.org_id
   WHERE l.id = NEW.line_id AND l.org_id = NEW.org_id;
  IF rma_org IS NULL OR document_kind IS DISTINCT FROM 'rma' OR line_document IS DISTINCT FROM NEW.document_id THEN
    RAISE EXCEPTION 'RMA line must belong to an RMA document in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT org_id INTO source_org FROM public.inventory_movements WHERE id = NEW.source_issue_movement_id;
  IF source_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'RMA source movement must belong to the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.disposition_location_id IS NOT NULL THEN
    SELECT org_id INTO location_org FROM public.stock_locations WHERE id = NEW.disposition_location_id;
    IF location_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'RMA disposition location must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.vendor_credit_id IS NOT NULL THEN
    SELECT org_id, kind INTO credit_org, credit_kind FROM public.documents WHERE id = NEW.vendor_credit_id;
    IF credit_org IS DISTINCT FROM NEW.org_id OR credit_kind IS DISTINCT FROM 'vendor_credit' THEN
      RAISE EXCEPTION 'RMA vendor credit must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.scrap_movement_id IS NOT NULL THEN
    SELECT org_id INTO scrap_org FROM public.inventory_movements WHERE id = NEW.scrap_movement_id;
    IF scrap_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'RMA scrap movement must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: row_extra_dims_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.row_extra_dims_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_subsidiary uuid;
begin
  v_subsidiary := new.subsidiary_id;
  if tg_table_name = 'document_lines' and v_subsidiary is null then
    select subsidiary_id into v_subsidiary from documents where id = new.document_id;
  end if;
  if v_subsidiary is null then
    select id into v_subsidiary from subsidiaries where org_id = new.org_id and parent_id is null;
  end if;
  perform validate_extra_dims(new.org_id, new.extra_dims, v_subsidiary);
  return new;
end $$;


--
-- Name: saas_metrics_fx_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_metrics_fx_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'saas FX evidence is append-only and cannot be deleted; record a superseding observation instead'
      USING ERRCODE = 'check_violation';
  END IF;
  RAISE EXCEPTION 'saas FX evidence is immutable and cannot be updated; record a new observation instead'
    USING ERRCODE = 'check_violation';
END
$$;


--
-- Name: saas_metrics_normalization_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_metrics_normalization_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  actor_org uuid;
  live boolean;
  prior_digest text;
  new_digest text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'saas normalization requests are durable audit and cannot be deleted; cancel the request instead'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Actor identities are validated against the subject: the requester and
  -- the approver must belong to the requesting organization.
  IF NEW.requested_by IS NOT NULL THEN
    SELECT org_id INTO actor_org FROM public.users WHERE id = NEW.requested_by;
    IF actor_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'saas normalization requester must be a user of the requesting organization; choose a requester in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.approved_by IS NOT NULL THEN
    SELECT org_id INTO actor_org FROM public.users WHERE id = NEW.approved_by;
    IF actor_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'saas normalization approver must be a user of the requesting organization; choose an approver in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.approved_by IS NOT DISTINCT FROM NEW.requested_by THEN
      RAISE EXCEPTION 'saas normalization approver must be distinct from the requester; choose a separate approver in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'pending' THEN
      RAISE EXCEPTION 'new saas normalization requests start as pending; claim the pending request to begin work'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION 'saas normalization approval is recorded by updating the pending request, not at insert; insert without approver, then record approval'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_heartbeat_at IS NOT NULL THEN
      RAISE EXCEPTION 'new saas normalization requests hold no lease; claim the pending request to take a lease token'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> 0 THEN
      RAISE EXCEPTION 'new saas normalization requests start at attempt zero; claims pending attempts'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'new saas normalization requests carry no outcome; finalize a running claim to record one'
        USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_requested',
      jsonb_build_object('event', 'saas_normalization_requested', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', 0,
        'statusBefore', NULL, 'statusAfter', NEW.status,
        'priorLeaseDigest', NULL, 'newLeaseDigest', NULL,
        'actor', NEW.requested_by, 'reason', NEW.reason),
      NEW.requested_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Request identity is immutable; a new month or idempotency key is a new request.
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.month IS DISTINCT FROM OLD.month
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by THEN
    RAISE EXCEPTION 'saas normalization request identity (organization, month, idempotency key, request hash, requester) is immutable; file a new request instead'
      USING ERRCODE = 'check_violation';
  END IF;
  -- The approver is immutable once recorded; the approval timestamp follows it.
  IF OLD.approved_by IS NOT NULL AND NEW.approved_by IS DISTINCT FROM OLD.approved_by THEN
    RAISE EXCEPTION 'saas normalization approver is immutable once recorded; the recorded approval stands'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_at IS NOT NULL AND NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
    RAISE EXCEPTION 'saas normalization approval time is immutable once recorded; the recorded approval stands'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.approved_by IS NULL) <> (NEW.approved_at IS NULL) THEN
    RAISE EXCEPTION 'saas normalization approval needs both approver and approval time; record them together on the pending request'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Terminal rows are immutable; further work is a new request.
  IF OLD.status IN ('succeeded', 'cancelled') THEN
    RAISE EXCEPTION 'saas normalization requests in terminal state % are immutable; file a new request for further work', OLD.status
      USING ERRCODE = 'check_violation';
  END IF;

  -- Liveness: the presented token must equal the stored live token and the
  -- stored lease must not have expired. Every later mutation and
  -- finalization funnels through this flag.
  live := OLD.lease_token IS NOT NULL
          AND NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token
          AND OLD.lease_expires_at IS NOT NULL
          AND OLD.lease_expires_at > now();
  prior_digest := CASE WHEN OLD.lease_token IS NULL THEN NULL
    ELSE 'sha256:' || encode(public.digest(convert_to(OLD.lease_token::text, 'UTF8'), 'sha256'), 'hex') END;
  new_digest := CASE WHEN NEW.lease_token IS NULL THEN NULL
    ELSE 'sha256:' || encode(public.digest(convert_to(NEW.lease_token::text, 'UTF8'), 'sha256'), 'hex') END;

  -- Pending rows change only by recording approval, claiming, or cancelling.
  IF OLD.status = 'pending' AND NEW.status = 'pending' THEN
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token
       OR NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at
       OR NEW.last_heartbeat_at IS DISTINCT FROM OLD.last_heartbeat_at
       OR NEW.attempt_count <> OLD.attempt_count
       OR NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL
       OR NEW.progress IS DISTINCT FROM OLD.progress THEN
      RAISE EXCEPTION 'pending saas normalization requests change only by recording approval, claiming to running, or cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    IF OLD.approved_by IS NULL AND NEW.approved_by IS NOT NULL THEN
      INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
      VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_approved',
        jsonb_build_object('event', 'saas_normalization_approved', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', NEW.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'actor', NEW.approved_by, 'reason', NEW.reason),
        NEW.approved_by, NEW.idempotency_key::text);
    END IF;
    RETURN NEW;
  END IF;

  -- First claim: pending to running opens attempt one with a fresh live lease.
  -- Execution requires a recorded approval and a presented transition actor.
  IF OLD.status = 'pending' AND NEW.status = 'running' THEN
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'claiming a saas normalization request requires a recorded approval; record approver and approval time on the pending request, then claim'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM NEW.approved_by THEN
      RAISE EXCEPTION 'claiming a saas normalization request requires the approver as the acting user; record the approver as updated_by when claiming'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'claiming a saas normalization request needs a fresh lease token with a future expiry; generate a token and claim again'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'claiming a saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a claimed saas normalization request carries no outcome yet; finalize after work completes'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_claimed',
      jsonb_build_object('event', 'saas_normalization_claimed', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'pending' AND NEW.status = 'cancelled' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.requested_by THEN
      RAISE EXCEPTION 'cancelling a pending saas normalization request requires the requester as the acting user; record the requester as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION 'cancelling an unclaimed saas normalization request takes no lease; cancel without lease fields'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Running to running: either a live heartbeat under the live token, or a
  -- stale reacquisition after expiry. Heartbeats manufacture no audit event.
  IF OLD.status = 'running' AND NEW.status = 'running' THEN
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token THEN
      IF OLD.lease_expires_at IS NULL OR OLD.lease_expires_at > now() THEN
        RAISE EXCEPTION 'saas normalization lease is still live; heartbeat with the live token, or wait for expiry and reacquire'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request requires the approver as the acting user; record the approver as updated_by when reacquiring'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request needs a fresh lease token with a future expiry; generate a token and reacquire'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
        RAISE EXCEPTION 'a reacquired saas normalization request carries no outcome yet; finalize after work completes'
          USING ERRCODE = 'check_violation';
      END IF;
      NEW.last_heartbeat_at := now();
      NEW.updated_at := now();
      INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
      VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_abandoned',
        jsonb_build_object('event', 'saas_normalization_abandoned', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', OLD.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
          'actor', NEW.updated_by, 'reason', NEW.reason),
        NEW.updated_by, NEW.idempotency_key::text),
        (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_reacquired',
        jsonb_build_object('event', 'saas_normalization_reacquired', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', NEW.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
          'actor', NEW.updated_by, 'reason', NEW.reason),
        NEW.updated_by, NEW.idempotency_key::text);
      RETURN NEW;
    END IF;
    IF OLD.lease_expires_at IS NULL OR OLD.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'saas normalization lease has expired; reacquire with a fresh token before further heartbeats'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'saas normalization heartbeat requires the approver as the acting user; record the approver as updated_by when heartbeating'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count THEN
      RAISE EXCEPTION 'heartbeats open no new attempts; keep attempt_count at % or reacquire after expiry', OLD.attempt_count
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_expires_at < OLD.lease_expires_at THEN
      RAISE EXCEPTION 'heartbeats may extend the saas normalization lease expiry, never shorten it'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'running saas normalization requests carry progress only; finalize to record an outcome'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- Finalization under the live lease token: exactly one terminal event.
  IF OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed') THEN
    IF NOT live THEN
      RAISE EXCEPTION 'finalizing a saas normalization request requires the live lease token; heartbeat or reacquire first, then finalize'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'finalizing a saas normalization request requires the approver as the acting user; record the approver as updated_by when finalizing'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count THEN
      RAISE EXCEPTION 'finalization closes the current attempt; keep attempt_count at %', OLD.attempt_count
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'succeeded' THEN
      IF NEW.result IS NULL THEN
        RAISE EXCEPTION 'a succeeded saas normalization must store its result; include the result document'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
        RAISE EXCEPTION 'a succeeded saas normalization carries a result, not a failure; clear failure and remedy'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.failure IS NULL OR btrim(NEW.failure) = '' THEN
        RAISE EXCEPTION 'a failed saas normalization must name the failure; describe what went wrong'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.remedy IS NULL OR btrim(NEW.remedy) = '' THEN
        RAISE EXCEPTION 'a failed saas normalization must name the remedy; record how the operator recovers'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.result IS NOT NULL THEN
        RAISE EXCEPTION 'a failed saas normalization carries failure and remedy, not a result; clear the result'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    NEW.lease_token := NULL;
    NEW.lease_expires_at := NULL;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id,
      CASE WHEN NEW.status = 'succeeded' THEN 'saas_normalization_succeeded' ELSE 'saas_normalization_failed' END,
      jsonb_build_object('event', CASE WHEN NEW.status = 'succeeded' THEN 'saas_normalization_succeeded' ELSE 'saas_normalization_failed' END,
        'requestId', NEW.id, 'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'running' AND NEW.status = 'cancelled' THEN
    IF NOT live THEN
      RAISE EXCEPTION 'cancelling a running saas normalization request requires the live lease token; heartbeat or reacquire first'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'cancelling a running saas normalization request requires the approver as the acting user; record the approver as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.lease_token := NULL;
    NEW.lease_expires_at := NULL;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Retry from failure re-enters the lifecycle with a fresh live lease.
  IF OLD.status = 'failed' AND NEW.status = 'running' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request requires the approver as the acting user; record the approver as updated_by when retrying'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request needs a fresh lease token with a future expiry; generate a token and retry'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a retried saas normalization request starts clear; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_retried',
      jsonb_build_object('event', 'saas_normalization_retried', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'failed' AND NEW.status = 'cancelled' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'cancelling a failed saas normalization request requires the approver as the acting user; record the approver as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'saas normalization requests move pending to running to succeeded, failed or cancelled, and failed may retry to running; % to % is not a legal transition', OLD.status, NEW.status
    USING ERRCODE = 'check_violation';
END
$$;


--
-- Name: sales_address_location_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_address_location_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF ROW(OLD.line1,OLD.line2,OLD.city,OLD.region,OLD.postal_code,OLD.country) IS DISTINCT FROM ROW(NEW.line1,NEW.line2,NEW.city,NEW.region,NEW.postal_code,NEW.country) THEN
  NEW.longitude:=NULL; NEW.latitude:=NULL; NEW.location_verified_at:=NULL; NEW.location_verified_by:=NULL;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: sales_capture_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_capture_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE is_credit boolean:=false; is_reversal boolean:=false; old_won boolean:=false; new_won boolean:=false; prior public.crm_sales_evidence; metric_name text; source_name text; source_number_value text; value numeric; event_date date;
BEGIN
 IF TG_TABLE_NAME='documents' THEN
  IF NEW.kind NOT IN ('customer_invoice','customer_credit') THEN RETURN NEW; END IF;
  metric_name:='net_invoiced'; source_name:='document'; source_number_value:=NEW.document_number;
  is_credit:=NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted');
  is_reversal:=TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status='voided';
  value:=CASE WHEN NEW.kind='customer_credit' THEN -NEW.subtotal ELSE NEW.subtotal END;
  event_date:=COALESCE(NEW.posting_date,NEW.document_date);
  IF is_reversal THEN
   -- Finalized voids clear request fields. The posted reversal is the
   -- authoritative effective date for both accounting and sales evidence.
   SELECT reversal.posting_date INTO event_date
     FROM public.journal_entries reversal
    WHERE reversal.org_id=NEW.org_id
      AND reversal.id=NEW.reversal_entry_id
      AND reversal.reverses_entry_id=NEW.posted_entry_id
      AND reversal.status='posted';
  END IF;
 ELSE
  metric_name:='closed_won'; source_name:='opportunity'; source_number_value:=NEW.opportunity_number;
  SELECT is_won INTO new_won FROM public.crm_opportunity_statuses WHERE org_id=NEW.org_id AND id=NEW.status_id;
  IF TG_OP='UPDATE' THEN SELECT is_won INTO old_won FROM public.crm_opportunity_statuses WHERE org_id=OLD.org_id AND id=OLD.status_id; END IF;
  is_credit:=COALESCE(new_won,false) AND NOT COALESCE(old_won,false);
  is_reversal:=COALESCE(old_won,false) AND NOT COALESCE(new_won,false);
  IF TG_OP='UPDATE' AND old_won AND new_won AND
    (OLD.sales_rep_id IS DISTINCT FROM NEW.sales_rep_id OR OLD.sales_team_id IS DISTINCT FROM NEW.sales_team_id OR OLD.projected_amount IS DISTINCT FROM NEW.projected_amount OR OLD.currency IS DISTINCT FROM NEW.currency) THEN
   RAISE EXCEPTION 'Closed-won sales evidence is immutable; reopen the opportunity with a reason before adjusting it.' USING ERRCODE='23514';
  END IF;
  value:=NEW.projected_amount; event_date:=(NEW.closed_at AT TIME ZONE COALESCE((SELECT NULLIF(settings->>'timeZone','') FROM public.orgs WHERE id=NEW.org_id),'UTC'))::date;
  IF is_reversal AND NULLIF(trim(NEW.win_loss_reason),'') IS NULL THEN RAISE EXCEPTION 'Enter the reason for reopening this opportunity.' USING ERRCODE='23514'; END IF;
 END IF;
 IF is_credit THEN
  IF event_date IS NULL THEN RAISE EXCEPTION 'Sales evidence requires an effective date.' USING ERRCODE='23514'; END IF;
  INSERT INTO public.crm_sales_evidence(org_id,source_kind,source_id,source_number,source_revision,event_kind,metric,employee_id,sales_team_id,subsidiary_id,currency,amount,effective_date,created_by)
   VALUES(NEW.org_id,source_name,NEW.id,source_number_value,NEW.revision_seq,'credit',metric_name,NEW.sales_rep_id,NEW.sales_team_id,NEW.subsidiary_id,NEW.currency,value,event_date,NEW.updated_by);
 ELSIF is_reversal THEN
  SELECT e.* INTO prior FROM public.crm_sales_evidence e WHERE e.org_id=NEW.org_id AND e.source_kind=source_name AND e.source_id=NEW.id AND e.event_kind='credit' AND NOT EXISTS (SELECT 1 FROM public.crm_sales_evidence r WHERE r.org_id=e.org_id AND r.reverses_id=e.id) ORDER BY e.created_at DESC LIMIT 1;
  IF FOUND THEN
   IF source_name='opportunity' THEN event_date:=(NEW.updated_at AT TIME ZONE COALESCE((SELECT NULLIF(settings->>'timeZone','') FROM public.orgs WHERE id=NEW.org_id),'UTC'))::date; END IF;
   IF event_date IS NULL THEN RAISE EXCEPTION 'A sales reversal requires its controlled effective date.' USING ERRCODE='23514'; END IF;
   INSERT INTO public.crm_sales_evidence(org_id,source_kind,source_id,source_number,source_revision,event_kind,metric,employee_id,sales_team_id,subsidiary_id,currency,amount,effective_date,reverses_id,created_by)
    VALUES(prior.org_id,prior.source_kind,prior.source_id,prior.source_number,NEW.revision_seq,'reversal',prior.metric,prior.employee_id,prior.sales_team_id,prior.subsidiary_id,prior.currency,-prior.amount,event_date,prior.id,NEW.updated_by);
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: sales_customer_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_customer_assignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE account public.crm_account_profiles;
BEGIN
 IF TG_OP='UPDATE' AND OLD.sales_rep_id IS NOT DISTINCT FROM NEW.sales_rep_id THEN RETURN NEW; END IF;
 SELECT * INTO account FROM public.crm_account_profiles WHERE org_id=NEW.org_id AND party_id=NEW.party_id FOR UPDATE;
 IF NOT FOUND OR account.sales_rep_id IS NOT DISTINCT FROM NEW.sales_rep_id THEN RETURN NEW; END IF;
 UPDATE public.crm_account_profiles SET sales_rep_id=NEW.sales_rep_id,updated_at=clock_timestamp(),updated_by=NEW.updated_by WHERE org_id=NEW.org_id AND id=account.id;
 INSERT INTO public.crm_account_assignment_events(org_id,account_profile_id,from_employee_id,to_employee_id,from_owner_user_id,to_owner_user_id,from_territory_id,to_territory_id,source,reason,created_by,updated_by)
 VALUES(NEW.org_id,account.id,account.sales_rep_id,NEW.sales_rep_id,account.owner_user_id,account.owner_user_id,account.territory_id,account.territory_id,'manual','Customer sales representative changed',NEW.updated_by,NEW.updated_by);
 RETURN NEW;
END $$;


--
-- Name: sales_document_attribution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_document_attribution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.status IN ('posted','voided') AND (OLD.sales_rep_id IS DISTINCT FROM NEW.sales_rep_id OR OLD.sales_team_id IS DISTINCT FROM NEW.sales_team_id) THEN
  RAISE EXCEPTION 'Posted sales attribution is immutable.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted') AND NEW.kind IN ('customer_invoice','customer_credit') AND NEW.sales_rep_id IS NULL THEN
  SELECT c.sales_rep_id INTO NEW.sales_rep_id FROM public.customer_roles c WHERE c.org_id=NEW.org_id AND c.party_id=NEW.party_id;
  IF NEW.sales_team_id IS NULL THEN
   SELECT (v.definition->>'sales_team_id')::uuid INTO NEW.sales_team_id FROM public.crm_account_profiles cp
    JOIN LATERAL(SELECT definition FROM public.crm_sales_territory_versions v WHERE v.org_id=cp.org_id AND v.territory_id=cp.territory_id AND v.effective_from<=COALESCE(NEW.posting_date,NEW.document_date) ORDER BY effective_from DESC,revision DESC LIMIT 1)v ON true
    WHERE cp.org_id=NEW.org_id AND cp.party_id=NEW.party_id AND cp.sales_rep_id=NEW.sales_rep_id;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: sales_employee_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_employee_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE field_name text; employee uuid; before_value jsonb; after_value jsonb;
BEGIN
 after_value:=to_jsonb(NEW);
 IF TG_OP='UPDATE' THEN before_value:=to_jsonb(OLD); ELSE before_value:='{}'::jsonb; END IF;
 FOREACH field_name IN ARRAY TG_ARGV LOOP
  employee:=NULLIF(after_value->>field_name,'')::uuid;
  IF employee IS NOT NULL AND (TG_OP='INSERT' OR before_value->field_name IS DISTINCT FROM after_value->field_name) THEN
   PERFORM 1 FROM public.employee_roles e JOIN public.parties p ON p.org_id=e.org_id AND p.id=e.party_id
    WHERE e.org_id=NEW.org_id AND e.party_id=employee AND e.is_active AND e.is_sales_rep AND p.is_active
    AND (e.sales_rep_since IS NULL OR e.sales_rep_since<=COALESCE((after_value->>'period_start')::date,(after_value->>'valid_from')::date,(after_value->>'effective_from')::date,CURRENT_DATE)) FOR SHARE OF e,p;
   IF NOT FOUND THEN RAISE EXCEPTION 'Select an active employee designated as a sales representative in Sales → Representatives.' USING ERRCODE='23514'; END IF;
  END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: sales_employee_retirement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_employee_retirement_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF (OLD.is_sales_rep AND NOT NEW.is_sales_rep) OR (OLD.is_active AND NOT NEW.is_active) THEN
  IF EXISTS(SELECT 1 FROM public.customer_roles WHERE org_id=OLD.org_id AND sales_rep_id=OLD.party_id AND is_active)
   OR EXISTS(SELECT 1 FROM public.crm_sales_team_members WHERE org_id=OLD.org_id AND employee_id=OLD.party_id AND is_active)
   OR EXISTS(SELECT 1 FROM public.crm_sales_teams WHERE org_id=OLD.org_id AND manager_employee_id=OLD.party_id AND is_active)
   OR EXISTS(SELECT 1 FROM public.crm_sales_territories WHERE org_id=OLD.org_id AND (default_employee_id=OLD.party_id OR manager_employee_id=OLD.party_id) AND lifecycle<>'archived')
   OR EXISTS(SELECT 1 FROM public.crm_sales_quotas WHERE org_id=OLD.org_id AND employee_id=OLD.party_id AND lifecycle IN ('draft','pending_approval','approved') AND period_end>=CURRENT_DATE)
   OR EXISTS(SELECT 1 FROM public.crm_opportunities o JOIN public.crm_opportunity_statuses st ON st.org_id=o.org_id AND st.id=o.status_id WHERE o.org_id=OLD.org_id AND o.sales_rep_id=OLD.party_id AND o.is_active AND NOT st.is_closed) THEN
    RAISE EXCEPTION 'Reassign the employee’s active customers, teams, territories and open opportunities, and close or revise open quotas in Sales before removing sales eligibility.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: sales_evidence_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_evidence_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF public.app_bypass_rls_active() AND current_setting('openbooks.amend',true)='on' THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'Sales evidence is immutable; correct the source through its controlled reversal workflow.' USING ERRCODE='23514';
END $$;


--
-- Name: sales_legacy_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_legacy_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE field_name text; before_value jsonb; after_value jsonb;
BEGIN
 after_value:=to_jsonb(NEW);before_value:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
 FOREACH field_name IN ARRAY TG_ARGV LOOP
  IF after_value->>field_name IS NOT NULL AND (TG_OP='INSERT' OR before_value->field_name IS DISTINCT FROM after_value->field_name) THEN
   RAISE EXCEPTION 'Sales responsibility must reference a native employee. Manage assignments in Sales.' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: sales_quota_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_quota_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' AND public.app_bypass_rls_active() AND current_setting('openbooks.amend',true)='on' THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Quota history cannot be deleted; close the quota instead.' USING ERRCODE='23514'; END IF;
 IF OLD.lifecycle IN ('approved','superseded','closed') AND
  (to_jsonb(NEW)-ARRAY['lifecycle','updated_at','updated_by','revision']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['lifecycle','updated_at','updated_by','revision']) THEN
  RAISE EXCEPTION 'Approved quotas are immutable; create a revised quota with a reason and approval.' USING ERRCODE='23514';
 END IF;
 IF NEW.lifecycle IS DISTINCT FROM OLD.lifecycle AND NOT (
  (OLD.lifecycle='draft' AND NEW.lifecycle='pending_approval') OR
  (OLD.lifecycle='pending_approval' AND NEW.lifecycle IN ('draft','approved')) OR
  (OLD.lifecycle='approved' AND NEW.lifecycle IN ('superseded','closed'))) THEN
  RAISE EXCEPTION 'Invalid quota lifecycle transition.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: scheduler_outbox_terminal_audit_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scheduler_outbox_terminal_audit_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'scheduler_outbox_terminal_audit is append-only';
END $$;


--
-- Name: scheduler_outbox_terminal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scheduler_outbox_terminal_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_frozen boolean;
BEGIN
  IF OLD.terminal_failed_at IS NULL THEN
    RETURN NEW;
  END IF;
  v_frozen :=
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.kind IS DISTINCT FROM OLD.kind
    OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
    OR NEW.occurrence_key IS DISTINCT FROM OLD.occurrence_key
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.terminal_failed_at IS DISTINCT FROM OLD.terminal_failed_at
    OR NEW.terminal_failed_by IS DISTINCT FROM OLD.terminal_failed_by;
  IF NOT v_frozen THEN
    RETURN NEW;
  END IF;
  IF NEW.terminal_failed_at IS NOT DISTINCT FROM OLD.terminal_failed_at
     AND NEW.terminal_failed_by IS NOT DISTINCT FROM OLD.terminal_failed_by THEN
    -- Only non-stamp frozen facts moved; nothing authorizes those either.
    RAISE EXCEPTION 'scheduler_outbox terminal-failure evidence is immutable; authorize a replay to reset it';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.scheduler_outbox_terminal_audit prior
     WHERE prior.outbox_row_id = OLD.id
       AND prior.event = 'replay_authorized'
  ) THEN
    RAISE EXCEPTION 'a scheduler_outbox replay reset requires its replay_authorized audit evidence first';
  END IF;
  IF public.openbooks_scheduler_outbox_replay_allowed(OLD.org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'a scheduler_outbox replay reset requires its organization''s authorization pin';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION scheduler_outbox_terminal_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.scheduler_outbox_terminal_guard() IS 'Freezes the audit-bearing facts of stamped scheduler_outbox rows; clearing the stamps requires prior replay evidence plus the transaction-scoped authorization pin.';


--
-- Name: seed_builtin_segments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_builtin_segments(p_org_id uuid) RETURNS void
    LANGUAGE sql
    AS $$
  insert into segment_definitions
    (org_id, key, name, plural_name, source_kind, storage_column,
     is_hierarchical, show_on_header, show_on_lines, show_in_reports,
     allow_account_requirement, sort_order)
  values
    (p_org_id, 'subsidiary', 'Subsidiary', 'Subsidiaries', 'builtin', 'subsidiary_id', true, true, true, true, false, 10),
    (p_org_id, 'department', 'Department', 'Departments', 'builtin', 'department_id', true, true, true, true, true, 20),
    (p_org_id, 'project', 'Project', 'Projects', 'builtin', 'project_id', true, true, true, true, true, 30),
    (p_org_id, 'location', 'Location', 'Locations', 'builtin', 'location_id', true, true, true, true, true, 40),
    (p_org_id, 'class', 'Class', 'Classes', 'builtin', 'class_id', true, true, true, true, true, 50)
  on conflict (org_id, key) do nothing
$$;


--
-- Name: seed_builtin_segments_on_org_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_builtin_segments_on_org_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Sandbox tenants clone the production segment graph with deterministically
  -- rebased identities; pre-seeding would create duplicate logical keys.
  if new.env_kind = 'sandbox' then return new; end if;
  perform seed_builtin_segments(new.id);
  return new;
end $$;


--
-- Name: segment_definition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.segment_definition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and old.source_kind = 'builtin'
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'built-in segment definitions cannot be deleted' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and old.source_kind = 'builtin' and
     (new.key <> old.key or new.source_kind <> old.source_kind or new.storage_column is distinct from old.storage_column) then
    raise exception 'built-in segment identity cannot be changed' using errcode = '23514';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;


--
-- Name: segment_definitions_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.segment_definitions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_value_segment uuid;
  v_line_count bigint;
begin
  if new.default_value_id is not null then
    select segment_id into v_value_segment
      from public.segment_values
     where org_id = new.org_id and id = new.default_value_id;
    if not found or v_value_segment is distinct from new.id then
      raise exception 'default value % does not belong to segment %', new.default_value_id, new.key
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'UPDATE' and old.is_balancing and not new.is_balancing then
    select count(*) into v_line_count
      from public.journal_lines l
      join public.journal_entries e on e.org_id = l.org_id and e.id = l.entry_id
     where l.org_id = old.org_id
       and l.extra_dims ? old.key
       and e.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'segment % cannot stop balancing while % posted journal lines carry it',
        old.key, v_line_count using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: segment_value_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.segment_value_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_hierarchical boolean;
  old_scope text;
  new_scope text;
  first_scope text;
  second_scope text;
  tree_scope text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (OLD.org_id, OLD.segment_id) IS DISTINCT FROM (NEW.org_id, NEW.segment_id) THEN
    old_scope := OLD.org_id::text || ':' || OLD.segment_id::text;
    new_scope := NEW.org_id::text || ':' || NEW.segment_id::text;
    first_scope := LEAST(old_scope, new_scope);
    second_scope := GREATEST(old_scope, new_scope);
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || first_scope, 0)
    );
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || second_scope, 0)
    );
  ELSE
    tree_scope := NEW.org_id::text || ':' || NEW.segment_id::text;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || tree_scope, 0)
    );
  END IF;

  SELECT is_hierarchical INTO v_hierarchical
    FROM public.segment_definitions
   WHERE id = NEW.segment_id
     AND org_id = NEW.org_id
     AND source_kind = 'custom'
   FOR KEY SHARE;
  IF v_hierarchical IS NULL THEN
    RAISE EXCEPTION 'segment value must belong to a custom segment in this organization'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE'
     AND (OLD.org_id, OLD.segment_id) IS DISTINCT FROM (NEW.org_id, NEW.segment_id)
     AND EXISTS (
       SELECT 1 FROM public.segment_values child
        WHERE child.parent_id = OLD.id
          AND child.org_id = OLD.org_id
          AND child.segment_id = OLD.segment_id
     ) THEN
    RAISE EXCEPTION 'a segment value with children cannot change organization or segment'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.subsidiary_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.subsidiaries subsidiary
     WHERE subsidiary.id = NEW.subsidiary_id AND subsidiary.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'segment value subsidiary belongs to another organization'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.parent_id IS NOT NULL THEN
    IF NOT v_hierarchical THEN
      RAISE EXCEPTION 'this segment is not hierarchical' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.segment_values parent
       WHERE parent.id = NEW.parent_id
         AND parent.org_id = NEW.org_id
         AND parent.segment_id = NEW.segment_id
    ) THEN
      RAISE EXCEPTION 'segment value parent is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.parent_id = NEW.id OR EXISTS (
      WITH RECURSIVE descendants AS (
        SELECT id
          FROM public.segment_values
         WHERE org_id = NEW.org_id
           AND segment_id = NEW.segment_id
           AND parent_id = NEW.id
        UNION
        SELECT value.id
          FROM public.segment_values value
          JOIN descendants descendant ON value.parent_id = descendant.id
         WHERE value.org_id = NEW.org_id
           AND value.segment_id = NEW.segment_id
      )
      SELECT 1 FROM descendants WHERE id = NEW.parent_id
    ) THEN
      RAISE EXCEPTION 'segment value hierarchy contains a cycle' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION segment_value_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.segment_value_guard() IS 'openbooks:segment_value_guard:v2 - serializes each organization/segment tree mutation through a transaction-scoped advisory fence before scope and descendant checks, preventing concurrent cross-reparent cycles for API, import, and direct writers';


--
-- Name: segment_values_clear_default_for_wipe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.segment_values_clear_default_for_wipe() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if public.openbooks_sandbox_wipe_allowed(old.org_id) then
    update public.segment_definitions
       set default_value_id = null, updated_at = now()
     where org_id = old.org_id and default_value_id = old.id;
  end if;
  return old;
end $$;


--
-- Name: sftp_root_prefix_tenant_conforms(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sftp_root_prefix_tenant_conforms(p_org_id uuid, p_root_prefix text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT p_root_prefix ~ ('^sftp/' || p_org_id::text || '(/|$)')
     AND p_root_prefix ~ '^[^/%]+(/[^/%]+)*$'
     AND p_root_prefix !~ '\\'
     AND p_root_prefix !~ '(^|/)\.\.?(/|$)'
$_$;


--
-- Name: FUNCTION sftp_root_prefix_tenant_conforms(p_org_id uuid, p_root_prefix text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sftp_root_prefix_tenant_conforms(p_org_id uuid, p_root_prefix text) IS 'openbooks:sftp tenant containment — a root prefix conforms only when it stays under its own org''s sftp/<orgId>/ namespace and is a safe relative folder path (no backslash, no percent-encoding, no dot/empty segments).';


--
-- Name: stock_location_warehouse(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_location_warehouse(p_org_id uuid, p_stock_location_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  current_id uuid := p_stock_location_id;
  current_kind text;
  next_id uuid;
  depth integer := 0;
BEGIN
  WHILE current_id IS NOT NULL LOOP
    SELECT sl.kind, sl.parent_id INTO current_kind, next_id
      FROM public.stock_locations sl
     WHERE sl.id = current_id AND sl.org_id = p_org_id;
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
    IF current_kind = 'warehouse' THEN
      RETURN current_id;
    END IF;
    depth := depth + 1;
    IF depth > 64 THEN
      RAISE EXCEPTION 'stock location % has a parent chain deeper than 64 levels or a cycle', p_stock_location_id;
    END IF;
    current_id := next_id;
  END LOOP;
  RETURN NULL;
END
$$;


--
-- Name: stock_locations_warehouse_nesting_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_locations_warehouse_nesting_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  enclosing uuid;
  enclosing_code text;
  nested_code text;
BEGIN
  enclosing := public.stock_location_warehouse(NEW.org_id, NEW.parent_id);
  IF NEW.kind = 'warehouse' AND enclosing IS NOT NULL THEN
    SELECT code INTO enclosing_code FROM public.stock_locations WHERE id = enclosing AND org_id = NEW.org_id;
    RAISE EXCEPTION 'warehouse % cannot sit inside warehouse %; make it a zone or move it out', NEW.code, enclosing_code
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.kind = 'warehouse' OR enclosing IS NOT NULL) THEN
    WITH RECURSIVE below AS (
      SELECT c.id, c.code, c.kind, 1 AS depth
        FROM public.stock_locations c
       WHERE c.parent_id = NEW.id AND c.org_id = NEW.org_id
      UNION ALL
      SELECT c.id, c.code, c.kind, b.depth + 1
        FROM below b
        JOIN public.stock_locations c ON c.parent_id = b.id AND c.org_id = NEW.org_id
       WHERE b.depth < 64
    )
    SELECT code INTO nested_code FROM below WHERE kind = 'warehouse' LIMIT 1;
    IF nested_code IS NOT NULL THEN
      RAISE EXCEPTION 'warehouse % cannot sit inside another warehouse; make it a zone or move it out', nested_code
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: stock_locations_warehouse_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_locations_warehouse_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF NEW.kind = 'warehouse' AND NOT EXISTS (
       SELECT 1 FROM public.warehouses w
        WHERE w.stock_location_id = NEW.id AND w.org_id = NEW.org_id) THEN
    INSERT INTO public.warehouses
      (stock_location_id, org_id, name, status, status_changed_at, status_changed_by, created_by, updated_by)
    VALUES
      (NEW.id, NEW.org_id, NEW.code,
       CASE WHEN NEW.is_active THEN 'active' ELSE 'suspended' END,
       now(), NEW.created_by, NEW.created_by, NEW.created_by);
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: stock_locations_warehouse_shape_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_locations_warehouse_shape_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  stranded record;
BEGIN
  IF NEW.kind IS DISTINCT FROM OLD.kind AND EXISTS (
       SELECT 1 FROM public.warehouses w
        WHERE w.stock_location_id = OLD.id AND w.org_id = OLD.org_id) THEN
    RAISE EXCEPTION 'stock location % is a warehouse and cannot change kind; retire the warehouse and create the new location instead', OLD.code
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.parent_id IS DISTINCT FROM OLD.parent_id THEN
    SELECT r.sequence, t.code AS target_code, wl.code AS warehouse_code INTO stranded
      FROM public.putaway_rules r
      JOIN public.stock_locations t ON t.id = r.target_location_id AND t.org_id = r.org_id
      JOIN public.stock_locations wl ON wl.id = r.warehouse_id AND wl.org_id = r.org_id
     WHERE r.org_id = NEW.org_id
       AND public.stock_location_warehouse(r.org_id, r.target_location_id) IS DISTINCT FROM r.warehouse_id
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'moving % would take putaway target % out of warehouse % (rule %); change that rule first',
        NEW.code, stranded.target_code, stranded.warehouse_code, stranded.sequence
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: subscription_amendment_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_amendment_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF OLD.status = 'applied' THEN
    RAISE EXCEPTION 'applied subscription amendments are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: subscription_period_invoice_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_period_invoice_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'subscription period invoice lineage is immutable';
END $$;


--
-- Name: subscription_plan_version_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_plan_version_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF OLD.status IN ('published','superseded') THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'published subscription plan versions are immutable';
    END IF;
    IF ROW(OLD.plan_id,OLD.effective_from,OLD.name,OLD.description,OLD.currency_code,OLD.interval,OLD.interval_count,OLD.billing_timing,OLD.published_at,OLD.published_by)
      IS DISTINCT FROM ROW(NEW.plan_id,NEW.effective_from,NEW.name,NEW.description,NEW.currency_code,NEW.interval,NEW.interval_count,NEW.billing_timing,NEW.published_at,NEW.published_by)
    THEN
      RAISE EXCEPTION 'published subscription plan commercial terms are immutable';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: subscription_version_component_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_version_component_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_version uuid; parent_status text;
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  parent_version := CASE WHEN TG_OP = 'DELETE' THEN OLD.version_id ELSE NEW.version_id END;
  SELECT status INTO parent_status FROM subscription_plan_versions WHERE id=parent_version;
  IF parent_status IN ('published','superseded') THEN
    RAISE EXCEPTION 'components of published subscription plan versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: subsidiary_ref_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subsidiary_ref_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.subsidiary_id is not null and not exists (
    select 1 from subsidiaries s where s.id = new.subsidiary_id and s.org_id = new.org_id
  ) then
    raise exception 'subsidiary belongs to another organization' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: subsidiary_tree_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subsidiary_tree_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  first_org uuid;
  second_org uuid;
  tree_org uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.org_id IS DISTINCT FROM NEW.org_id THEN
    first_org := LEAST(OLD.org_id::text, NEW.org_id::text)::uuid;
    second_org := GREATEST(OLD.org_id::text, NEW.org_id::text)::uuid;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('subsidiary-tree:' || first_org::text, 0)
    );
    PERFORM pg_advisory_xact_lock(
      hashtextextended('subsidiary-tree:' || second_org::text, 0)
    );
  ELSE
    tree_org := CASE WHEN TG_OP = 'DELETE' THEN OLD.org_id ELSE NEW.org_id END;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('subsidiary-tree:' || tree_org::text, 0)
    );
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.parent_id IS NULL
       AND EXISTS (SELECT 1 FROM public.orgs WHERE id = OLD.org_id)
       AND NOT public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RAISE EXCEPTION 'the root subsidiary cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.parent_id IS NULL AND NEW.parent_id IS NOT NULL THEN
    RAISE EXCEPTION 'the root subsidiary cannot be moved' USING ERRCODE = '23514';
  END IF;
  IF NEW.parent_id IS NULL AND NOT NEW.is_active THEN
    RAISE EXCEPTION 'the root subsidiary cannot be inactive' USING ERRCODE = '23514';
  END IF;
  IF NEW.parent_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
        FROM public.subsidiaries parent
       WHERE parent.id = NEW.parent_id
         AND parent.org_id = NEW.org_id
    ) THEN
      RAISE EXCEPTION 'subsidiary parent belongs to another organization' USING ERRCODE = '23514';
    END IF;
    IF NEW.parent_id = NEW.id OR EXISTS (
      WITH RECURSIVE descendants AS (
        SELECT id
          FROM public.subsidiaries
         WHERE org_id = NEW.org_id AND parent_id = NEW.id
        UNION ALL
        SELECT subsidiary.id
          FROM public.subsidiaries subsidiary
          JOIN descendants descendant ON subsidiary.parent_id = descendant.id
         WHERE subsidiary.org_id = NEW.org_id
      )
      SELECT 1 FROM descendants WHERE id = NEW.parent_id
    ) THEN
      RAISE EXCEPTION 'subsidiary hierarchy contains a cycle' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION subsidiary_tree_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subsidiary_tree_guard() IS 'openbooks:subsidiary_tree_guard:v2 - serializes each organization tree mutation through a transaction-scoped advisory fence before parent and descendant checks, preventing concurrent cross-reparent cycles while preserving root invariants';


--
-- Name: tax_filing_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_filing_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if openbooks_sandbox_wipe_allowed(old.org_id) then return old; end if;
    raise exception 'tax filing snapshots cannot be deleted';
  end if;
  if old.status = 'prepared' and new.status = 'filed'
     and (to_jsonb(new) - 'status' - 'filing_reference' - 'filed_at' - 'updated_at' - 'updated_by')
       = (to_jsonb(old) - 'status' - 'filing_reference' - 'filed_at' - 'updated_at' - 'updated_by')
  then
    return new;
  end if;
  raise exception 'tax filing snapshots are immutable';
end $$;


--
-- Name: tax_group_member_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_group_member_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare group_org uuid; code_org uuid;
begin
  if new.sequence <= 0 then raise exception 'tax group member sequence must be positive'; end if;
  select org_id into group_org from tax_groups where id = new.tax_group_id;
  select org_id into code_org from tax_codes where id = new.tax_code_id;
  if group_org is null or code_org is null or group_org <> code_org then
    raise exception 'tax group and tax code must belong to the same organization';
  end if;
  return new;
end $$;


--
-- Name: tax_group_members_parent_org_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_group_members_parent_org_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.org_id IS NOT DISTINCT FROM OLD.org_id THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'tax_groups'
     AND EXISTS (
       SELECT 1
         FROM public.tax_group_members member
         JOIN public.tax_codes code ON code.id = member.tax_code_id
        WHERE member.tax_group_id = OLD.id
          AND code.org_id IS DISTINCT FROM NEW.org_id
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'tax_group_members organization would diverge from tax_group';
  END IF;

  IF TG_TABLE_NAME = 'tax_codes'
     AND EXISTS (
       SELECT 1
         FROM public.tax_group_members member
         JOIN public.tax_groups group_row ON group_row.id = member.tax_group_id
        WHERE member.tax_code_id = OLD.id
          AND group_row.org_id IS DISTINCT FROM NEW.org_id
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'tax_group_members organization would diverge from tax_code';
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: FUNCTION tax_group_members_parent_org_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tax_group_members_parent_org_guard() IS 'openbooks:tax_group_members_parent_org_guard:v1 - parent organization updates cannot strand an org-less tax-group membership';


--
-- Name: tax_group_members_tenant_coherence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_group_members_tenant_coherence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  group_org uuid;
  code_org uuid;
BEGIN
  SELECT org_id INTO group_org
    FROM public.tax_groups
   WHERE id = NEW.tax_group_id;
  SELECT org_id INTO code_org
    FROM public.tax_codes
   WHERE id = NEW.tax_code_id;

  -- Missing parents remain the responsibility of the original FKs.  This is
  -- important for deferred insertion order and preserves their error/action
  -- semantics exactly.
  IF group_org IS NULL OR code_org IS NULL THEN
    RETURN NEW;
  END IF;
  IF group_org IS DISTINCT FROM code_org THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'tax_group_members references parents from different organizations',
      DETAIL = jsonb_build_object(
        'tax_group_id', NEW.tax_group_id,
        'tax_code_id', NEW.tax_code_id,
        'tax_group_org_id', group_org,
        'tax_code_org_id', code_org
      )::text;
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: FUNCTION tax_group_members_tenant_coherence_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tax_group_members_tenant_coherence_guard() IS 'openbooks:tax_group_members_tenant_coherence_guard:v1 - explicit org-less bridge exception; both tenant-owned parents must share one organization';


--
-- Name: tax_rates_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_rates_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (
    select 1
      from tax_rates r
     where r.id <> new.id
       and r.org_id = new.org_id
       and r.tax_code_id = new.tax_code_id
       and effective_date_ranges_overlap(r.effective_from, r.effective_to, new.effective_from, new.effective_to)
  ) then
    raise exception 'tax rates overlap for tax code %', new.tax_code_id using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: tax_registrations_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_registrations_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.subsidiary_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.subsidiaries s WHERE s.org_id=NEW.org_id AND s.id=NEW.subsidiary_id AND s.is_active AND NOT s.is_elimination)
    THEN RAISE EXCEPTION 'tax registration must belong to an active legal entity in this organization'; END IF;
  IF NOT NEW.is_active THEN RETURN NEW; END IF;
  IF EXISTS(SELECT 1 FROM public.tax_registrations r WHERE r.id<>NEW.id AND r.org_id=NEW.org_id AND r.is_active
    AND r.subsidiary_id IS NOT DISTINCT FROM NEW.subsidiary_id AND r.jurisdiction_id=NEW.jurisdiction_id
    AND coalesce(r.return_form_code,'')=coalesce(NEW.return_form_code,'')
    AND public.effective_date_ranges_overlap(coalesce(r.effective_from,'-infinity'::date),r.effective_to,coalesce(NEW.effective_from,'-infinity'::date),NEW.effective_to))
    THEN RAISE EXCEPTION 'tax registrations overlap for this legal entity, jurisdiction and return form' USING ERRCODE='23P01'; END IF;
  RETURN NEW;
END $$;


--
-- Name: time_entries_default_work_region(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.time_entries_default_work_region() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_site text;
  v_profile_region text;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.work_region IS NULL THEN
    IF NEW.project_id IS NOT NULL THEN
      SELECT p.site_jurisdiction INTO v_site
        FROM public.projects p
       WHERE p.org_id = NEW.org_id AND p.id = NEW.project_id;
    END IF;
    IF v_site IS NOT NULL THEN
      NEW.work_region := CASE WHEN v_site LIKE '%-%'
        THEN split_part(v_site, '-', 2) ELSE v_site END;
      NEW.work_region_source := 'project_site';
    ELSE
      SELECT ep.province INTO v_profile_region
        FROM public.employee_payroll_profiles ep
       WHERE ep.org_id = NEW.org_id AND ep.employee_party_id = NEW.employee_party_id
       ORDER BY ep.updated_at DESC, ep.id
       LIMIT 1;
      IF v_profile_region IS NOT NULL THEN
        NEW.work_region := v_profile_region;
        NEW.work_region_source := 'payroll_profile';
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND
     (NEW.work_region, NEW.work_subregion) IS DISTINCT FROM
     (OLD.work_region, OLD.work_subregion) THEN
    IF EXISTS (
      SELECT 1 FROM public.pay_stubs s
      JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
      JOIN public.documents d ON d.org_id = r.org_id AND d.id = r.document_id
      WHERE s.org_id = NEW.org_id AND s.employee_party_id = NEW.employee_party_id
        AND NEW.worked_on BETWEEN r.period_start AND r.period_end
        AND r.run_status = 'committed' AND d.status <> 'voided'
    ) THEN
      RAISE EXCEPTION 'Payroll work jurisdiction is locked because a payroll run covering this service date is committed'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.work_region_source IS DISTINCT FROM 'hr_override'
       OR nullif(btrim(NEW.work_region_reason), '') IS NULL THEN
      RAISE EXCEPTION 'Changing a time entry work jurisdiction requires an HR override reason'
        USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
    VALUES (NEW.org_id, 'time_entries', NEW.id, 'work_jurisdiction_override',
      jsonb_build_object('before', jsonb_build_object('region', OLD.work_region, 'subregion', OLD.work_subregion),
                         'after', jsonb_build_object('region', NEW.work_region, 'subregion', NEW.work_subregion),
                         'reason', NEW.work_region_reason), NEW.updated_by);
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: trg_application_open_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_application_open_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_doc uuid;
begin
  if openbooks_sandbox_wipe_allowed(
       case when tg_op = 'DELETE' then old.org_id else new.org_id end
     ) then
    return null;
  end if;
  for v_doc in
    select distinct d.id
      from documents d
      join journal_lines jl on jl.entry_id = d.posted_entry_id
     where jl.is_open_item
       and jl.id in (coalesce(new.to_line_id, old.to_line_id),
                     coalesce(new.from_line_id, old.from_line_id))
  loop
    perform recompute_document_open_balance(v_doc);
  end loop;
  return null;
end $$;


--
-- Name: trg_document_open_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_document_open_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM recompute_document_open_balance(NEW.id);
  RETURN NULL;
END $$;


--
-- Name: trg_hrm_survey_response_unique_questions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_hrm_survey_response_unique_questions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT public.hrm_survey_answers_have_unique_question_ids(NEW.answers) THEN
    RAISE EXCEPTION 'survey response must contain at most one answer per question'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'hrm_survey_responses_unique_question_ids';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_journal_line_open_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_journal_line_open_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_entries uuid[];
  v_entry uuid;
  v_doc uuid;
  v_org uuid;
begin
  if tg_op = 'DELETE' then
    v_entries := array[old.entry_id];
    v_org := old.org_id;
  elsif tg_op = 'INSERT' then
    v_entries := array[new.entry_id];
    v_org := new.org_id;
  elsif new.entry_id is distinct from old.entry_id
     or new.account_id is distinct from old.account_id
     or new.amount is distinct from old.amount
     or new.txn_amount is distinct from old.txn_amount
     or new.currency is distinct from old.currency
     or new.is_open_item is distinct from old.is_open_item then
    v_entries := array[old.entry_id, new.entry_id];
    v_org := new.org_id;
  else
    return new;
  end if;
  for v_entry in select distinct e from unnest(v_entries) as e loop
    for v_doc in select d.id from public.documents d
                  where d.org_id = v_org and d.posted_entry_id = v_entry loop
      perform public.recompute_document_open_balance(v_doc);
    end loop;
  end loop;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end $$;


--
-- Name: trg_party_payment_stats_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_party_payment_stats_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_app record;
  v_bill_now date;
  v_pay_now date;
begin
  -- Only the re-dated line's image differs; the other leg still reads its
  -- live row. Each firing moves its own applications from its own
  -- before-image to its own after-image, so multi-row cascades converge.
  for v_app in select x.from_line_id as f, x.to_line_id as t
                 from public.applications x
                where x.org_id = new.org_id and x.unapplied_at is null
                  and (x.from_line_id = new.id or x.to_line_id = new.id) loop
    select bl.posting_date, pl.posting_date
      into v_bill_now, v_pay_now
      from public.journal_lines bl
      join public.journal_lines pl on pl.id = v_app.f and pl.org_id = new.org_id
     where bl.id = v_app.t and bl.org_id = new.org_id;
    perform public.openbooks_party_payment_stats_delta(
      v_app.f, v_app.t, -1,
      case when v_app.t = old.id then old.posting_date else v_bill_now end,
      case when v_app.f = old.id then old.posting_date else v_pay_now end);
    perform public.openbooks_party_payment_stats_delta(
      v_app.f, v_app.t, 1,
      case when v_app.t = new.id then new.posting_date else v_bill_now end,
      case when v_app.f = new.id then new.posting_date else v_pay_now end);
  end loop;
  return new;
end $$;


--
-- Name: usage_prepaid_draws_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usage_prepaid_draws_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'prepaid draw evidence is append-only';
END;
$$;


--
-- Name: usage_rating_bands_draft_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usage_rating_bands_draft_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_org uuid;
  target_version uuid;
  version_status text;
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    target_org := OLD.org_id;
    target_version := OLD.plan_version_id;
    SELECT status INTO version_status FROM public.usage_rating_plan_versions
      WHERE org_id = target_org AND id = target_version;
    IF version_status = 'published' THEN
      RAISE EXCEPTION 'bands of a published usage rating plan version are immutable; publish a new version';
    END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT status INTO version_status FROM public.usage_rating_plan_versions
      WHERE org_id = NEW.org_id AND id = NEW.plan_version_id;
    IF version_status = 'published' THEN
      RAISE EXCEPTION 'bands of a published usage rating plan version are immutable; publish a new version';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: usage_rating_published_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usage_rating_published_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'usage rating plan versions must be created as drafts';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'published' THEN
    RAISE EXCEPTION 'published usage rating plan versions are immutable; publish a new version';
  END IF;
  IF TG_OP = 'DELETE' AND OLD.status = 'published' THEN
    RAISE EXCEPTION 'published usage rating plan versions are immutable; retain the published version';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: usage_rating_runs_transition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usage_rating_runs_transition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'active' THEN
      RAISE EXCEPTION 'a rating run must begin active';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.id IS DISTINCT FROM OLD.id
     OR NEW.link_id IS DISTINCT FROM OLD.link_id
     OR NEW.plan_version_id IS DISTINCT FROM OLD.plan_version_id
     OR NEW.period_start IS DISTINCT FROM OLD.period_start
     OR NEW.period_end IS DISTINCT FROM OLD.period_end
     OR NEW.input_hash IS DISTINCT FROM OLD.input_hash
     OR NEW.output_hash IS DISTINCT FROM OLD.output_hash
     OR NEW.supersedes_run_id IS DISTINCT FROM OLD.supersedes_run_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR (NEW.invoice_id IS DISTINCT FROM OLD.invoice_id
         AND NOT (OLD.invoice_id IS NOT NULL AND NEW.invoice_id IS NULL
                  AND OLD.status = 'active' AND NEW.status = 'superseded'
                  AND EXISTS (
                    SELECT 1 FROM public.documents d
                     WHERE d.org_id = OLD.org_id AND d.id = OLD.invoice_id
                       AND d.status = 'draft'
                  )))
     OR NOT (NEW.status = OLD.status OR (OLD.status = 'active' AND NEW.status = 'superseded')) THEN
    RAISE EXCEPTION 'rating run evidence is immutable except for superseding or clearing a deleted draft invoice';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: uuid_generate_v7(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_generate_v7() RETURNS uuid
    LANGUAGE sql PARALLEL SAFE
    AS $$
      select encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid())
        placing substring(int8send((extract(epoch from clock_timestamp()) * 1000)::bigint) from 3)
        from 1 for 6), 52, 1), 53, 1), 'hex')::uuid
    $$;


--
-- Name: validate_application_idempotency_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_application_idempotency_actor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM users
     WHERE id = NEW.actor_id AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'application operation actor must belong to the organization';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_country_tax_pack_installation_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_country_tax_pack_installation_actor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.installed_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users WHERE id = NEW.installed_by AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'country tax pack installer must belong to the installation organization';
  END IF;
  IF NEW.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users WHERE id = NEW.superseded_by AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'country tax pack superseding actor must belong to the installation organization';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_document_posted_period_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_document_posted_period_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_status text;
  current_entry_id uuid;
  current_period_id uuid;
  current_org_id uuid;
  entry_period_id uuid;
  entry_org_id uuid;
BEGIN
  SELECT status, posted_entry_id, posting_period_id, org_id
    INTO current_status, current_entry_id, current_period_id, current_org_id
    FROM documents
   WHERE id = NEW.id;

  -- The document may have been deleted later in the same transaction.
  IF NOT FOUND OR current_status <> 'posted' THEN
    RETURN NULL;
  END IF;
  IF current_entry_id IS NULL OR current_period_id IS NULL THEN
    RAISE EXCEPTION 'posted document requires exact journal and accounting-period identity';
  END IF;
  SELECT period_id, org_id
    INTO entry_period_id, entry_org_id
    FROM journal_entries
   WHERE id = current_entry_id;
  IF entry_period_id IS NULL
     OR entry_org_id <> current_org_id
     OR entry_period_id <> current_period_id THEN
    RAISE EXCEPTION 'document posting period must equal its posted journal period';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: validate_extra_dims(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_extra_dims(p_org_id uuid, p_dims jsonb, p_subsidiary_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
declare d record;
begin
  if jsonb_typeof(coalesce(p_dims, '{}'::jsonb)) <> 'object' then
    raise exception 'custom segment assignments must be an object' using errcode = '23514';
  end if;
  for d in
    select pair.key, pair.value, sv.subsidiary_id, sv.subsidiary_include_children
      from jsonb_each_text(coalesce(p_dims, '{}'::jsonb)) pair
      left join segment_definitions sd on sd.org_id = p_org_id and sd.key = pair.key
       and sd.source_kind = 'custom' and sd.is_active
      left join segment_values sv on sv.segment_id = sd.id and sv.org_id = sd.org_id
       and sv.id::text = pair.value and sv.is_active
  loop
    if d.subsidiary_include_children is null then
      raise exception 'invalid custom segment assignment for %', d.key using errcode = '23514';
    end if;
    if d.subsidiary_id is not null and p_subsidiary_id is not null and not (
      p_subsidiary_id = d.subsidiary_id or (
        d.subsidiary_include_children and exists (
          with recursive descendants as (
            select id from subsidiaries where id = d.subsidiary_id and org_id = p_org_id
            union all
            select s.id from subsidiaries s join descendants x on s.parent_id = x.id
             where s.org_id = p_org_id
          ) select 1 from descendants where id = p_subsidiary_id
        )
      )
    ) then
      raise exception 'custom segment value % is restricted to another subsidiary', d.value using errcode = '23514';
    end if;
  end loop;
end $$;


--
-- Name: warehouses_location_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warehouses_location_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  location_kind text;
  location_code text;
BEGIN
  SELECT kind, code INTO location_kind, location_code
    FROM public.stock_locations
   WHERE id = NEW.stock_location_id AND org_id = NEW.org_id;
  IF location_kind IS DISTINCT FROM 'warehouse' THEN
    RAISE EXCEPTION 'stock location % is a %, not a warehouse; only a warehouse-kind location can be a warehouse',
      coalesce(location_code, NEW.stock_location_id::text), coalesce(location_kind, 'missing location')
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: wip_prebill_event_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wip_prebill_event_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'WIP prebill events are append-only';
END $$;


--
-- Name: wip_prebill_source_reservation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wip_prebill_source_reservation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status text; source_key uuid;
BEGIN
  SELECT status INTO parent_status FROM wip_prebills WHERE org_id=NEW.org_id AND id=NEW.prebill_id;
  IF parent_status NOT IN ('draft','review','approved') THEN RETURN NEW; END IF;
  source_key := coalesce(NEW.time_entry_id, NEW.document_line_id);
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text||':'||NEW.source_type||':'||source_key::text,0));
  IF EXISTS (SELECT 1 FROM wip_prebill_lines line JOIN wip_prebills worksheet ON worksheet.org_id=line.org_id AND worksheet.id=line.prebill_id
    WHERE line.org_id=NEW.org_id AND line.id<>NEW.id AND line.source_type=NEW.source_type
      AND coalesce(line.time_entry_id,line.document_line_id)=source_key AND worksheet.status IN ('draft','review','approved'))
  THEN RAISE EXCEPTION 'WIP source is already reserved by an active prebill'; END IF;
  RETURN NEW;
END $$;


--
-- Name: worker_employment_versions_closure_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_employment_versions_closure_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Governed amend path (fixture teardown, historical replay, native merge):
  -- the existing house mechanism, not a new bypass. Production paths never
  -- set openbooks.amend; scratch teardown does, or cascade deletes of a
  -- dropped scratch org could never complete.
  IF TG_OP = 'DELETE'
     AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'worker_employment_versions: rows are never deleted; close with a superseding version'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.superseded_by IS NOT NULL THEN
    RAISE EXCEPTION 'worker_employment_versions: closed versions are immutable'
      USING ERRCODE = '23514';
  END IF;
  -- Pure audit touch on a live row (updated_at/updated_by only): housekeeping
  -- attribution, never content. Compared as full images so anything beyond
  -- the volatile audit columns falls through to the append-only refusal; the
  -- closing transition below allowlists its own columns separately.
  IF NEW.superseded_by IS NULL AND NEW.recorded_until IS NULL
     AND NEW.closed_by_change_id IS NULL
     AND to_jsonb(NEW) - ARRAY['updated_at','updated_by']
       = to_jsonb(OLD) - ARRAY['updated_at','updated_by'] THEN
    RETURN NEW;
  END IF;
  IF NEW.superseded_by IS NULL OR NEW.recorded_until IS NULL THEN
    RAISE EXCEPTION 'worker_employment_versions: live rows are append-only; the only allowed UPDATE is the closing transition (recorded_until + superseded_by) or a pure audit touch'
      USING ERRCODE = '23514';
  END IF;
  -- Explicit allowlist: ONLY recorded_until, superseded_by, closed_by_change_id, and the audit
  -- touch (updated_at/updated_by) may differ. Identity, content, effective
  -- and recorded starts, and creation audit can never mutate. The successor
  -- reference and its evidence are validated deferred at commit
  -- (hrm_closure_evidence_guard), because the successor row and its
  -- employment_changes event are written AFTER the close in the same
  -- transaction (close-then-insert-then-evidence).
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.employment_id IS DISTINCT FROM OLD.employment_id
     OR NEW.version_no IS DISTINCT FROM OLD.version_no
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
     OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
     OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'worker_employment_versions: closure sets recorded_until + superseded_by + closed_by_change_id (plus audit touch) only'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION worker_employment_versions_closure_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.worker_employment_versions_closure_guard() IS 'openbooks:worker_employment_versions_closure_guard:v1 - closed rows immutable; live rows accept only the closing transition or a pure audit touch; successor + evidence proven deferred by hrm_closure_evidence_guard';


--
-- Name: worker_employments_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_employments_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE survivor uuid;
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'worker_employments: org_id is immutable (composite children reference it)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.employer_subsidiary_id IS DISTINCT FROM OLD.employer_subsidiary_id THEN
    RAISE EXCEPTION 'worker_employments: employer_subsidiary_id is immutable (transfer = terminate + rehire, never an edit)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.worker_party_id IS DISTINCT FROM OLD.worker_party_id THEN
    -- The marker is the WHOLE contract (merge-owner guarantee): the
    -- absorbed party carries custom.merged_into.survivor, written inside
    -- the merge transaction with the absorbed row deactivated, never
    -- deleted. Deliberately NOT the audit_log row: audit shape is the merge
    -- module's internal detail, and gating a data constraint on a
    -- compliance artifact would couple this table to that shape forever.
    SELECT (custom->'merged_into'->>'survivor')::uuid INTO survivor
      FROM public.parties WHERE id = OLD.worker_party_id AND org_id = OLD.org_id;
    IF survivor IS DISTINCT FROM NEW.worker_party_id THEN
      RAISE EXCEPTION 'worker_employments: worker_party_id changes only through the audited native party merge (engine/src/sync/party-merges.ts)'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: FUNCTION worker_employments_identity_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.worker_employments_identity_guard() IS 'openbooks:worker_employments_identity_guard:v1 - org/employer immutable; worker remap only to the recorded merge survivor (marker), validated deferred at commit. Honest scope: proves the target matches a recorded merge outcome, not that this transaction performed the merge';


--
-- Name: account_group_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_group_members (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    group_id uuid NOT NULL,
    account_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    dimension text NOT NULL
);

ALTER TABLE ONLY public.account_group_members FORCE ROW LEVEL SECURITY;


--
-- Name: account_group_members; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.account_group_members WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    group_id,
    account_id,
    created_at,
    created_by,
    updated_at,
    updated_by,
    dimension
   FROM public.account_group_members
  WHERE (org_id = public.openbooks_query_org_id());


