CREATE TABLE public.asset_events (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    asset_id uuid NOT NULL,
    kind text NOT NULL,
    occurred_on date NOT NULL,
    amount numeric(19,4),
    journal_entry_id uuid,
    memo text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    reverses_event_id uuid,
    reversal_reason text,
    financial_change_id uuid,
    book_id uuid,
    CONSTRAINT asset_events_reversal_shape CHECK ((((kind = 'reversed'::text) AND (reverses_event_id IS NOT NULL) AND ((journal_entry_id IS NOT NULL) OR ((financial_change_id IS NOT NULL) AND (book_id IS NOT NULL))) AND (reversal_reason IS NOT NULL) AND ((length(btrim(reversal_reason)) >= 8) AND (length(btrim(reversal_reason)) <= 500))) OR ((kind <> 'reversed'::text) AND (reverses_event_id IS NULL) AND (reversal_reason IS NULL))))
);

ALTER TABLE ONLY public.asset_events FORCE ROW LEVEL SECURITY;


--
-- Name: asset_events; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.asset_events WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    asset_id,
    kind,
    occurred_on,
    amount,
    journal_entry_id,
    memo,
    created_at,
    created_by,
    updated_at,
    updated_by,
    reverses_event_id,
    reversal_reason,
    financial_change_id,
    book_id
   FROM public.asset_events
  WHERE (org_id = public.openbooks_query_org_id());


