--
-- Name: bank_statement_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_statement_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    statement_id uuid NOT NULL,
    line_number integer NOT NULL,
    posted_on date NOT NULL,
    amount numeric(19,4) NOT NULL,
    currency text NOT NULL,
    description text,
    counterparty_ref text,
    bank_transaction_id text,
    match_status text DEFAULT 'unmatched'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    account_id uuid NOT NULL,
    exclusion_reason text,
    excluded_at timestamp with time zone,
    excluded_by uuid,
    possible_duplicate_of uuid,
    CONSTRAINT bank_statement_lines_exclusion_evidence CHECK ((((match_status = 'excluded'::text) AND (exclusion_reason IS NOT NULL) AND ((length(btrim(exclusion_reason)) >= 5) AND (length(btrim(exclusion_reason)) <= 500)) AND (excluded_at IS NOT NULL) AND (excluded_by IS NOT NULL)) OR ((match_status <> 'excluded'::text) AND (exclusion_reason IS NULL) AND (excluded_at IS NULL) AND (excluded_by IS NULL))))
);

