--
-- Name: crm_opportunity_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_opportunity_lines (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    opportunity_id uuid NOT NULL,
    line_number integer NOT NULL,
    item_id uuid,
    description text,
    quantity numeric(19,4) DEFAULT '1'::numeric NOT NULL,
    unit text,
    unit_price numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    amount numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    probability integer,
    expected_amount numeric(19,4) DEFAULT '0'::numeric NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    unit_cost numeric(19,4),
    cost_amount numeric(19,4),
    CONSTRAINT crm_opportunity_line_cost CHECK ((((unit_cost IS NULL) OR (unit_cost >= (0)::numeric)) AND ((cost_amount IS NULL) OR (cost_amount >= (0)::numeric)) AND ((unit_cost IS NULL) = (cost_amount IS NULL)))),
    CONSTRAINT crm_opportunity_line_values CHECK (((quantity > (0)::numeric) AND (unit_price >= (0)::numeric) AND (amount >= (0)::numeric) AND (expected_amount >= (0)::numeric) AND ((probability IS NULL) OR ((probability >= 0) AND (probability <= 100)))))
);

ALTER TABLE ONLY public.crm_opportunity_lines FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN crm_opportunity_lines.unit_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_opportunity_lines.unit_cost IS 'Expected cost per unit in the opportunity currency (0178). NULL = cost not recorded, which is not the same as zero: an uncosted line has no margin, a zero-cost line has a 100% margin. May exceed unit_price — a deal sold below cost is representable on purpose';


--
-- Name: COLUMN crm_opportunity_lines.cost_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_opportunity_lines.cost_amount IS 'quantity x unit_cost, extended and rounded by the writer (0178) exactly as amount extends unit_price, so a reader never re-derives it. NULL if and only if unit_cost is NULL';


--
-- Name: CONSTRAINT crm_opportunity_line_cost ON crm_opportunity_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT crm_opportunity_line_cost ON public.crm_opportunity_lines IS 'Cost is non-negative and all-or-nothing (0178): cost_amount is a stored derivation of unit_cost, so a row carrying one without the other would carry a derivation nobody can reproduce';


--
-- Name: crm_opportunity_lines; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.crm_opportunity_lines WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    opportunity_id,
    line_number,
    item_id,
    description,
    quantity,
    unit,
    unit_price,
    amount,
    probability,
    expected_amount,
    created_at,
    created_by,
    updated_at,
    updated_by,
    unit_cost,
    cost_amount
   FROM public.crm_opportunity_lines
  WHERE (org_id = public.openbooks_query_org_id());


