-- Name: crm_opportunity_statuses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_opportunity_statuses (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    key text NOT NULL,
    name text NOT NULL,
    description text,
    sequence integer DEFAULT 0 NOT NULL,
    probability integer DEFAULT 0 NOT NULL,
    default_forecast_category text DEFAULT 'upside'::text NOT NULL,
    is_closed boolean DEFAULT false NOT NULL,
    is_won boolean DEFAULT false NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    requires_lines boolean DEFAULT false NOT NULL,
    requires_primary_contact boolean DEFAULT false NOT NULL,
    requires_positive_amount boolean DEFAULT false NOT NULL,
    requires_win_loss_reason boolean DEFAULT false NOT NULL,
    CONSTRAINT crm_opportunity_status_probability CHECK (((probability >= 0) AND (probability <= 100))),
    CONSTRAINT crm_opportunity_status_won_closed CHECK (((NOT is_won) OR is_closed))
);

ALTER TABLE ONLY public.crm_opportunity_statuses FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN crm_opportunity_statuses.requires_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_opportunity_statuses.requires_lines IS 'Entering this stage requires at least one opportunity line (0178). Declared per status, enforced by the engine resolver validateOpportunityStageTransition on every write path';


--
-- Name: COLUMN crm_opportunity_statuses.requires_primary_contact; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_opportunity_statuses.requires_primary_contact IS 'Entering this stage requires a primary contact on the opportunity (0178)';


--
-- Name: COLUMN crm_opportunity_statuses.requires_positive_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_opportunity_statuses.requires_positive_amount IS 'Entering this stage requires a projected amount strictly greater than zero (0178). The baseline CHECK already forbids a negative projected amount, so this is the "priced, not merely non-negative" gate';


--
-- Name: COLUMN crm_opportunity_statuses.requires_win_loss_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.crm_opportunity_statuses.requires_win_loss_reason IS 'Entering this stage requires a win/loss reason (0178). Backfilled true on every existing closed-and-not-won status so upgrades keep the rule the edit route used to hard-code; a new status gates nothing until configured';


