    CONSTRAINT depr_lines_amount_direction CHECK (((source = ANY (ARRAY['manual'::text, 'production_usage'::text])) OR ((planned_amount >= (0)::numeric) AND ((posted_amount IS NULL) OR (posted_amount >= (0)::numeric))))),
    CONSTRAINT depr_lines_input_provenance CHECK ((((source = ANY (ARRAY['formula'::text, 'imported'::text])) AND (input_id IS NULL)) OR ((source = ANY (ARRAY['manual'::text, 'production_usage'::text])) AND (input_id IS NOT NULL)))),
    CONSTRAINT depr_lines_non_gl_recognition CHECK (((non_gl_recognized_at IS NULL) OR ((posted_amount IS NOT NULL) AND (journal_entry_id IS NULL) AND (source <> 'imported'::text)))),
    CONSTRAINT depr_lines_posting_evidence_pair CHECK ((((posted_amount IS NULL) AND (journal_entry_id IS NULL)) OR ((posted_amount IS NOT NULL) AND ((posted_amount = (0)::numeric) OR (journal_entry_id IS NOT NULL) OR (source = 'imported'::text) OR (non_gl_recognized_at IS NOT NULL))))),
    CONSTRAINT depr_lines_source_check CHECK ((source = ANY (ARRAY['formula'::text, 'manual'::text, 'production_usage'::text, 'imported'::text])))
);

