    updated_by uuid,
    tax_overridden boolean DEFAULT false NOT NULL,
    subsidiary_id uuid,
    extra_dims jsonb DEFAULT '{}'::jsonb NOT NULL,
    stock_location_id uuid,
    party_id uuid,
    equipment_unit_id uuid,
    rate_version_id uuid,
    rate_presentation text,
    base_quantity numeric(19,4),
    base_unit text,
    cost_rate numeric(19,4),
    bill_rate numeric(19,4),
    cost_amount numeric(19,4),
    bill_amount numeric(19,4),
    recovery_account_id uuid,
    tax_group_id uuid,
    tax_input_amount numeric(19,4),
    field_ticket_id uuid,
    markup_percent numeric(19,4),
    distribution_group_id uuid,
    distribution_rule_id uuid,
    distribution_version_id uuid,
    distribution_locked boolean DEFAULT false NOT NULL,
    settlement_type text,
    price_basis jsonb,
    quantity_cancelled numeric(28,8) DEFAULT 0 NOT NULL,
    CONSTRAINT doc_lines_one_tax_profile CHECK ((num_nonnulls(tax_code_id, tax_group_id) <= 1)),
    CONSTRAINT doc_lines_target CHECK (((item_id IS NOT NULL) OR (account_id IS NOT NULL))),
    CONSTRAINT document_lines_quantity_cancelled_check CHECK (((quantity_cancelled >= (0)::numeric) AND ((quantity_cancelled = (0)::numeric) OR ((quantity_fulfilled + quantity_cancelled) <= quantity)))),
    CONSTRAINT document_lines_rate_presentation_check CHECK (((rate_presentation IS NULL) OR (rate_presentation = ANY (ARRAY['summary'::text, 'rate_components'::text])))),
    CONSTRAINT document_lines_settlement_type CHECK ((settlement_type = ANY (ARRAY['out_of_pocket'::text, 'company_paid'::text, 'personal'::text])))
);

ALTER TABLE ONLY public.document_lines FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN document_lines.quantity_fulfilled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.quantity_fulfilled IS 'Commercial quantity fulfilled against this order line, preserved to eight decimal places.';


--
-- Name: COLUMN document_lines.quantity_billed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.quantity_billed IS 'Commercial quantity billed or converted from this order line, preserved to eight decimal places.';


--
-- Name: COLUMN document_lines.settlement_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.settlement_type IS 'Who fronted the money for this expense line (0171): out_of_pocket = employee paid, company owes a person; company_paid = company-liability card, company owes the issuer; personal = non-business charge on the company card, employee owes the company (receivable, never an expense). NULL = settlement not recorded (all pre-0171 history); the repost path treats NULL as out_of_pocket legacy math';


--
-- Name: COLUMN document_lines.price_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.price_basis IS 'Pricing provenance stamped at pricing time: {kind, scheduleId, levelId, assignmentId, unitPrice, resolvedAt}. Null for hand-priced lines.';


--
-- Name: COLUMN document_lines.quantity_cancelled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.document_lines.quantity_cancelled IS 'Order quantity cancelled and no longer owed to the customer; the sum of the line''s order_line_cancellations rows. Open quantity is quantity - quantity_fulfilled - quantity_cancelled.';


