--
-- Name: employee_payroll_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.employee_payroll_profiles (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    employee_party_id uuid NOT NULL,
    pay_schedule_id uuid NOT NULL,
    province text NOT NULL,
    pay_basis text DEFAULT 'hourly'::text NOT NULL,
    federal_claim_code integer,
    federal_claim_amount numeric(19,4),
    provincial_claim_code integer,
    provincial_claim_amount numeric(19,4),
    additional_tax_per_period numeric(19,4),
    prescribed_zone_deduction numeric(19,4),
    authorized_annual_deductions numeric(19,4),
    authorized_federal_credits numeric(19,4),
    authorized_provincial_credits numeric(19,4),
    cpp_exempt boolean DEFAULT false NOT NULL,
    ei_exempt boolean DEFAULT false NOT NULL,
    tax_exempt boolean DEFAULT false NOT NULL,
    vacation_percent numeric(7,4),
    vacation_method text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    union_agreement_id uuid,
    union_classification_id uuid,
    country text NOT NULL,
    filing_status text,
    multiple_jobs boolean DEFAULT false NOT NULL,
    dependent_credits numeric(19,4),
    other_income_annual numeric(19,4),
    deductions_annual numeric(19,4),
    w4_pre_2020 boolean DEFAULT false NOT NULL,
    w4_allowances integer,
    fica_exempt boolean DEFAULT false NOT NULL,
    futa_exempt boolean DEFAULT false NOT NULL,
    sin_encrypted text,
    sin_last3 text,
    filing_account_id uuid,
    stub_delivery text DEFAULT 'email'::text NOT NULL,
    payment_method text,
    labour_jurisdiction text,
    residence_region text,
    paid_on_commission boolean,
    employment_id uuid,
    pl_rok_urodzenia integer,
    es_ano_nacimiento integer,
    es_grupo_cotizacion integer,
    es_situacion_laboral text,
    jp_hyojun_hoshu integer,
    jp_kaigo_dainigou text,
    br_dependentes integer,
    br_pensao_mensal numeric(19,4),
    sui_exempt boolean DEFAULT false NOT NULL,
    br_salario_familia_filhos integer,
    es_contrato_temporal text,
    statutory_occupation_class text,
    CONSTRAINT employee_payroll_profiles_allowances CHECK (((w4_allowances IS NULL) OR (w4_allowances >= 0))),
    CONSTRAINT employee_payroll_profiles_br_dependentes CHECK (((br_dependentes IS NULL) OR (br_dependentes >= 0))),
    CONSTRAINT employee_payroll_profiles_br_salario_familia CHECK (((br_salario_familia_filhos IS NULL) OR (br_salario_familia_filhos >= 0))),
    CONSTRAINT employee_payroll_profiles_country CHECK ((country ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT employee_payroll_profiles_es_ano CHECK (((es_ano_nacimiento IS NULL) OR ((es_ano_nacimiento >= 1906) AND (es_ano_nacimiento <= 2026)))),
    CONSTRAINT employee_payroll_profiles_es_contrato CHECK (((es_contrato_temporal IS NULL) OR (es_contrato_temporal = ANY (ARRAY['true'::text, 'false'::text])))),
    CONSTRAINT employee_payroll_profiles_es_grupo CHECK (((es_grupo_cotizacion IS NULL) OR ((es_grupo_cotizacion >= 1) AND (es_grupo_cotizacion <= 11)))),
    CONSTRAINT employee_payroll_profiles_es_situacion CHECK (((es_situacion_laboral IS NULL) OR (es_situacion_laboral = ANY (ARRAY['activo'::text, 'pensionista'::text, 'desempleado'::text])))),
    CONSTRAINT employee_payroll_profiles_fed_code CHECK (((federal_claim_code IS NULL) OR ((federal_claim_code >= 0) AND (federal_claim_code <= 10)))),
    CONSTRAINT employee_payroll_profiles_filing_status CHECK (((filing_status IS NULL) OR (filing_status = ANY (ARRAY['single'::text, 'married_joint'::text, 'head_household'::text])))),
    CONSTRAINT employee_payroll_profiles_jp_kaigo CHECK (((jp_kaigo_dainigou IS NULL) OR (jp_kaigo_dainigou = ANY (ARRAY['true'::text, 'false'::text])))),
    CONSTRAINT employee_payroll_profiles_pay_basis CHECK ((pay_basis = ANY (ARRAY['hourly'::text, 'salary'::text]))),
    CONSTRAINT employee_payroll_profiles_payment_method CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['eft'::text, 'cheque'::text])))),
    CONSTRAINT employee_payroll_profiles_prov_code CHECK (((provincial_claim_code IS NULL) OR ((provincial_claim_code >= 0) AND (provincial_claim_code <= 10)))),
    CONSTRAINT employee_payroll_profiles_stub_delivery CHECK ((stub_delivery = ANY (ARRAY['email'::text, 'print'::text, 'both'::text]))),
    CONSTRAINT employee_payroll_profiles_vacation CHECK (((vacation_percent IS NULL) OR (vacation_percent >= (0)::numeric))),
    CONSTRAINT employee_payroll_profiles_vacation_method CHECK ((vacation_method = ANY (ARRAY['accrue'::text, 'pay_each_period'::text])))
);

ALTER TABLE ONLY public.employee_payroll_profiles FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN employee_payroll_profiles.country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.country IS 'Statutory country pack this employee runs under (0190): no default — an unset country is refused by NOT NULL rather than silently becoming Canada. Historical rows carrying ''CA'' may have been defaulted; they are left untouched because a defaulted row is indistinguishable from a chosen one.';


--
-- Name: COLUMN employee_payroll_profiles.residence_region; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.residence_region IS 'Region the employee RESIDES in, when it differs from the region of employment (province). Null means not recorded, which withholding resolution treats as the work region and reports as an assumption. Drives reciprocity, resident sub-region levies (New York City, Philadelphia) and residence-region withholding. Codes are the pack''s own region vocabulary; validated at the API boundary against the country pack, never by a CHECK naming one country''s codes.';


--
-- Name: COLUMN employee_payroll_profiles.paid_on_commission; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.paid_on_commission IS 'Whether the employee is paid in whole or in part on commission, for statutory-holiday rules that read it. Null = unanswered: the engine fails closed exactly as a missing per-request entry does. Never default this to false — a silent false answers for the operator and reintroduces the inference payroll-holidays.ts:700-707 refuses to make.';


--
-- Name: COLUMN employee_payroll_profiles.pl_rok_urodzenia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.pl_rok_urodzenia IS 'Employee birth year for the PL FP age bar (0191): PESEL-derived with a declared fallback for employees without a PESEL; null = unknown, never guessed.';


--
-- Name: COLUMN employee_payroll_profiles.es_ano_nacimiento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_ano_nacimiento IS 'Employee birth year feeding the ES age-banded rule, AÑOPER (0191); null = unknown, never guessed.';


--
-- Name: COLUMN employee_payroll_profiles.es_grupo_cotizacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_grupo_cotizacion IS 'ES Seguridad Social contribution group 1–11, Orden PJC/297/2026 art. 33 (0191); null = undeclared, never group 1 by fallthrough.';


--
-- Name: COLUMN employee_payroll_profiles.es_situacion_laboral; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_situacion_laboral IS 'ES employment situation SITUPER: activo, pensionista or desempleado (0191); null = undeclared, never defaulted.';


--
-- Name: COLUMN employee_payroll_profiles.jp_hyojun_hoshu; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.jp_hyojun_hoshu IS 'Employee 標準報酬月額 grade value in whole yen, copied off the JPS notice (0191); null = undeclared, never priced off raw pay.';


--
-- Name: COLUMN employee_payroll_profiles.jp_kaigo_dainigou; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.jp_kaigo_dainigou IS 'Whether the employee is a 介護保険第2号被保険者, as "true"/"false" text (0191); null = undeclared, never defaulted into the cheaper premium.';


--
-- Name: COLUMN employee_payroll_profiles.br_dependentes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.br_dependentes IS 'Dependent count for the R$ 189,59 IRRF deduction, from the eSocial cadastro (0191); null = unknown, never defaulted.';


--
-- Name: COLUMN employee_payroll_profiles.br_pensao_mensal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.br_pensao_mensal IS 'Court-ordered monthly alimony reducing the IRRF base (0191); null = none ordered, never zero-filled.';


--
-- Name: COLUMN employee_payroll_profiles.sui_exempt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.sui_exempt IS 'State unemployment insurance exemption for this employment; independent of federal FUTA exemption.';


--
-- Name: COLUMN employee_payroll_profiles.br_salario_familia_filhos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.br_salario_familia_filhos IS 'Qualifying children for salário-família (<14 or disabled), from the eSocial cadastro (0389); null = none declared, never defaulted.';


--
-- Name: COLUMN employee_payroll_profiles.es_contrato_temporal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.es_contrato_temporal IS 'ES contract type for the Seguridad Social desempleo split: "true" prices the temporary-contract 8,30% rate, "false" the indefinite 7,05% (Orden PJC/297/2026 art. 33.2.a) (0406); null = undeclared, never indefinite by fallthrough.';


--
-- Name: COLUMN employee_payroll_profiles.statutory_occupation_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.employee_payroll_profiles.statutory_occupation_class IS 'Statutory occupation class for rules that price by occupation (New Brunswick route salesperson, ESA s. 21(2)). Null = unrecorded; validated against the country pack at the profile boundary.';


--
-- Name: CONSTRAINT employee_payroll_profiles_country ON employee_payroll_profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT employee_payroll_profiles_country ON public.employee_payroll_profiles IS 'Pack-country shape check (0175): two uppercase letters. Deliberately NOT an enumeration — packs declare which countries exist (engine/src/payroll/packs.ts), the database only rejects malformed codes.';


--
-- Name: employee_payroll_profiles; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.employee_payroll_profiles WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    employee_party_id,
    pay_schedule_id,
    province,
    pay_basis,
    federal_claim_code,
    federal_claim_amount,
    provincial_claim_code,
    provincial_claim_amount,
    additional_tax_per_period,
    prescribed_zone_deduction,
    authorized_annual_deductions,
    authorized_federal_credits,
    authorized_provincial_credits,
    cpp_exempt,
    ei_exempt,
    tax_exempt,
    vacation_percent,
    vacation_method,
    is_active,
    created_at,
    created_by,
    updated_at,
    updated_by,
    union_agreement_id,
    union_classification_id,
    country,
    filing_status,
    multiple_jobs,
    dependent_credits,
    other_income_annual,
    deductions_annual,
    w4_pre_2020,
    w4_allowances,
    fica_exempt,
    futa_exempt,
    sin_last3,
    filing_account_id,
    stub_delivery,
    payment_method,
    labour_jurisdiction
   FROM public.employee_payroll_profiles
  WHERE (org_id = public.openbooks_query_org_id());


