--
-- Name: COLUMN entitlement_ledger.source_holiday_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.entitlement_ledger.source_holiday_date IS 'Date of the statutory holiday that granted this movement; pairs with source_holiday_key (0413).';


