    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    subsidiary_id uuid NOT NULL,
    depreciation_method text,
    useful_life_months integer,
    depreciation_rate_percent numeric(19,4),
    depreciation_convention text,
    depreciation_units_total numeric(19,4),
    depreciation_method_id uuid,
    asset_account_id uuid,
    accumulated_depreciation_account_id uuid,
    depreciation_expense_account_id uuid,
    opening_accumulated_depreciation numeric(19,4),
    opening_accumulated_as_of date,
    transferred_from_asset_id uuid,
    CONSTRAINT fixed_assets_depreciation_convention_check CHECK (((depreciation_convention IS NULL) OR (depreciation_convention = ANY (ARRAY['full_month'::text, 'mid_month'::text, 'half_year'::text])))),
    CONSTRAINT fixed_assets_depreciation_method_check CHECK (((depreciation_method IS NULL) OR (depreciation_method = ANY (ARRAY['straight_line'::text, 'declining_balance'::text, 'double_declining'::text, 'units_of_production'::text, 'manual'::text])))),
    CONSTRAINT fixed_assets_nonnegative_depreciation_rate CHECK (((depreciation_rate_percent IS NULL) OR (depreciation_rate_percent >= (0)::numeric))),
    CONSTRAINT fixed_assets_opening_balances_check CHECK ((((opening_accumulated_depreciation IS NULL) AND (opening_accumulated_as_of IS NULL)) OR ((opening_accumulated_depreciation IS NOT NULL) AND (opening_accumulated_as_of IS NOT NULL) AND (opening_accumulated_depreciation >= (0)::numeric) AND (opening_accumulated_depreciation <= (acquisition_cost - salvage_value))))),
    CONSTRAINT fixed_assets_positive_depreciation_units CHECK (((depreciation_units_total IS NULL) OR (depreciation_units_total > (0)::numeric))),
    CONSTRAINT fixed_assets_positive_useful_life CHECK (((useful_life_months IS NULL) OR (useful_life_months > 0)))
);

