    CONSTRAINT gifts_in_kind_basis_check CHECK (((kind <> ALL (ARRAY['in_kind_goods'::text, 'in_kind_services'::text])) OR (fair_value_basis IS NOT NULL))),
    CONSTRAINT gifts_kind_check CHECK ((kind = ANY (ARRAY['cash'::text, 'check'::text, 'card'::text, 'stock'::text, 'in_kind_goods'::text, 'in_kind_services'::text, 'other'::text]))),
