    classification text DEFAULT 'finance'::text NOT NULL,
    classification_inputs jsonb DEFAULT '{}'::jsonb NOT NULL,
    exemption text,
    initial_liability numeric(19,4),
    initial_rou_asset numeric(19,4),
    rou_asset_account_id uuid NOT NULL,
