    org_id uuid NOT NULL,
    work_order_id uuid NOT NULL,
    sequence integer NOT NULL,
    name text NOT NULL,
    work_center_id uuid NOT NULL,
    planned_setup_minutes numeric(19,4) NOT NULL,
    planned_run_minutes numeric(19,4) NOT NULL,
    actual_setup_minutes numeric(19,4),
    actual_run_minutes numeric(19,4),
    actual_labor_minutes numeric(19,4),
    quantity_planned numeric(19,4) NOT NULL,
    quantity_done numeric(19,4) DEFAULT 0 NOT NULL,
    quantity_scrapped_here numeric(19,4) DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    operator_user_id uuid,
    pause_reason text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    measured_qty numeric(19,4),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    quality_gate text NOT NULL,
    backflush_at text NOT NULL,
    standard_labor_wage_id uuid,
    standard_labor_effective_from date,
    standard_labor_rate numeric(19,4),
    standard_labor_currency character(3),
    standard_labor_basis text,
    standard_labor_annual_hours numeric(19,4),
    standard_labor_final_rate numeric(19,4),
    standard_labor_functional_currency character(3),
    standard_labor_burden jsonb,
    standard_labor_burden_hash text,
    standard_labor_fx_class text,
    standard_labor_fx_rate numeric(19,10),
    standard_labor_fx_row_id uuid,
    standard_labor_fx_date date,
    standard_labor_fx_source text,
    standard_labor_fx_direction text,
    overhead_snapshot jsonb,
    overhead_snapshot_hash text,
    CONSTRAINT mfg_wo_operations_backflush_check CHECK ((backflush_at = ANY (ARRAY['none'::text, 'start'::text, 'finish'::text]))),
    CONSTRAINT mfg_wo_operations_minutes_nonnegative CHECK (((planned_setup_minutes >= (0)::numeric) AND (planned_run_minutes >= (0)::numeric) AND ((actual_setup_minutes IS NULL) OR (actual_setup_minutes >= (0)::numeric)) AND ((actual_run_minutes IS NULL) OR (actual_run_minutes >= (0)::numeric)) AND ((actual_labor_minutes IS NULL) OR (actual_labor_minutes >= (0)::numeric)))),
    CONSTRAINT mfg_wo_operations_name_nonempty CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT mfg_wo_operations_pause_reason CHECK (((status <> 'paused'::text) OR ((pause_reason IS NOT NULL) AND (length(btrim(pause_reason)) > 0)))),
    CONSTRAINT mfg_wo_operations_quality_gate_check CHECK ((quality_gate = ANY (ARRAY['none'::text, 'measure'::text]))),
    CONSTRAINT mfg_wo_operations_quantities_nonnegative CHECK (((quantity_planned >= (0)::numeric) AND (quantity_done >= (0)::numeric) AND (quantity_scrapped_here >= (0)::numeric) AND ((measured_qty IS NULL) OR (measured_qty >= (0)::numeric)))),
    CONSTRAINT mfg_wo_operations_sequence_positive CHECK ((sequence > 0)),
    CONSTRAINT mfg_wo_operations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'paused'::text, 'done'::text]))),
    CONSTRAINT mfg_woop_ovhd_coherent CHECK ((num_nonnulls(overhead_snapshot, overhead_snapshot_hash) = ANY (ARRAY[0, 2]))),
    CONSTRAINT mfg_woop_std_fx_coherent CHECK (((num_nonnulls(standard_labor_fx_class, standard_labor_fx_rate, standard_labor_fx_row_id, standard_labor_fx_date, standard_labor_fx_source, standard_labor_fx_direction) = 0) OR ((standard_labor_fx_class = 'par'::text) AND (standard_labor_fx_rate = (1)::numeric) AND (standard_labor_fx_row_id IS NULL) AND (standard_labor_fx_date IS NULL) AND (standard_labor_fx_source IS NULL) AND (standard_labor_fx_direction IS NULL)) OR ((standard_labor_fx_class = 'quoted'::text) AND (standard_labor_fx_rate IS NOT NULL) AND (standard_labor_fx_row_id IS NOT NULL) AND (standard_labor_fx_date IS NOT NULL) AND (standard_labor_fx_source IS NOT NULL) AND (standard_labor_fx_direction IS NOT NULL)))),
    CONSTRAINT mfg_woop_std_labor_coherent CHECK ((num_nonnulls(standard_labor_wage_id, standard_labor_effective_from, standard_labor_rate, standard_labor_currency, standard_labor_basis, standard_labor_annual_hours, standard_labor_final_rate, standard_labor_functional_currency, standard_labor_burden, standard_labor_burden_hash) = ANY (ARRAY[0, 10])))
);

ALTER TABLE ONLY public.mfg_wo_operations FORCE ROW LEVEL SECURITY;


