-- Name: parties; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.parties (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    kind text NOT NULL,
    display_name text NOT NULL,
    legal_name text,
    short_code text,
    email text,
    phone text,
    website text,
    tax_ids jsonb DEFAULT '{}'::jsonb,
    is_active boolean DEFAULT true NOT NULL,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    subsidiary_id uuid,
    invoicing_preference jsonb,
    invoicing_profile jsonb,
    payment_method text,
    emergency_contact jsonb,
    CONSTRAINT parties_emergency_contact_shape CHECK (((emergency_contact IS NULL) OR ((jsonb_typeof(emergency_contact) = 'object'::text) AND ((NOT (emergency_contact ? 'name'::text)) OR ((jsonb_typeof((emergency_contact -> 'name'::text)) = 'string'::text) AND (char_length(btrim((emergency_contact ->> 'name'::text))) > 0))) AND ((NOT (emergency_contact ? 'relationship'::text)) OR ((jsonb_typeof((emergency_contact -> 'relationship'::text)) = 'string'::text) AND (char_length(btrim((emergency_contact ->> 'relationship'::text))) > 0))) AND ((NOT (emergency_contact ? 'phone'::text)) OR ((jsonb_typeof((emergency_contact -> 'phone'::text)) = 'string'::text) AND (char_length(btrim((emergency_contact ->> 'phone'::text))) > 0)))))),
    CONSTRAINT parties_payment_method CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['eft'::text, 'cheque'::text, 'card'::text, 'cash'::text, 'other'::text]))))
);

ALTER TABLE ONLY public.parties FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN parties.emergency_contact; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.parties.emergency_contact IS 'HR-9 self-service (0198): the person''s emergency contact as {name, relationship, phone}; null = none recorded. Proposed by the person through a profile_change request, applied on HR approval; masked (null_out) in sandboxes.';


