  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: pay_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pay_runs (
    document_id uuid NOT NULL,
    org_id uuid NOT NULL,
    pay_schedule_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    pay_date date NOT NULL,
    tax_year integer NOT NULL,
    run_status text DEFAULT 'draft'::text NOT NULL,
    run_type text DEFAULT 'regular'::text NOT NULL,
    gross_total numeric(19,4) DEFAULT 0 NOT NULL,
    net_total numeric(19,4) DEFAULT 0 NOT NULL,
    employer_cost_total numeric(19,4) DEFAULT 0 NOT NULL,
    employee_count integer DEFAULT 0 NOT NULL,
    calculated_at timestamp with time zone,
    paid_at timestamp with time zone,
    paid_entry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    calculation_source_snapshot jsonb,
    calculation_source_digest text,
    calculation_errors jsonb,
    refusal_acknowledgement jsonb,
    benefit_source_snapshot jsonb,
    CONSTRAINT pay_runs_calculation_errors_shape CHECK (((calculation_errors IS NULL) OR (jsonb_typeof(calculation_errors) = 'array'::text))),
    CONSTRAINT pay_runs_calculation_source_digest CHECK (((calculation_source_digest IS NULL) OR (calculation_source_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT pay_runs_calculation_source_pair CHECK ((num_nonnulls(calculation_source_snapshot, calculation_source_digest) = ANY (ARRAY[0, 2]))),
    CONSTRAINT pay_runs_calculation_source_shape CHECK (((calculation_source_snapshot IS NULL) OR (jsonb_typeof(calculation_source_snapshot) = 'object'::text))),
    CONSTRAINT pay_runs_pay_date CHECK ((pay_date >= period_end)),
    CONSTRAINT pay_runs_period_order CHECK ((period_end >= period_start)),
    CONSTRAINT pay_runs_refusal_acknowledgement_shape CHECK (((refusal_acknowledgement IS NULL) OR (jsonb_typeof(refusal_acknowledgement) = 'object'::text))),
    CONSTRAINT pay_runs_run_status CHECK ((run_status = ANY (ARRAY['draft'::text, 'calculated'::text, 'committed'::text, 'voided'::text]))),
    CONSTRAINT pay_runs_run_type CHECK ((run_type = ANY (ARRAY['regular'::text, 'bonus'::text, 'termination'::text, 'retro'::text])))
);

ALTER TABLE ONLY public.pay_runs FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN pay_runs.calculation_source_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_runs.calculation_source_snapshot IS 'Versioned canonical time-entry and effective rate inputs that produced the calculated stubs; commit must recompute an exact match.';


--
-- Name: COLUMN pay_runs.calculation_source_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_runs.calculation_source_digest IS 'SHA-256 of calculation_source_snapshot canonical JSON; missing on a calculated legacy run forces recalculation before commit.';


--
-- Name: COLUMN pay_runs.calculation_errors; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_runs.calculation_errors IS 'Per-employee calculation outcomes (refusals, warnings, out-of-scope) from the latest calculate, replaced wholesale on every pass; commit gates on the in-scope refusals and the run page renders them back, so both see what the calculate saw.';


--
-- Name: COLUMN pay_runs.refusal_acknowledgement; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_runs.refusal_acknowledgement IS 'Recorded operator decision to commit despite in-scope refusals: who was left out with the refusal text verbatim, who acknowledged, when, and the digest of the exact refusal set acknowledged.';


--
-- Name: pay_runs; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.pay_runs WITH (security_barrier='true') AS
 SELECT document_id,
    org_id,
    pay_schedule_id,
    period_start,
    period_end,
    pay_date,
    tax_year,
    run_status,
    run_type,
    gross_total,
    net_total,
    employer_cost_total,
    employee_count,
    calculated_at,
    paid_at,
    paid_entry_id,
    created_at,
    created_by,
    updated_at,
    updated_by,
    calculation_source_snapshot,
    calculation_source_digest,
    calculation_errors,
    refusal_acknowledgement,
    benefit_source_snapshot
   FROM public.pay_runs
  WHERE (org_id = public.openbooks_query_org_id());


