    sequence integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    liability_account_id uuid,
    liability_account_source text DEFAULT 'unknown'::text NOT NULL,
    liability_account_evidence jsonb,
    item_id uuid,
    expense_account_id uuid,
    expense_account_source text DEFAULT 'unknown'::text NOT NULL,
    expense_account_evidence jsonb,
    remittance_party_id uuid,
    earned_from date,
    earned_to date,
    statutory_reporting_code jsonb,
    payment_kind text DEFAULT 'cash'::text NOT NULL,
    non_cash_account_id uuid,
    CONSTRAINT pay_stub_lines_earning_dates_pair CHECK ((((earned_from IS NULL) AND (earned_to IS NULL)) OR ((earned_from IS NOT NULL) AND (earned_to IS NOT NULL) AND (earned_from <= earned_to)))),
    CONSTRAINT pay_stub_lines_expense_account_evidence CHECK ((((expense_account_source = 'unknown'::text) AND (expense_account_id IS NULL) AND (expense_account_evidence IS NULL)) OR ((expense_account_source = ANY (ARRAY['item'::text, 'component'::text, 'org_default'::text])) AND (expense_account_id IS NOT NULL) AND (expense_account_evidence IS NOT NULL) AND (jsonb_typeof(expense_account_evidence) = 'object'::text)))),
    CONSTRAINT pay_stub_lines_kind CHECK ((kind = ANY (ARRAY['earning'::text, 'deduction'::text, 'employer_contribution'::text, 'credit'::text]))),
    CONSTRAINT pay_stub_lines_liability_account_evidence CHECK ((((liability_account_source = 'unknown'::text) AND (liability_account_id IS NULL) AND (liability_account_evidence IS NULL)) OR ((liability_account_source = ANY (ARRAY['commit'::text, 'legacy_component'::text])) AND (liability_account_id IS NOT NULL) AND (liability_account_evidence IS NULL)) OR ((liability_account_source = 'reconciled'::text) AND (liability_account_id IS NOT NULL) AND (liability_account_evidence IS NOT NULL) AND (jsonb_typeof(liability_account_evidence) = 'object'::text) AND COALESCE((jsonb_typeof((liability_account_evidence -> 'reason'::text)) = 'string'::text), false) AND COALESCE((jsonb_typeof((liability_account_evidence -> 'reference'::text)) = 'string'::text), false) AND (length(TRIM(BOTH FROM (liability_account_evidence ->> 'reason'::text))) > 0) AND (length(TRIM(BOTH FROM (liability_account_evidence ->> 'reference'::text))) > 0)))),
    CONSTRAINT pay_stub_lines_non_cash_shape CHECK ((((payment_kind = 'cash'::text) AND (non_cash_account_id IS NULL)) OR ((payment_kind = 'non_cash'::text) AND (kind = 'earning'::text) AND (non_cash_account_id IS NOT NULL)))),
    CONSTRAINT pay_stub_lines_payment_kind CHECK ((payment_kind = ANY (ARRAY['cash'::text, 'non_cash'::text]))),
    CONSTRAINT pay_stub_lines_statutory_reporting_code_shape CHECK (((statutory_reporting_code IS NULL) OR ((jsonb_typeof(statutory_reporting_code) = 'object'::text) AND (statutory_reporting_code ?& ARRAY['formCode'::text, 'boxCode'::text, 'code'::text, 'label'::text]) AND (jsonb_typeof((statutory_reporting_code -> 'formCode'::text)) = 'string'::text) AND (jsonb_typeof((statutory_reporting_code -> 'boxCode'::text)) = 'string'::text) AND (jsonb_typeof((statutory_reporting_code -> 'code'::text)) = 'string'::text) AND (jsonb_typeof((statutory_reporting_code -> 'label'::text)) = 'string'::text))))
);

ALTER TABLE ONLY public.pay_stub_lines FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN pay_stub_lines.liability_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.liability_account_id IS 'Liability account this deduction/employer contribution was credited to at commit. Remittances debit this account, never the component''s current setup.';


--
-- Name: COLUMN pay_stub_lines.liability_account_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.liability_account_source IS 'commit = stamped by the committing engine; legacy_component = backfilled from the component''s account at migration 0094 (the figure reported until then); unknown = pre-0094 line whose component named no account (resolves through the pack''s legacy slot).';


--
-- Name: COLUMN pay_stub_lines.liability_account_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.liability_account_evidence IS 'Original posting evidence reference and reason for a one-time audited resolution of an unknown historical liability account.';


--
-- Name: COLUMN pay_stub_lines.item_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.item_id IS 'Service item the hours on this line were worked on, carried from the time entry like project_id/time_type_id. Null for lines with no operational item (salary, bonus, per diem).';


--
-- Name: COLUMN pay_stub_lines.expense_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.expense_account_id IS 'Expense account this earning line was costed to at calculate. Posting debits this account, never the component''s or item''s current setup.';


--
-- Name: COLUMN pay_stub_lines.expense_account_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.expense_account_source IS 'item = the line''s item declared an account; component = fell through to the pay component''s expense account; org_default = fell through to the org wage/burden default; unknown = unstamped history resolving live as before.';


--
-- Name: COLUMN pay_stub_lines.remittance_party_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.remittance_party_id IS 'Remittance destination this deduction/employer contribution/credit accrued to at commit. Remittances route by this, never the component''s current vendor.';


--
-- Name: COLUMN pay_stub_lines.statutory_reporting_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stub_lines.statutory_reporting_code IS 'Tax form reporting code resolved by the country pack at payroll calculation; immutable stub history must not follow later component setup edits.';


--
-- Name: CONSTRAINT pay_stub_lines_kind ON pay_stub_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT pay_stub_lines_kind ON public.pay_stub_lines IS 'Stub line kinds (0179): mirrors pay_components_kind so every seedable component kind is payable.';


