--
-- Name: pay_stubs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pay_stubs (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    pay_run_document_id uuid NOT NULL,
    employee_party_id uuid NOT NULL,
    province text NOT NULL,
    periods_per_year integer NOT NULL,
    pay_date date NOT NULL,
    tax_year integer NOT NULL,
    federal_claim numeric(19,4) DEFAULT 0 NOT NULL,
    provincial_claim numeric(19,4) DEFAULT 0 NOT NULL,
    currency_code text NOT NULL,
    gross numeric(19,4) DEFAULT 0 NOT NULL,
    pensionable_earnings numeric(19,4) DEFAULT 0 NOT NULL,
    insurable_earnings numeric(19,4) DEFAULT 0 NOT NULL,
    net_pay numeric(19,4) DEFAULT 0 NOT NULL,
    employer_cost numeric(19,4) DEFAULT 0 NOT NULL,
    vacation_accrued numeric(19,4) DEFAULT 0 NOT NULL,
    factors jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    payment_method text,
    cheque_number text,
    country text,
    country_source text DEFAULT 'unknown'::text NOT NULL,
    filing_account_id uuid,
    filing_account_source text DEFAULT 'unknown'::text NOT NULL,
    filing_account_evidence jsonb,
    employment_id uuid NOT NULL,
    CONSTRAINT pay_stubs_cheque_number_method CHECK (((cheque_number IS NULL) OR (payment_method = 'cheque'::text))),
    CONSTRAINT pay_stubs_country_evidence CHECK ((((country IS NULL) AND (country_source = 'unknown'::text)) OR ((country IS NOT NULL) AND (country ~ '^[A-Z]{2}$'::text) AND (country_source = ANY (ARRAY['calculation'::text, 'legacy_region'::text]))))),
    CONSTRAINT pay_stubs_filing_account_evidence CHECK ((((filing_account_source = 'unknown'::text) AND (filing_account_id IS NULL) AND (filing_account_evidence IS NULL)) OR ((filing_account_source = ANY (ARRAY['calculation'::text, 'insertion'::text])) AND (filing_account_evidence IS NULL)) OR ((filing_account_source = 'reconciled'::text) AND (filing_account_evidence IS NOT NULL) AND (jsonb_typeof(filing_account_evidence) = 'object'::text) AND COALESCE((jsonb_typeof((filing_account_evidence -> 'reason'::text)) = 'string'::text), false) AND COALESCE((jsonb_typeof((filing_account_evidence -> 'reference'::text)) = 'string'::text), false) AND (length(TRIM(BOTH FROM (filing_account_evidence ->> 'reason'::text))) > 0) AND (length(TRIM(BOTH FROM (filing_account_evidence ->> 'reference'::text))) > 0)))),
    CONSTRAINT pay_stubs_net_nonnegative CHECK ((net_pay >= (0)::numeric)),
    CONSTRAINT pay_stubs_payment_method CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['eft'::text, 'cheque'::text]))))
);

ALTER TABLE ONLY public.pay_stubs FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN pay_stubs.country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.country IS 'Country of the statutory pack that calculated this stub; independent of the current employee profile.';


--
-- Name: COLUMN pay_stubs.country_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.country_source IS 'calculation = captured directly; legacy_region = derived from the existing disjoint province/state snapshot; unknown = requires review before year-end reporting.';


--
-- Name: COLUMN pay_stubs.filing_account_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.filing_account_id IS 'Filing identity captured for this payroll. A captured null is explicitly unassigned; never resolve it from a later profile/default.';


--
-- Name: COLUMN pay_stubs.filing_account_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.filing_account_source IS 'calculation = new engine; insertion = rolling old writer; unknown = legacy evidence required; reconciled = original evidence recorded with actor and immutable audit.';


--
-- Name: COLUMN pay_stubs.filing_account_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pay_stubs.filing_account_evidence IS 'Original payroll evidence reference and reconciliation reason; required only for a one-time resolution of unknown legacy attribution.';


--
-- Name: pay_stubs; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.pay_stubs WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    pay_run_document_id,
    employee_party_id,
    province,
    periods_per_year,
    pay_date,
    tax_year,
    federal_claim,
    provincial_claim,
    currency_code,
    gross,
    pensionable_earnings,
    insurable_earnings,
    net_pay,
    employer_cost,
    vacation_accrued,
    factors,
    created_at,
    created_by,
    updated_at,
    updated_by,
    payment_method,
    cheque_number,
