    CONSTRAINT price_levels_method CHECK ((pricing_method = ANY (ARRAY['explicit'::text, 'markup_discount'::text, 'cost_plus'::text]))),
    CONSTRAINT price_levels_name_present CHECK ((char_length(btrim(name)) > 0))
);

