   FROM public.saas_metrics_facts_monthly
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: saas_metrics_fx_evidence; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.saas_metrics_fx_evidence (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    month date NOT NULL,
    base_currency text NOT NULL,
    quote_currency text NOT NULL,
    rate numeric(19,10) NOT NULL,
    source text NOT NULL,
    quoted_at timestamp with time zone NOT NULL,
    evidence jsonb NOT NULL,
    inputs_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT saas_metrics_fx_evidence_currencies_valid CHECK (((base_currency ~ '^[A-Z]{3}$'::text) AND (quote_currency ~ '^[A-Z]{3}$'::text) AND (base_currency <> quote_currency))),
    CONSTRAINT saas_metrics_fx_evidence_inputs_hash_digest CHECK ((inputs_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT saas_metrics_fx_evidence_month_start CHECK ((EXTRACT(day FROM month) = (1)::numeric)),
    CONSTRAINT saas_metrics_fx_evidence_rate_positive CHECK ((rate > (0)::numeric)),
    CONSTRAINT saas_metrics_fx_evidence_shape CHECK (((jsonb_typeof(evidence) = 'object'::text) AND ((evidence ->> 'base_currency'::text) = base_currency) AND ((evidence ->> 'quote_currency'::text) = quote_currency) AND (((evidence ->> 'rate'::text))::numeric(19,10) = rate) AND ((evidence ->> 'source'::text) = source) AND (((evidence ->> 'quoted_at'::text))::timestamp with time zone = quoted_at) AND ((evidence ->> 'inputs_hash'::text) = inputs_hash))),
    CONSTRAINT saas_metrics_fx_evidence_source_valid CHECK ((source = ANY (ARRAY['manual'::text, 'bank_of_canada'::text, 'ecb'::text, 'open_exchange_rates'::text])))
);

ALTER TABLE ONLY public.saas_metrics_fx_evidence FORCE ROW LEVEL SECURITY;


