-- Name: TABLE saas_metrics_fx_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.saas_metrics_fx_evidence IS 'Append-only reproducible FX observations for SaaS normalization. Evidence documents replay the quotation; rows are never updated or deleted.';


--
-- Name: saas_metrics_fx_evidence; Type: VIEW; Schema: openbooks_query; Owner: -
