    rate,
    source,
    quoted_at,
    evidence,
    inputs_hash,
    created_at,
    created_by
   FROM public.saas_metrics_fx_evidence
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: saas_metrics_monthly; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.saas_metrics_monthly (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    subsidiary_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    month date NOT NULL,
    cohort_month date NOT NULL,
    mrr_start numeric(19,4) NOT NULL,
    mrr_end numeric(19,4) NOT NULL,
    new_mrr numeric(19,4) NOT NULL,
    expansion_mrr numeric(19,4) NOT NULL,
    contraction_mrr numeric(19,4) NOT NULL,
    churned_mrr numeric(19,4) NOT NULL,
    reactivation_mrr numeric(19,4) NOT NULL,
    movement text NOT NULL,
    recognized_revenue numeric(19,4) NOT NULL,
    deferred_delta numeric(19,4) NOT NULL,
    inputs_hash text NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    reporting_currency text,
    denomination_version text,
    normalization_evidence jsonb,
    CONSTRAINT saas_metrics_monthly_month_start CHECK (((EXTRACT(day FROM month) = (1)::numeric) AND (EXTRACT(day FROM cohort_month) = (1)::numeric))),
    CONSTRAINT saas_metrics_monthly_movement_identity CHECK (((mrr_end - mrr_start) = ((((new_mrr + expansion_mrr) + reactivation_mrr) - contraction_mrr) - churned_mrr))),
    CONSTRAINT saas_metrics_monthly_movement_valid CHECK ((movement = ANY (ARRAY['new'::text, 'expansion'::text, 'contraction'::text, 'churn'::text, 'reactivation'::text, 'flat'::text]))),
    CONSTRAINT saas_metrics_monthly_nonnegative_mrr CHECK (((mrr_start >= (0)::numeric) AND (mrr_end >= (0)::numeric) AND (new_mrr >= (0)::numeric) AND (expansion_mrr >= (0)::numeric) AND (contraction_mrr >= (0)::numeric) AND (churned_mrr >= (0)::numeric) AND (reactivation_mrr >= (0)::numeric))),
    CONSTRAINT saas_metrics_monthly_norm_complete CHECK ((((reporting_currency IS NULL) AND (denomination_version IS NULL) AND (normalization_evidence IS NULL)) OR ((reporting_currency IS NOT NULL) AND (denomination_version IS NOT NULL) AND (normalization_evidence IS NOT NULL)))),
    CONSTRAINT saas_metrics_monthly_norm_shape CHECK (((reporting_currency IS NULL) OR ((reporting_currency ~ '^[A-Z]{3}$'::text) AND (denomination_version ~ '^v[0-9]+$'::text) AND (char_length(denomination_version) <= 64) AND (jsonb_typeof(normalization_evidence) = 'object'::text) AND ((normalization_evidence ->> 'inputs_hash'::text) ~ '^[0-9a-f]{64}$'::text))))
);

ALTER TABLE ONLY public.saas_metrics_monthly FORCE ROW LEVEL SECURITY;


