-- Name: TABLE saas_metrics_monthly; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.saas_metrics_monthly IS 'Monthly subscription revenue facts. mrr_start and mrr_end are stocks; movement amounts, recognized_revenue, and deferred_delta are flows.';


