   FROM public.saas_metrics_monthly
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: saas_metrics_normalization_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.saas_metrics_normalization_requests (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    month date NOT NULL,
    reason text NOT NULL,
    requested_by uuid NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    idempotency_key uuid NOT NULL,
    request_hash text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    progress jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb,
    failure text,
    remedy text,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_heartbeat_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT saas_metrics_normalization_requests_approved_pair CHECK (((approved_by IS NULL) = (approved_at IS NULL))),
    CONSTRAINT saas_metrics_normalization_requests_approver_distinct CHECK (((approved_by IS NULL) OR (approved_by <> requested_by))),
    CONSTRAINT saas_metrics_normalization_requests_attempt_nonnegative CHECK ((attempt_count >= 0)),
    CONSTRAINT saas_metrics_normalization_requests_lease_pair CHECK (((lease_token IS NULL) = (lease_expires_at IS NULL))),
    CONSTRAINT saas_metrics_normalization_requests_month_start CHECK ((EXTRACT(day FROM month) = (1)::numeric)),
    CONSTRAINT saas_metrics_normalization_requests_outcome_shape CHECK ((((status = ANY (ARRAY['pending'::text, 'running'::text, 'cancelled'::text])) AND (result IS NULL) AND (failure IS NULL) AND (remedy IS NULL)) OR ((status = 'succeeded'::text) AND (result IS NOT NULL) AND (failure IS NULL) AND (remedy IS NULL)) OR ((status = 'failed'::text) AND (result IS NULL) AND (failure IS NOT NULL) AND (remedy IS NOT NULL) AND (btrim(failure) <> ''::text) AND (btrim(remedy) <> ''::text)))),
    CONSTRAINT saas_metrics_normalization_requests_reason_nonblank CHECK (((char_length(btrim(reason)) >= 8) AND (char_length(btrim(reason)) <= 1000))),
    CONSTRAINT saas_metrics_normalization_requests_request_hash_digest CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT saas_metrics_normalization_requests_status_valid CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.saas_metrics_normalization_requests FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE saas_metrics_normalization_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.saas_metrics_normalization_requests IS 'Guarded SaaS normalization request lifecycle. The row owns current fenced liveness; append-only attempt history lives in audit_log.';


--
-- Name: saas_metrics_normalization_requests; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.saas_metrics_normalization_requests WITH (security_barrier='true') AS
 SELECT id,
    org_id,
