    idempotency_key,
    request_hash,
    status,
    progress,
    result,
    failure,
    remedy,
    lease_token,
    lease_expires_at,
    attempt_count,
    last_heartbeat_at,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.saas_metrics_normalization_requests
  WHERE (org_id = public.openbooks_query_org_id());


