--
-- Name: tax_filings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_filings (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    form_code text NOT NULL,
    form_name text NOT NULL,
    country text,
    period_from date NOT NULL,
    period_to date NOT NULL,
    version integer NOT NULL,
    status text DEFAULT 'prepared'::text NOT NULL,
    submission_channel text NOT NULL,
    boxes jsonb NOT NULL,
    adjustments jsonb DEFAULT '{}'::jsonb NOT NULL,
    snapshot_hash text NOT NULL,
    filing_reference text,
    filed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    functional_currency text,
    presentation_currency text,
    translation jsonb,
    subsidiary_ids uuid[],
    registration_id uuid,
    registration_number text,
    snapshot_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT tax_filings_boxes_check CHECK ((jsonb_typeof(boxes) = 'array'::text)),
    CONSTRAINT tax_filings_dates_check CHECK ((period_from <= period_to)),
    CONSTRAINT tax_filings_filed_state_check CHECK ((((status = 'prepared'::text) AND (filed_at IS NULL)) OR ((status = 'filed'::text) AND (filed_at IS NOT NULL)))),
    CONSTRAINT tax_filings_snapshot_hash_check CHECK ((snapshot_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tax_filings_status_check CHECK ((status = ANY (ARRAY['prepared'::text, 'filed'::text]))),
    CONSTRAINT tax_filings_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY public.tax_filings FORCE ROW LEVEL SECURITY;


--
-- Name: COLUMN tax_filings.functional_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.functional_currency IS 'Frozen denomination of the stored boxes (0265): the filing entity functional currency, or the presentation currency for a translated view. Backfilled where the org posture is unambiguous; NULL means pre-snapshot and ambiguous — readers must refuse, never substitute the current org base.';


--
-- Name: COLUMN tax_filings.presentation_currency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.presentation_currency IS 'Declared presentation currency of a translated consolidated view (0265); NULL for single-currency returns.';


--
-- Name: COLUMN tax_filings.translation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.translation IS 'Translation evidence for a translated consolidated view (0265): rate source, rate date and per-entity applied rates. NULL for single-currency returns.';


--
-- Name: COLUMN tax_filings.subsidiary_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.subsidiary_ids IS 'Frozen filing-entity scope (0265): the subsidiary set the return summed. NULL means pre-snapshot (unknown scope — v1 semantics); an empty array is the legacy degenerate org-wide return.';


--
-- Name: COLUMN tax_filings.registration_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.registration_id IS 'Frozen filing identity (0265): the tax_registrations row whose number travels on the return. NULL means pre-snapshot or unregistered.';


--
-- Name: COLUMN tax_filings.registration_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.registration_number IS 'Frozen filing identity (0265): the government registration number printed on the return. NULL means pre-snapshot or unregistered.';


--
-- Name: COLUMN tax_filings.snapshot_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tax_filings.snapshot_version IS 'Snapshot schema version (0265): 1 hashed form/period/channel/boxes/adjustments only; 2 additionally hashes registration, currency and scope posture. Existing rows stay 1 so they verify exactly as prepared.';


--
-- Name: tax_filings; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.tax_filings WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    form_code,
    form_name,
    country,
    period_from,
    period_to,
    version,
    status,
    submission_channel,
    boxes,
    adjustments,
    snapshot_hash,
    filing_reference,
    filed_at,
    created_at,
    created_by,
    updated_at,
    updated_by,
    functional_currency,
    presentation_currency,
    translation,
    subsidiary_ids,
    registration_id,
    registration_number,
    snapshot_version
   FROM public.tax_filings
  WHERE (org_id = public.openbooks_query_org_id());


