    base_captured boolean DEFAULT false NOT NULL,
    CONSTRAINT change_set_items_captured_base_valid CHECK (((NOT base_captured) OR COALESCE((((op = 'insert'::text) AND (expected_before IS NULL)) OR ((op = ANY (ARRAY['update'::text, 'delete'::text])) AND (expected_before IS NOT NULL) AND (jsonb_typeof(expected_before) = 'object'::text) AND ((expected_before ->> 'id'::text) = (target_id)::text) AND ((expected_before ->> 'org_id'::text) = (org_id)::text))), false)))
);

