-- Name: change_sets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.change_sets (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    sandbox_org_id uuid NOT NULL,
    name text NOT NULL,
    description text,
    status text DEFAULT 'draft'::text NOT NULL,
    applied_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    capture_complete boolean DEFAULT false NOT NULL,
    item_count integer DEFAULT 0 NOT NULL,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    approved_at timestamp with time zone,
    approved_by uuid,
    applied_by uuid,
    CONSTRAINT change_sets_actor_separation CHECK ((((created_by IS NULL) OR (reviewed_by IS NULL) OR (created_by <> reviewed_by)) AND ((created_by IS NULL) OR (approved_by IS NULL) OR (created_by <> approved_by)) AND ((created_by IS NULL) OR (applied_by IS NULL) OR (created_by <> applied_by)) AND ((reviewed_by IS NULL) OR (approved_by IS NULL) OR (reviewed_by <> approved_by)) AND ((reviewed_by IS NULL) OR (applied_by IS NULL) OR (reviewed_by <> applied_by)) AND ((approved_by IS NULL) OR (applied_by IS NULL) OR (approved_by <> applied_by)))),
    CONSTRAINT change_sets_apply_evidence CHECK (((status <> 'applied'::text) OR (applied_at IS NOT NULL))),
    CONSTRAINT change_sets_approval_evidence CHECK (((status = ANY (ARRAY['draft'::text, 'reviewed'::text, 'discarded'::text])) OR ((approved_at IS NOT NULL) AND (approved_by IS NOT NULL)) OR ((status = 'applied'::text) AND (approved_at IS NULL) AND (approved_by IS NULL) AND (applied_by IS NULL)))),
    CONSTRAINT change_sets_capture_lifecycle CHECK (((status = ANY (ARRAY['draft'::text, 'discarded'::text])) OR capture_complete)),
    CONSTRAINT change_sets_item_count_nonnegative CHECK ((item_count >= 0)),
    CONSTRAINT change_sets_review_evidence CHECK (((status = ANY (ARRAY['draft'::text, 'discarded'::text])) OR ((reviewed_at IS NOT NULL) AND (reviewed_by IS NOT NULL)) OR ((status = 'applied'::text) AND (reviewed_at IS NULL) AND (reviewed_by IS NULL) AND (applied_by IS NULL)))),
    CONSTRAINT change_sets_status_valid CHECK ((status = ANY (ARRAY['draft'::text, 'reviewed'::text, 'approved'::text, 'applied'::text, 'discarded'::text])))
);

ALTER TABLE ONLY public.change_sets FORCE ROW LEVEL SECURITY;


