    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    position_id uuid,
    CONSTRAINT employment_assignment_versions_closure CHECK ((((superseded_by IS NULL) = (recorded_until IS NULL)) AND ((superseded_by IS NULL) = (closed_by_change_id IS NULL)))),
    CONSTRAINT employment_assignment_versions_finite_time CHECK ((((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date)) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date))) AND (recorded_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND ((recorded_until IS NULL) OR ((recorded_until >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_until < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT employment_assignment_versions_fte CHECK (((fte > (0)::numeric) AND (fte <> 'NaN'::numeric))),
    CONSTRAINT employment_assignment_versions_no CHECK ((version_no >= 1)),
    CONSTRAINT employment_assignment_versions_range CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT employment_assignment_versions_recorded CHECK (((recorded_until IS NULL) OR (recorded_until > recorded_at)))
);

