    CONSTRAINT employment_changes_kind CHECK ((change_kind = ANY (ARRAY['created'::text, 'status_changed'::text, 'assignment_issued'::text, 'assignment_superseded'::text, 'corrected'::text, 'terminated'::text, 'rehired_reference'::text, 'profile_changed'::text]))),
    CONSTRAINT employment_changes_reason CHECK ((char_length(btrim(reason)) > 0)),
