    CONSTRAINT hrm_employment_change_requests_snapshot_iff_decided CHECK (((status = ANY (ARRAY['approved'::text, 'rejected'::text, 'applied'::text])) = (decision_snapshot IS NOT NULL))),
    CONSTRAINT hrm_employment_change_requests_status_valid CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'applied'::text]))),
    CONSTRAINT hrm_employment_change_requests_submission_paired CHECK (((submitted_at IS NULL) = (submitted_by IS NULL))),
    CONSTRAINT hrm_employment_change_requests_submission_presence CHECK (((status <> ALL (ARRAY['pending_approval'::text, 'approved'::text, 'rejected'::text, 'applied'::text])) OR (submitted_at IS NOT NULL))),
