--
-- Name: hrm_interview_slots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_interview_slots (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    interview_id uuid NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    timezone text NOT NULL,
    kind text DEFAULT 'proposed'::text NOT NULL,
    proposed_by uuid,
    booked_by_candidate_at timestamp with time zone,
    calendar_ref jsonb,
    candidate_token_hash text,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_interview_slots_booking_paired CHECK (((kind = 'booked'::text) = (booked_by_candidate_at IS NOT NULL))),
    CONSTRAINT hrm_interview_slots_finite_time CHECK (((starts_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (starts_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND (ends_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (ends_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND ((booked_by_candidate_at IS NULL) OR ((booked_by_candidate_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (booked_by_candidate_at < '10000-01-01 00:00:00+00'::timestamp with time zone))) AND ((expires_at IS NULL) OR ((expires_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (expires_at < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT hrm_interview_slots_kind CHECK ((kind = ANY (ARRAY['proposed'::text, 'booked'::text, 'declined'::text]))),
    CONSTRAINT hrm_interview_slots_ordered CHECK ((starts_at < ends_at)),
    CONSTRAINT hrm_interview_slots_timezone_not_blank CHECK ((char_length(btrim(timezone)) > 0))
);

ALTER TABLE ONLY public.hrm_interview_slots FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_interview_slots; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_interview_slots IS 'HRM self-scheduling slots (0229): proposed/booked/declined rows per interview. One booking link covers a proposed batch, so its SHA-256 hex repeats across the batch rows; the raw token is never stored. calendar_ref carries provider event ids — the provider is an org-declared connector, not built here.';


