    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    kit_id uuid,
    CONSTRAINT hrm_interviews_completed_paired CHECK (((status = 'completed'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT hrm_interviews_duration CHECK (((duration_minutes IS NULL) OR (duration_minutes > 0))),
    CONSTRAINT hrm_interviews_finite_time CHECK (((scheduled_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (scheduled_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND ((completed_at IS NULL) OR ((completed_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (completed_at < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT hrm_interviews_kind CHECK ((kind = ANY (ARRAY['phone'::text, 'video'::text, 'onsite'::text, 'panel'::text, 'assessment'::text]))),
    CONSTRAINT hrm_interviews_location_not_blank CHECK (((location IS NULL) OR (char_length(btrim(location)) > 0))),
    CONSTRAINT hrm_interviews_outcome CHECK (((outcome IS NULL) OR ((status = 'completed'::text) AND (outcome = ANY (ARRAY['advance'::text, 'hold'::text, 'reject'::text]))))),
    CONSTRAINT hrm_interviews_status CHECK ((status = ANY (ARRAY['scheduled'::text, 'completed'::text, 'cancelled'::text, 'no_show'::text])))
);

