--
-- Name: hrm_leave_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_leave_policies (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    applies_to jsonb DEFAULT '{"department_id": null, "employer_subsidiary_id": null}'::jsonb NOT NULL,
    accrual_rule jsonb DEFAULT '{"kind": "none"}'::jsonb NOT NULL,
    carryover_rule jsonb DEFAULT '{"kind": "none"}'::jsonb NOT NULL,
    minimum_notice_days integer DEFAULT 0 NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    applies_employer_subsidiary_id uuid GENERATED ALWAYS AS (((applies_to ->> 'employer_subsidiary_id'::text))::uuid) STORED,
    applies_department_id uuid GENERATED ALWAYS AS (((applies_to ->> 'department_id'::text))::uuid) STORED,
    accrual_kind text GENERATED ALWAYS AS ((accrual_rule ->> 'kind'::text)) STORED,
    accrual_hours text GENERATED ALWAYS AS ((accrual_rule ->> 'hours'::text)) STORED,
    accrual_periods_per_year integer GENERATED ALWAYS AS (((accrual_rule ->> 'periods_per_year'::text))::integer) STORED,
    carryover_kind text GENERATED ALWAYS AS ((carryover_rule ->> 'kind'::text)) STORED,
    carryover_hours text GENERATED ALWAYS AS ((carryover_rule ->> 'hours'::text)) STORED,
    carryover_expires_after_days integer GENERATED ALWAYS AS (((carryover_rule ->> 'expires_after_days'::text))::integer) STORED,
    CONSTRAINT hrm_leave_policies_finite_time CHECK ((((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date)) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date))))),
    CONSTRAINT hrm_leave_policies_notice CHECK ((minimum_notice_days >= 0)),
    CONSTRAINT hrm_leave_policies_window CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
);

ALTER TABLE ONLY public.hrm_leave_policies FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_leave_policies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_leave_policies IS 'HRM leave policies (0194): HR entitlement in TIME per type, with applies_to scoping and effective dating. This is not the payroll bank in VALUE; the two are never conflated.';


--
-- Name: hrm_leave_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_leave_requests (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    employment_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    hours numeric(9,2) NOT NULL,
    reason text,
    status text DEFAULT 'draft'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    flow_instance_id uuid,
    attachment_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_leave_requests_decision CHECK ((((status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL) AND (decision_reason IS NOT NULL) AND (char_length(btrim(decision_reason)) > 0)) OR ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'withdrawn'::text, 'cancelled'::text])) AND (decided_by IS NULL) AND (decided_at IS NULL)))),
    CONSTRAINT hrm_leave_requests_finite_time CHECK ((((starts_on >= '0001-01-01'::date) AND (starts_on <= '9999-12-31'::date)) AND ((ends_on >= '0001-01-01'::date) AND (ends_on <= '9999-12-31'::date)))),
    CONSTRAINT hrm_leave_requests_hours CHECK ((hours > (0)::numeric)),
    CONSTRAINT hrm_leave_requests_range CHECK ((ends_on >= starts_on)),
    CONSTRAINT hrm_leave_requests_status CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.hrm_leave_requests FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_leave_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_leave_requests IS 'HRM leave requests (0194): lifecycle draft/submitted/approved/rejected/withdrawn/cancelled. Approved requests never overlap per employment (storage exclusion); the service refuses overlapping submits first.';


--
-- Name: hrm_leave_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hrm_leave_types (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    paid boolean DEFAULT true NOT NULL,
    value_crossing text DEFAULT 'none'::text NOT NULL,
    requires_attachment boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT hrm_leave_types_code CHECK ((char_length(btrim(code)) > 0)),
    CONSTRAINT hrm_leave_types_name CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT hrm_leave_types_value_crossing CHECK ((value_crossing = ANY (ARRAY['none'::text, 'payout'::text, 'bank_in'::text])))
);

ALTER TABLE ONLY public.hrm_leave_types FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE hrm_leave_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.hrm_leave_types IS 'HRM leave-type taxonomy (0194): org-configurable, country-agnostic. value_crossing names which of the two allowed pay-run input movements (payout, bank_in) this type raises, or none. No pack declares leave types; this table is the single source of truth.';


--
-- Name: COLUMN hrm_leave_types.value_crossing; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.hrm_leave_types.value_crossing IS 'Which allowed movement this type raises as a pay-run input (none, payout, bank_in). There is no taken movement kind; unpaid or salary-paid absence never touches the ledger.';


