    CONSTRAINT hrm_one_on_ones_held_paired CHECK (((status = 'held'::text) = (held_at IS NOT NULL))),
    CONSTRAINT hrm_one_on_ones_parties_differ CHECK ((manager_employment_id <> report_employment_id)),
    CONSTRAINT hrm_one_on_ones_recurrence_shape CHECK (((recurrence IS NULL) OR ((jsonb_typeof(recurrence) = 'object'::text) AND (recurrence ? 'every_weeks'::text) AND (recurrence ? 'weekday'::text) AND (jsonb_typeof((recurrence -> 'every_weeks'::text)) = 'number'::text) AND (((recurrence ->> 'every_weeks'::text))::numeric >= (1)::numeric) AND (((recurrence ->> 'every_weeks'::text))::numeric <= (12)::numeric) AND (jsonb_typeof((recurrence -> 'weekday'::text)) = 'number'::text) AND (((recurrence ->> 'weekday'::text))::numeric >= (0)::numeric) AND (((recurrence ->> 'weekday'::text))::numeric <= (6)::numeric)))),
    CONSTRAINT hrm_one_on_ones_skip_reason CHECK (((status <> 'skipped'::text) OR ((skip_reason IS NOT NULL) AND (char_length(btrim(skip_reason)) > 0)))),
    CONSTRAINT hrm_one_on_ones_status CHECK ((status = ANY (ARRAY['scheduled'::text, 'held'::text, 'skipped'::text, 'cancelled'::text])))
);

