    CONSTRAINT hrm_requisitions_opened_paired CHECK (((status = ANY (ARRAY['draft'::text, 'cancelled'::text])) OR (opened_on IS NOT NULL))),
    CONSTRAINT hrm_requisitions_revision CHECK ((revision >= 1)),
    CONSTRAINT hrm_requisitions_status CHECK ((status = ANY (ARRAY['draft'::text, 'open'::text, 'on_hold'::text, 'filled'::text, 'cancelled'::text]))),
