    CONSTRAINT pay_component_earning_classifications_exemption_category CHECK (((statutory_exemption_category IS NULL) OR (statutory_exemption_category = ANY (ARRAY['military_pay'::text, 'rail_carrier'::text, 'motor_carrier'::text, 'air_carrier'::text, 'seafarer'::text])))),
    CONSTRAINT pay_component_earning_classifications_reporting_category CHECK (((statutory_reporting_category IS NULL) OR (statutory_reporting_category ~ '^[a-z][a-z0-9_]{0,63}$'::text))),
    CONSTRAINT pay_component_earning_classifications_supplemental_category CHECK (((supplemental_wage_category IS NULL) OR (supplemental_wage_category = ANY (ARRAY['bonus_or_stock_option'::text, 'other'::text]))))
);

