--
-- Name: position_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.position_changes (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    position_id uuid NOT NULL,
    revision integer NOT NULL,
    change_kind text NOT NULL,
    prior_snapshot jsonb NOT NULL,
    reason text NOT NULL,
    recorded_source text DEFAULT 'user'::text NOT NULL,
    recorded_by uuid,
    recorded_source_ref text,
    change_txid bigint NOT NULL,
    closed_versions jsonb DEFAULT '[]'::jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT position_changes_actor CHECK ((((recorded_source = 'user'::text) AND (recorded_by IS NOT NULL) AND (recorded_source_ref IS NULL)) OR ((recorded_source = 'system'::text) AND (recorded_by IS NULL) AND (recorded_source_ref IS NOT NULL) AND (char_length(btrim(recorded_source_ref)) > 0)))),
    CONSTRAINT position_changes_closed_versions CHECK ((jsonb_typeof(closed_versions) = 'array'::text)),
    CONSTRAINT position_changes_finite_time CHECK (((recorded_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_at < '10000-01-01 00:00:00+00'::timestamp with time zone))),
    CONSTRAINT position_changes_kind CHECK ((change_kind = ANY (ARRAY['created'::text, 'revised'::text, 'funded'::text, 'assigned'::text, 'unassigned'::text, 'closed'::text]))),
    CONSTRAINT position_changes_reason CHECK ((char_length(btrim(reason)) > 0)),
    CONSTRAINT position_changes_revision CHECK ((revision >= 1)),
    CONSTRAINT position_changes_snapshot CHECK ((jsonb_typeof(prior_snapshot) = 'object'::text))
);

ALTER TABLE ONLY public.position_changes FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE position_changes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.position_changes IS 'HRM immutable position revision evidence (0192): every position write appends one row with prior image, non-blank reason, and a users row or named system source. Updates and deletes rejected (position_changes_immutable_guard).';


--
-- Name: position_funding; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.position_funding (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    position_id uuid NOT NULL,
    period_id uuid NOT NULL,
    funded_fte numeric(7,4) NOT NULL,
    funding_source_id uuid,
    amount numeric(19,4),
    currency text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT position_funding_amount_currency CHECK ((((amount IS NULL) AND (currency IS NULL)) OR ((amount IS NOT NULL) AND (currency IS NOT NULL) AND (amount <> 'NaN'::numeric) AND (currency ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT position_funding_funded_fte CHECK (((funded_fte >= (0)::numeric) AND (funded_fte <> 'NaN'::numeric)))
);

ALTER TABLE ONLY public.position_funding FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE position_funding; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.position_funding IS 'HRM headcount-plan funding (0192): one plan row per position and fiscal period (accounting_periods, budget-style reference) with funded FTE and an optional cost-plan amount. funded_fte >= 0 only: the plan-vs-funded comparison is a service preflight, never a row rejection.';


--
-- Name: COLUMN position_funding.funding_source_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.position_funding.funding_source_id IS 'Opaque planning-dimension reference (cost center, grant, program): carried for planning joins, never resolved by HRM. Null = unfunded by a named source.';


--
-- Name: position_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.position_versions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    position_id uuid NOT NULL,
    version_no integer NOT NULL,
    title text NOT NULL,
    department_id uuid,
    location_id uuid,
    employer_subsidiary_id uuid NOT NULL,
    job_grade text,
    planned_fte numeric(7,4) NOT NULL,
    status text NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_until timestamp with time zone,
    superseded_by integer,
    closed_by_change_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    job_level_id uuid,
    CONSTRAINT position_versions_closure CHECK ((((superseded_by IS NULL) = (recorded_until IS NULL)) AND ((superseded_by IS NULL) = (closed_by_change_id IS NULL)))),
    CONSTRAINT position_versions_finite_time CHECK ((((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date)) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date))) AND (recorded_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND ((recorded_until IS NULL) OR ((recorded_until >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_until < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT position_versions_no CHECK ((version_no >= 1)),
    CONSTRAINT position_versions_planned_fte CHECK (((planned_fte > (0)::numeric) AND (planned_fte <> 'NaN'::numeric))),
    CONSTRAINT position_versions_range CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT position_versions_recorded CHECK (((recorded_until IS NULL) OR (recorded_until > recorded_at))),
    CONSTRAINT position_versions_status CHECK ((status = ANY (ARRAY['planned'::text, 'open'::text, 'filled'::text, 'frozen'::text, 'closed'::text]))),
    CONSTRAINT position_versions_title_not_blank CHECK ((char_length(btrim(title)) > 0))
);

ALTER TABLE ONLY public.position_versions FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE position_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.position_versions IS 'HRM position versions (0192): title, placement, employer, grade, planned FTE and lifecycle status with half-open effective [effective_from, effective_to) and recorded [recorded_at, recorded_until) intervals. Live versions never overlap per position (position_versions_no_overlap); closed rows immutable (closure guard).';


--
-- Name: COLUMN position_versions.job_level_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.position_versions.job_level_id IS 'HR-12 job architecture (0221): the rung this version of the position sits on. Employment versions read their band through the position at the as-of date — band ids are never copied onto employments.';


