    CONSTRAINT posting_effects_terminal_evidence CHECK ((((status = 'terminal_failed'::text) AND (terminal_failure_reason IS NOT NULL) AND (length(btrim(terminal_failure_reason)) > 0) AND (terminal_failed_at IS NOT NULL) AND (terminal_failed_by IS NOT NULL)) OR (status <> 'terminal_failed'::text)))
);

