    CONSTRAINT scheduler_outbox_scope CHECK ((((kind = 'approval_escalation'::text) AND (org_id IS NOT NULL) AND (subject_id IS NOT NULL)) OR ((kind = ANY (ARRAY['dunning'::text, 'subscription_billing'::text, 'property_billing'::text, 'fx_providers'::text, 'saas_metrics'::text])) AND (org_id IS NULL) AND (subject_id IS NULL)) OR ((kind = 'flow_email'::text) AND (org_id IS NOT NULL) AND (subject_id IS NOT NULL) AND (payload IS NOT NULL)) OR ((kind = 'allocation_run'::text) AND (org_id IS NOT NULL) AND (subject_id IS NOT NULL) AND (payload IS NOT NULL)))),
