--
-- Name: worker_employment_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worker_employment_versions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    employment_id uuid NOT NULL,
    version_no integer NOT NULL,
    status text NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_until timestamp with time zone,
    superseded_by integer,
    closed_by_change_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT worker_employment_versions_closure CHECK ((((superseded_by IS NULL) = (recorded_until IS NULL)) AND ((superseded_by IS NULL) = (closed_by_change_id IS NULL)))),
    CONSTRAINT worker_employment_versions_finite_time CHECK ((((effective_from >= '0001-01-01'::date) AND (effective_from <= '9999-12-31'::date)) AND ((effective_to IS NULL) OR ((effective_to >= '0001-01-01'::date) AND (effective_to <= '9999-12-31'::date))) AND (recorded_at >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_at < '10000-01-01 00:00:00+00'::timestamp with time zone) AND ((recorded_until IS NULL) OR ((recorded_until >= '0001-01-01 00:00:00+00'::timestamp with time zone) AND (recorded_until < '10000-01-01 00:00:00+00'::timestamp with time zone))))),
    CONSTRAINT worker_employment_versions_no CHECK ((version_no >= 1)),
    CONSTRAINT worker_employment_versions_range CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT worker_employment_versions_recorded CHECK (((recorded_until IS NULL) OR (recorded_until > recorded_at))),
    CONSTRAINT worker_employment_versions_status CHECK ((status = ANY (ARRAY['offered'::text, 'active'::text, 'on_leave'::text, 'suspended'::text, 'terminated'::text])))
);

ALTER TABLE ONLY public.worker_employment_versions FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE worker_employment_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.worker_employment_versions IS 'HRM employment status versions (0184): half-open effective [effective_from, effective_to) and recorded [recorded_at, recorded_until) intervals. Live versions never overlap per employment (worker_employment_versions_no_overlap + recorded_no_ambiguity); closed rows immutable (closure guard).';


--
-- Name: worker_employments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worker_employments (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    worker_party_id uuid NOT NULL,
    employer_subsidiary_id uuid NOT NULL,
    employment_number text,
    revision integer DEFAULT 1 NOT NULL,
    service_start date,
    service_start_provenance text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT worker_employments_finite_time CHECK (((service_start IS NULL) OR ((service_start >= '0001-01-01'::date) AND (service_start <= '9999-12-31'::date)))),
    CONSTRAINT worker_employments_revision CHECK ((revision >= 1)),
    CONSTRAINT worker_employments_service_start CHECK ((((service_start IS NULL) AND (service_start_provenance IS NULL)) OR ((service_start IS NOT NULL) AND (service_start_provenance IS NOT NULL) AND (char_length(btrim(service_start_provenance)) > 0))))
);

ALTER TABLE ONLY public.worker_employments FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE worker_employments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.worker_employments IS 'HRM stable employment identity (0184): one worker party employed by one legal-employer subsidiary. No status, dates, or flags: lifecycle lives in worker_employment_versions. Employer immutable (worker_employments_identity_guard); worker remap only via audited party merge. Canonical employer, no legacy projection: no backfill here; ambiguous source employer/start refused by the one-time migration, never fabricated.';


--
-- Name: COLUMN worker_employments.employer_subsidiary_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.worker_employments.employer_subsidiary_id IS 'Legal employer of this employment: the single employer of record. Transfer = terminate + rehire, never an edit (worker_employments_identity_guard).';


