--
-- Name: sftp_servers sftp_servers_root_prefix_safe; Type: CHECK CONSTRAINT; Schema: public; Owner: -
--

ALTER TABLE public.sftp_servers
    ADD CONSTRAINT sftp_servers_root_prefix_safe CHECK (((root_prefix ~ '^[^/%]+(/[^/%]+)*$'::text) AND (root_prefix !~ '\\'::text) AND (root_prefix !~ '(^|/)\.\.?(/|$)'::text))) NOT VALID;


--
-- Name: CONSTRAINT sftp_servers_root_prefix_safe ON sftp_servers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT sftp_servers_root_prefix_safe ON public.sftp_servers IS 'openbooks:root_prefix escape guard — a tenant names folders, never physical locations: relative, no backslash, no percent-encoding, no dot/empty segments. Tenant binding to sftp/<orgId>/ is enforced by the creation route and the engine storage resolver. NOT VALID: legacy non-conforming rows keep their exact prior prefix as quarantine evidence; any UPDATE re-validates, so a quarantined login stays deactivated until remediated.';


