--
-- Name: file_blobs file_blobs_org_isolation; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY file_blobs_org_isolation ON public.file_blobs USING ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (EXISTS ( SELECT 1
   FROM (public.file_versions fv
     JOIN public.files f ON ((f.id = fv.file_id)))
  WHERE ((fv.id = file_blobs.version_id) AND ((f.org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting))))))) WITH CHECK ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (EXISTS ( SELECT 1
   FROM (public.file_versions fv
     JOIN public.files f ON ((f.id = fv.file_id)))
  WHERE ((fv.id = file_blobs.version_id) AND ((f.org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting)))))));


--
-- Name: file_versions; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.file_versions ENABLE ROW LEVEL SECURITY;

--
-- Name: file_versions file_versions_org_isolation; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY file_versions_org_isolation ON public.file_versions USING ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (EXISTS ( SELECT 1
   FROM public.files f
  WHERE ((f.id = file_versions.file_id) AND ((f.org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting))))))) WITH CHECK ((( SELECT public.app_bypass_rls_active() AS app_bypass_rls_active) OR (EXISTS ( SELECT 1
   FROM public.files f
  WHERE ((f.id = file_versions.file_id) AND ((f.org_id)::text = ( SELECT current_setting('app.current_org'::text, true) AS current_setting)))))));


